	["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}：交齐全部九具搁浅的遗骸后，{npc:10219}会提供这个任务",
	["{quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "{quest:948}是古树之林中的古树，{npc:270269}和{npc:11218}在他旁边沉睡。",
	["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394}（暗夜精灵）和{npc:272054}（天裔）在{area:493}南部等候。三件遗物在它们东边的{area:2363}里。最初几周的报告称：其他玩家正在拾取某件遗物时，你拾取不到东西：稍等片刻再试。",
}

G["forever/alliance/03-loch-modan"] = {
	["12 minutes"] = "12分钟",
	["Back down into town: {npc:415} by the smithy, {npc:341} at the north end of the bridge, {npc:381} on the docks."] = "下山回镇：{npc:415}在铁匠铺旁，{npc:341}在桥北端，{npc:381}在码头。",
	["Back north to {npc:234} and the gryphons."] = "向北返回{npc:234}和狮鹫处。",
	["Back north up the road to {area:108}. {npc:467} waits at the foot of the tower ramp; if he is missing, someone is escorting him and he is back within minutes."] = "向北沿路返回{area:108}。{npc:467}在通往塔的坡道底部；如果不在，就是有人正在护送他，几分钟内便会回来。",
	["Back to the {area:925}"] = "返回{area:925}",
	["Back to {area:442} for {zone:1439}'s southern loops: the gryphon to {zone:1453}, then the boat from the harbour."] = "返回{area:442}，继续{zone:1439}南部的路线：先乘狮鹫到{zone:1453}，再从港口坐船。",
	["Back toward town, swim east from the bridge into {area:68}; the chest lies on the lake bed beside a sunken boat. Murloc Flesheaters and Tidecallers line the south shore around it: any of them can carry a {item:1467}."] = "往镇子方向走，从桥边向东游入{area:68}；箱子在湖底的一艘沉船旁。鱼人食腐者和Tidecallers分布在附近南岸，都可能携带{item:1467}。",
	["Back west along the south shore to {area:144}: {npc:1105} by the inn, then {npc:1572} with the gryphons on the west side of town, on the way south."] = "沿南岸向西返回{area:144}：先找旅店旁的{npc:1105}，再找镇子西侧狮鹫旁的{npc:1572}，之后继续向南。",
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Cathedral of Light"] = "光明大教堂",
	["Chief Engineer Hinderweir stands on top of the dam, up the ramp at its west end."] = "主工程师辛德维尔七世站在大坝顶上，从西端的坡道上去。",
	["Cross the long bridge north into town: {npc:8965} and {npc:8962} play by the shore at its north end, {npc:341} and {npc:382} stand there too, {npc:415} by the smithy, {npc:344} in the town hall, {npc:381} on the docks, {npc:266} upstairs in the inn and {npc:379} and {npc:343} inside it."] = "向北穿过长桥进镇：{npc:8965}和{npc:8962}在桥北端的岸边玩耍，{npc:341}和{npc:382}也在那里；{npc:415}在铁匠铺旁，{npc:344}在镇公所，{npc:381}在码头，{npc:266}在旅店楼上，{npc:379}和{npc:343}也在旅店内。",
	["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level."] = "{npc:121}和迪菲亚拳匪在{area:20}巡逻；迪菲亚路霸（17级）成对巡逻其南边和东边的山丘：把它们分开拉。铁匠铺里的{area:1581}入口是小队地下城。\n小心：山丘上的营地有混编的迪菲亚，如果你等级低，很容易一次拉到不止一个。",
	["Down the road to {area:108}. {npc:234} stands at the top of the stone tower."] = "沿路前往{area:108}。{npc:234}站在石塔顶上。",
	["East along the hills to the mine: the Miners' League crates sit in its tunnels among the Tunnel Rat kobolds."] = "沿山丘向东前往矿洞：矿工联盟的箱子在洞内坑道中，周围有坑道鼠狗头人。",
	["East along the road to the gryphon master; {npc:1070} stands beside her."] = "沿路向东前往狮鹫管理员；{npc:1070}站在她旁边。",
	["Elder Mountain Boar"] = "老山地野猪",
	["Elder Mountain Boars and {npc:270693}"] = "老山地野猪和{npc:270693}",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} stands by the road next to her."] = "沿{area:68}南岸的道路前往狮鹫管理员。{npc:1070}就在她旁边的路边。",
	["Follow the road east out of Menethil and south through the {area:836} pass. Keep to the road: the {zone:1437} crocolisks and raptors beside it are over your level."] = "沿路向东离开米奈希尔，再向南穿过{area:836}山口。沿着大路走：路旁{zone:1437}的鳄鱼和迅猛龙等级都比你高。",
	["For {npc:1356} in {zone:1455}"] = "交给{zone:1455}的{npc:1356}",
	["For {npc:332} in {zone:1453}"] = "交给{zone:1453}的{npc:332}",
	["From level 20 {npc:381} gives {quest:150}: take it now if he offers it (otherwise on the last {area:69} stop). Its murlocs are for your next Redridge visit, at about 24."] = "20级起，{npc:381}会提供{quest:150}：如果现在能接就接下（否则留到最后一次停靠{area:69}时）。任务鱼人留到下次约24级来赤脊山时再打。",
	["From the gryphons, over the bridge into town: {npc:415} by the smithy, {npc:344} in the town hall."] = "从狮鹫处过桥进镇：{npc:415}在铁匠铺旁，{npc:344}在镇公所。",
	["From the tram, leave {zone:1453} by the main gate and follow the road through {area:87} and east through Elwynn to Redridge."] = "下地铁后从正门离开{zone:1453}，沿路穿过{area:87}，再向东穿越艾尔文森林，前往赤脊山。",
	["Headsplitter"] = "劈头者",
	["Into {zone:1426}"] = "进入{zone:1426}",
	["Into {zone:1432}"] = "进入{zone:1432}",
	["Into {zone:1455}"] = "进入{zone:1455}",
	["Its pikes and rivets come from the gnolls north of the lake, on the loop after {area:40}"] = "它的长矛和铆钉来自湖以北的豺狼人，在{area:40}之后的环线上",
	["Its pikes and rivets come from the gnolls north of the lake, on the loop after {zone:1436}"] = "所需的铁矛和铁铆钉由湖北面的豺狼人掉落，完成{zone:1436}后绕行时再收集",
	["Mountain Buzzard"] = "山地秃鹫",
	["Mountain Buzzards"] = "山鹫",
	["Mountain Buzzards circle the hills west and south of the lodge, back toward the dig. {quest:257} runs for 15 minutes."] = "山鹫在小屋西面和南面、通往挖掘场的山丘间盘旋。{quest:257}限时15分钟。",
	["North-east to the lodge on the hill. {npc:1154} stands inside, {npc:1187} outside."] = "向东北前往山上的小屋。{npc:1154}在屋内，{npc:1187}在屋外。",
	["Off the boat, walk up the pier to the flight master by the inn. Nothing to take here yet: Menethil's quests are for your {zone:1437} visit at about 22."] = "下船后沿码头前往旅店旁的飞行管理员。这里暂时没有要接的任务：米奈希尔的任务留到约22级来{zone:1437}时再做。",
	["Redridge Brute"] = "赤脊蛮兵",
	["Redridge Brutes and Mystics hold the hills north and north-west of town; both carry the Iron Pikes and Rivets. Black Dragon Whelps nest in the same hills.\nCareful: The whelps cast {spell:133} from range, and the gnolls run for help at low health."] = "赤脊山蛮兵和赤脊山秘法师占据镇子北面和西北的山丘，两者都携带铁矛和铁铆钉。黑龙雏龙也栖息在这片山丘。\n小心：雏龙会在远处施放{spell:133}，豺狼人则会在生命值低时逃跑求援。",
	["Redridge Mongrel"] = "赤脊杂种",
	["Redridge Mongrels and Thrashers hold the hills east of {area:1002}, north of the road; Poachers camp south of the road. Great Goretusks root around the same hills and Dire Condors circle south of the lake; Tarantulas crawl round {area:1002}."] = "混血赤脊山豺狼人和赤脊山鞭笞者占据{area:1002}东面、道路以北的山丘；赤脊山偷猎者扎营在道路以南。巨型血牙野猪在同一片山丘觅食，恐鹫在湖南面盘旋；狼蛛出没于{area:1002}周围。",
	["Redridge Mystic"] = "赤脊秘法师",
	["Redridge Poacher"] = "赤脊偷猎者",
	["Right-click the {quest:86613}"] = "右键点击{quest:86613}",
	["Round the south end of the loch and head east to the dig. {npc:1345} and {npc:1344} stand together at its west edge."] = "绕过湖南端，向东前往挖掘场。{npc:1345}和{npc:1344}一起站在挖掘场西侧。",
	["Sell and repair in {area:442} first: the next stretch is a long one."] = "先在{area:442}卖杂物并修理装备：接下来有一段很长的路。",
	["South along the road to {area:20}. The {npc:550} starts in front of the {area:20} smithy and walks north to the {area:113} and the back of the {area:111}, then back: look along his road. Slow him when he runs at 30% health."] = "沿路向南前往{area:20}。{npc:550}从{area:20}铁匠铺前出发，向北走到{area:113}和{area:111}后方，再原路返回：沿这条路线寻找。他在生命值降至30%时会逃跑，记得减速。",
	["South along the west shore. A {object:665289} lies on the loch bed east of {area:144} (it moves between several spots): open it for the {item:278051}, which starts the quest."] = "沿西岸向南。{area:144}以东的湖底有一个{object:665289}（它会在几个位置间移动）：打开它取得{item:278051}，用它开启任务。",
	["South of Thelsamar, Ylva lies dead in the mouth of a trogg cave. Take her banner, raise it beside her and hold the spot: troggs come in waves from both sides, then {npc:269185}."] = "塞尔萨玛南边，伊尔瓦的遗体躺在一个穴居人洞口。拿起她的旗帜，在遗体旁竖起并守住：穴居人会从两侧分波来袭，最后出现{npc:269185}。",
	["South-west from {area:20} to the lighthouse on the point: {npc:392} waits on its steps. {npc:391} walks the beach and the shallows north-east of it among the murlocs: pull him away from the Oracles."] = "从{area:20}向西南前往岬角上的灯塔：{npc:392}在台阶上。{npc:391}在灯塔东北的海滩和浅水区、鱼人之间游荡：把他拉离Oracles再打。",
	["Stay with the traitor as he walks south to {area:20}; he does not stop for fights, so clear what follows him. His walk ends at the Defias hideout below {area:20}."] = "跟着叛徒向南走到{area:20}；他不会停下来等战斗结束，记得清掉追他的怪。他最后会走到{area:20}下方的迪菲亚藏身处。",
	["Stonesplinter Diggers, Geomancers and Berserk Troggs hold the dig east of Ironband; any of them can drop a {item:2636}. Piles of Excavation Tools lie around the dig: open one and right-click the tools to start {quest:86613}, then gather six.\nCareful: Berserk Troggs (19-20) enrage below 40% health."] = "铁环东面的挖掘场被碎石怪掘地工、碎石怪地卜师和狂暴穴居人占据，它们都可能掉落{item:2636}。挖掘场四处分布着挖掘工具堆：打开一堆，右键点击工具接取{quest:86613}，然后收集六份。\n小心：狂暴穴居人（19-20级）在生命值低于40%时会狂暴。",
	["The Elder Mountain Boars roam the hills north-west of the lodge, along the east shore. {npc:270693}, a crocolisk, patrols the shore below them. {quest:258} runs for 12 minutes."] = "老山地野猪在旅舍西北、沿东岸的丘陵游荡。{npc:270693}是一只鳄鱼，在它们下方的岸边巡逻。{quest:258}持续12分钟。",
	["The dig site"] = "挖掘场",
	["The loch"] = "洛克湖",
	["The road crosses into Redridge at {area:1002}. {npc:464} walks around the crossroads."] = "这条路在{area:1002}进入赤脊山。{npc:464}在路口附近走动。",
	["The tunnel post"] = "隧道哨所",
	["The {npc:550}"] = "{npc:550}",
	["The {object:257}"] = "{object:257}",
	["Then west under the bridge: a {object:154357} mound on the lake bed beside town holds the necklace. Only one mound shows at a time, anywhere from under the dock to past the bridge."] = "然后向西游到桥下：镇子旁的湖底有一堆{object:154357}，项链就在里面。每次只出现一堆，可能在码头下方到桥另一侧之间的任何位置。",
	["Through the South Gate tunnel and west along the road to {zone:1455}."] = "穿过南门隧道，沿路向西到{zone:1455}。",
	["Through the South Gate tunnel and west along the road to {zone:1455}. Know the {zone:1455} flight path already? Fly from {area:144} instead: these two waypoints drop once you are in the city."] = "穿过南门隧道，沿路向西前往{zone:1455}。已经开通{zone:1455}的飞行路线了？那就从{area:144}直接飞过去：进城后这两个路径点会自动跳过。",
	["Through town east to west: {npc:8962} and {npc:341} at the north end of the bridge, {npc:381} on the docks, then {npc:342}'s garden at the west end; {npc:379} and {npc:343} are in the inn."] = "从东向西穿过镇子：{npc:8962}和{npc:341}在桥北端，{npc:381}在码头，然后去镇子西端{npc:342}的花园；{npc:379}和{npc:343}在旅店内。",
	["Tram to {zone:1453}"] = "乘地铁前往{zone:1453}",
	["Use the {item:6866} on {npc:6172}"] = "对{npc:6172}使用{item:6866}",
	["Walk east along the dam, down its eastern ramp, then back west along the foot of the dam on the land side: two Dark Iron Sappers guard the barrel. Kill them, then open the barrel: it ends this quest and starts the next."] = "沿坝顶向东走，从东端坡道下去，再沿陆地一侧的坝脚向西走：有两名黑铁工兵守着桶。杀掉他们后打开桶，完成此任务并接到下一步。",
	["West along the road to {area:1002} first; the gnolls are on the way back east."] = "先沿路向西前往{area:1002}；回来向东走时再打豺狼人。",
	["West out of Redridge by {area:1002} and along the road through Elwynn to {area:87}."] = "经{area:1002}向西离开赤脊山，沿路穿过艾尔文森林，前往{area:87}。",
	["West through Westbrook into {area:40}."] = "向西穿过西泉要塞进入{area:40}。",
	["West through Westbrook into {zone:1436}."] = "向西穿过西泉，进入{zone:1436}。",
	["West to the dwarven post at the tunnel to {zone:1426}."] = "向西前往通往{zone:1426}的隧道口矮人哨所。",
	["You have the {area:1537} flight path from {zone:1426}: back north to {area:144}'s gryphons, quicker than walking through the tunnel and across {zone:1426}."] = "你在{zone:1426}时已经开通了{area:1537}的飞行路线：向北返回{area:144}的狮鹫处，比穿过隧道再横穿{zone:1426}要快。",
	["{area:1001}: kill these as you meet them"] = "{area:1001}：沿途击杀以下目标",
	["{area:108} flight master"] = "{area:108}的飞行管理员",
	["{area:144} flight master"] = "{area:144}的飞行管理员",
	["{area:20} and the Defias hills"] = "{area:20}和迪菲亚山丘",
	["{area:69} flight master"] = "{area:69}飞行管理员",
	["{item:1081}: Tarantulas"] = "{item:1081}：狼蛛掉落",
	["{item:1221}: Black Dragon Whelps"] = "{item:1221}：黑龙雏龙掉落",
	["{item:1309}; underwater"] = "{item:1309}：在水下",
	["{item:1381}: the {npc:550}"] = "{item:1381}：{npc:550}掉落",
	["{item:254676}, from the crates around {area:20}"] = "{item:254676}，来自{area:20}周围的箱子",
	["{item:2640}, from the crates; below ground"] = "{item:2640}，开箱获得；在地下",
	["{item:280911}: Redridge Thrashers"] = "{item:280911}：赤脊山鞭笞者",
	["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：{npc:474}",
	["{npc:1154}, inside"] = "{npc:1154}，在屋内",
	["{npc:1187}: 15 minutes"] = "{npc:1187}：15分钟",
	["{npc:1343} stands at the {area:925}, at the south end of the pass."] = "{npc:1343}站在山口南端的{area:925}。",
	["{npc:1343}: {npc:1416}'s package"] = "{npc:1343}：{npc:1416}的包裹",
	["{npc:1573} keeps the gryphons in the {object:32372}; {npc:1356} is in the {object:32356}, north-east of it, on the way to the tram in {object:171524}."] = "{npc:1573}在{object:32372}照看狮鹫；{npc:1356}在其东北方向的{object:32356}内，前往{object:171524}的地铁时顺路经过。",
	["{npc:1573}, in the {object:32372}"] = "{npc:1573}，在{object:32372}",
	["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}：来自{area:442}的桑迪斯的信",
	["{npc:1684} stands on the shore north-east of town, {npc:1105} by the inn."] = "{npc:1684}站在镇子东北的岸边，{npc:1105}在旅店旁。",
	["{npc:234}, at the top of the tower"] = "{npc:234}，在塔顶",
	["{npc:261} guards the bridge on this road east, past the {area:91}: {npc:240}'s {quest:35}, from your walk through {area:87}, goes to him."] = "向东沿这条路走，经过{area:91}后，{npc:261}就在桥上值守：路过{area:87}时从{npc:240}处接的{quest:35}交给他。",
	["{npc:261}, on the bridge"] = "{npc:261}，在桥上",
	["{npc:266}, in the inn; upstairs"] = "{npc:266}，在旅店楼上",
	["{npc:332} is upstairs in the SI:7 building in {object:2100}: the stairs are hard to see at first. {npc:466} sits on his horse at the far end of the bridge outside the main gate, then back to the gryphons in the {object:2096}."] = "{npc:332}在{object:2100}的军情七处（SI:7）大楼楼上：楼梯起初不太显眼。{npc:466}骑马站在正门外桥的远端，之后返回{object:2096}的狮鹫处。",
	["{npc:332}, SI:7; upstairs"] = "{npc:332}，军情七处（SI:7）；楼上",
	["{npc:341}: {quest:98386}, for your next Redridge visit"] = "{npc:341}：{quest:98386}，留到下次来赤脊山时再做",
	["{npc:343}, inside"] = "{npc:343}：在屋内",
	["{npc:344}, in the town hall"] = "{npc:344}，在市政厅",
	["{npc:344}, in the town hall: for {npc:466} in {zone:1453}"] = "{npc:344}，在镇公所：交给{zone:1453}的{npc:466}",
	["{npc:379}, inside"] = "{npc:379}，在里面",
	["{npc:381}, on the docks"] = "{npc:381}，在码头",
	["{npc:381}, on the docks: the murlocs are for your next Redridge visit"] = "{npc:381}，在码头：鱼人留到下次来赤脊山时再打",
	["{npc:382}: the Blackrock camps are for your next Redridge visit, at about 24"] = "{npc:382}：黑石营地留到下次约24级来赤脊山时再做",
	["{npc:415}: for {npc:514} in {area:87}"] = "{npc:415}：交给{area:87}的{npc:514}",
	["{npc:464} walks around {area:1002}: look inside the circle on the map"] = "{npc:464}在{area:1002}附近巡逻：在地图标示的圆圈内寻找",
	["{npc:466}, outside the main gate"] = "{npc:466}，在正门外",
	["{npc:467}, at the foot of the tower ramp"] = "{npc:467}，在通往塔的坡道底部",
	["{npc:514} works at the {area:87} smithy."] = "{npc:514}在{area:87}的铁匠铺工作。",
	["{npc:6171}: Redemption"] = "{npc:6171}：救赎",
	["{object:665289}; underwater"] = "{object:665289}；在水下",
	["{quest:3741}; underwater"] = "{quest:3741}；在水下",
	["{quest:86613}: open a pile at the dig"] = "{quest:86613}：打开挖掘场的一堆工具",
}

G["forever/alliance/04-redridge-mountains"] = {
	["Back east through town from {npc:342}'s garden: two Wanted posters hang on the town hall doorway."] = "从{npc:342}的花园向东穿过镇子：镇公所门口挂着两张通缉告示。",
	["Back north along the road from {area:42} to {area:1002}."] = "从{area:42}沿路向北返回{area:1002}。",
	["Back to {area:12}"] = "返回{area:12}",
	["Back to {area:69}"] = "回到{area:69}",
	["Back to {zone:1429}"] = "返回{zone:1429}",
	["Blackrock Champion"] = "黑石勇士",
	["Blackrock camps"] = "黑石营地",
	["Boat to {area:17203}"] = "乘船前往{area:17203}",
	["Continue west to {quest:163}. The {object:673515} glows by the ruined house south of the road; {npc:288} hides in the house at the west end of the village."] = "继续向西到{quest:163}。{object:673515}在路南的废屋旁发光；{npc:288}藏在村子西端的房子里。",
	["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "向北过长桥进入镇子。{npc:341}和{npc:382}站在桥的北端，{npc:900}在市政厅，{npc:381}和{npc:266}在码头，{npc:343}在旅店，{npc:342}在镇子西端她的菜园里。",
	["Cross the long bridge north into town: {npc:381} on the docks, {npc:900} in the town hall, the innkeeper in the inn, {npc:342} in her garden at the west end. {npc:382}'s Blackrock quests and {quest:98386} came with you from your first Redridge visit."] = "向北过长桥进镇：{npc:381}在码头，{npc:900}在市政厅，旅店老板在旅店里，{npc:342}在西端她的花园里。{npc:382}的黑石任务和{quest:98386}是你第一次来赤脊山时带过来的。",
	["Cross the long bridge north into town: {npc:381} on the docks, {npc:900} in the town hall, {npc:342} in her garden at the west end. {npc:382}'s Blackrock quests and {quest:98386} came with you from your first Redridge visit."] = "向北过长桥进镇：{npc:381}在码头，{npc:900}在镇公所，{npc:342}在镇子西端的花园里。{npc:382}的黑石任务和{quest:98386}，是你第一次来赤脊山时接下并保留的。",
	["Fly to {area:108}"] = "飞往{area:108}",
	["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn to Redridge."] = "飞往{area:108}，向西北前往海岸：{object:177790}躺在近海的海底。然后沿路向东穿过艾尔文森林前往赤脊山。",
	["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn."] = "飞往{area:108}，向西北前往海岸：{object:177790}就在近海的海底。然后沿路向东穿过艾尔文森林。",
	["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "沿{area:68}南岸的道路走到狮鹫管理员处。{npc:1070}和{npc:903}站在她旁边的路边。",
	["Follow the road along the south shore of {area:68} to the gryphon master. {npc:903} stands by the road next to her."] = "沿{area:68}南岸的道路走到狮鹫管理员处。{npc:903}就站在她旁边的路边。",
	["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "沿道路向西北经过墓地，前往森林最西缘的{npc:311}营地。{npc:893}站在{npc:311}旁边。",
	["Follow the road south from {area:1002} into {area:10}; {area:42} lies on the east side of the forest.\nNo {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "沿路向南从{area:1002}进入{area:10}；{area:42}在森林东侧。\n没有{item:4371}做{quest:174}？{npc:3133}在{npc:276}旁的房子里出售，存货有限；{area:150}的{npc:1448}也卖。\n{npc:276}的房子在小镇东端。{npc:3133}在它旁边的房子里卖工程学商品。",
	["For {npc:302}, on the hill south-east of town"] = "交给{npc:302}，在镇子东南方的山上",
	["From the keep head back west along the lake's north shore and north up the {area:95} to {area:997}; {area:69}'s hand-ins wait for Keeshan's escort, which ends there. Blackrock Champions camp in the valley."] = "从要塞沿湖北岸向西返回，再向北沿{area:95}进入{area:997}。{area:69}的任务留到护送基沙恩后再交，护送会在镇上结束。黑石勇士在山谷里扎营。",
	["Gar'im keeps to the cave at the camps' south end with his imp and two orcs. Elite: group up if you can; solo, pull the orcs at the mouth first and interrupt his fire cast."] = "Gar'im和他的小鬼、两名兽人待在营地南端的洞穴里。这是精英，尽量组队；独自挑战时，先引出洞口的兽人，并打断他的火焰法术。",
	["Greater Tarantula"] = "巨型狼蛛",
	["Greater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "巨型狼蛛在湖东北边伐木场周围的山坡上爬行。",
	["Head back east along the road to the {area:245}."] = "沿路向东返回{area:245}。",
	["Head north out of {area:69} up the {area:95} to {area:997}. Blackrock Champions camp in the valley."] = "从{area:69}向北出发，沿{area:95}上行到{area:997}。黑石勇士在山谷中扎营。",
	["Inside"] = "室内",
	["Into {area:69} from the north with Keeshan: {npc:900} and {npc:344} in the town hall, {npc:382} and {npc:341} at the north end of the bridge, then over the bridge to {npc:903} and the gryphons."] = "随基沙恩从北边进入{area:69}：{npc:900}和{npc:344}在镇公所，{npc:382}和{npc:341}在桥北端，然后过桥去找{npc:903}和狮鹫。",
	["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "基沙恩下士躲在山谷最北端，靠近{zone:1428}边界。护送他下山回到{area:69}；途中会遭到黑石兽人伏击。",
	["Level 18 and 20 spells"] = "18级和20级法术",
	["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin.\nGreater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "鱼人食肉者和唤潮者沿桥东的南岸分布。它们任何一个都可能带着{item:1467}或鱼鳍。\n巨型狼蛛在湖东北磨坊周围的山坡上爬行。",
	["Murloc Flesheaters and Tidecallers line the south shore of {area:68}, just east of the gryphons and the bridge. Any of them can carry a fin."] = "鱼人食腐者和鱼人唤潮者分布在{area:68}南岸，就在狮鹫和桥的东边。它们都有可能掉落鱼鳍。",
	["Next: the gryphon to {area:42} for {area:10}'s second loop (05-duskwood)."] = "下一步：乘狮鹫去{area:42}，开始{area:10}的第二趟环线（05-暮色森林）。",
	["Next: the gryphon to {area:42} for {zone:1431}'s second loop (05-duskwood)."] = "接下来：乘狮鹫前往{area:42}，开始{zone:1431}的第二轮路线（05-duskwood）。",
	["North up the valley's east side. Shadowhide gnolls fill it; {npc:703} (26) and his two guards stand at its north end: clear the gnolls around him first and fight at full health. Stay out of {area:2099} to the west until the watch tower: its orcs are elite."] = "沿山谷东侧向北。谷中遍布暗皮豺狼人；{npc:703}（26）和两名卫兵在山谷北端。先清理他周围的豺狼人，以满血状态战斗。去瞭望塔之前不要进入西边的{area:2099}，里面的兽人是精英。",
	["On the road east, past the {area:91}, head north from the bridge to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "沿路向东，经过{area:91}后，从桥边向北前往{area:86}。{npc:6172}躺在湖南侧，对他使用{item:6866}。周围的迪菲亚流浪巫师会掉落{item:6846}。",
	["On the top floor"] = "在最顶层",
	["Only once {quest:97914} is handed in: for {npc:3649}, back in {area:442} (06-ashenvale)"] = "只有在交完{quest:97914}之后：交给回到{area:442}的{npc:3649}（06-灰谷）",
	["Pygmy Venom Web Spider"] = "小毒网蜘蛛",
	["Rabid Dire Wolf"] = "狂躁凶狼",
	["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders are the small spiders, and few: most crawl along the {area:1097} west of {quest:163}, fewer up north towards {npc:311}'s camp; they drop the venom too. Every ghoul of the cemetery's northern half can drop a fang. Wolves and the bigger spiders share the {zone:1436} border, so pull with care."] = "疯狂的恐狼在墓地和{npc:289}周围的树林里游荡，饥饿的恐狼则在他东北边的山丘上。小型结网毒蜘蛛体型小、数量少，大多沿{quest:163}西边的{area:1097}爬行，北边往{npc:311}营地的方向也有少量；它们同样掉落毒液。墓地北半部的所有食尸鬼都有可能掉落尖牙。狼和较大的蜘蛛都分布在{zone:1436}边界附近，引怪时要小心。",
	["Redridge Mongrel"] = "赤脊杂种",
	["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Redridge Brutes, for the Iron Pikes and Rivets, hold the hills further north; Dire Condors and Great Goretusks roam the hills east of them."] = "赤脊杂种和其他豺狼人占据着{area:1002}以东、路北的丘陵；赤脊鞭笞者在其间游荡，偷猎者扎营在路南。赤脊蛮兵（为铁矛和铆钉任务而来）占据更北的丘陵；凶暴秃鹫和巨型刺喉猪在它们东边的丘陵上游荡。",
	["Redridge Poacher"] = "赤脊偷猎者",
	["Shaman training"] = "萨满祭司训练",
	["Skeletal Mage"] = "骷髅法师",
	["Skeletal Warrior"] = "骷髅战士",
	["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {area:10} can drop a {item:2378}.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once."] = "骷髅战士和骷髅法师在{area:42}东南的坟墓间走动，位于山上{npc:302}的房子下方。{area:10}里的每个骷髅都可能掉落{item:2378}。\n小心：骷髅彼此站得很近，直接冲进去往往会一次拉好几只。",
	["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {zone:1431} can drop a {item:2378}.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once."] = "骷髅战士和骷髅法师在{area:42}东南侧的墓地游荡，就在山丘上{npc:302}房屋的下方。{zone:1431}的所有骷髅都有几率掉落{item:2378}。\n注意：骷髅站位密集，直接冲进去容易同时引到多个敌人。",
	["South-east from the mill, west of {area:1000}'s gnolls, to the Blackrock camps east of {area:2099}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite."] = "从磨坊向东南，到{area:1000}豺狼人以西，再到{area:2099}以东的黑石营地。营地里满是叛徒、步兵和先锋；待在要塞以东，那里面的兽人是精英。",
	["South-east from the mill, west of {area:1000}'s gnolls, to the Blackrock camps east of {area:2099}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite. Weapon racks and swords lie about the camps; meat haunches, grain sacks and water barrels hold the supplies."] = "从伐木场向东南走，经{area:1000}豺狼人营地的西边，前往{area:2099}东边的黑石营地。营地里遍布黑石叛节者、黑石步兵和黑石前锋；留在要塞东边，要塞里的兽人是精英。营地里散落着武器架和剑；肉块、粮袋和水桶里装着补给。",
	["Starving Dire Wolf"] = "饥饿凶狼",
	["Swim east from the bridge into {area:68}; the chest lies on the lake bed."] = "从桥边向东游进{area:68}；箱子在湖底。",
	["The Wanted poster beside it"] = "旁边的另一张通缉告示",
	["The Wanted poster by the inn"] = "旅店旁的通缉布告",
	["The Wanted poster on the town hall doorway"] = "镇公所门口的通缉告示",
	["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "墓地位于村子北边。恐怖骸骨和骸骨魔在墓地南半部游荡。精英{npc:522}在墓地间徘徊：离他远点。",
	["The hermit's shack stands in the woods north-east of the {area:492}."] = "隐士的小屋在{area:492}东北方的树林里。",
	["The keep stands beside the tower. {npc:334} (elite) waits in the keep's top room with two guards and a dragon; Blackrock Shadowcasters (elite) and Sentries stand on its west side, so pull one at a time on the way in, and hug the right wall as you enter his room so you don't pull him at once. Elite: group up if you can."] = "要塞就在塔旁。{npc:334}（精英）与两名卫兵、一条龙待在要塞顶层房间里；黑石暗影法师（精英）和黑石哨兵分布在要塞西侧。进入时逐只引怪，进他的房间时紧贴右墙，免得立即引到他。这是精英任务，尽量组队。",
	["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "松土堆在农舍南边的老树桩旁。",
	["The road east through Elwynn crosses into Redridge at {area:1002}, where the roads to Redridge, {area:10} and Elwynn meet: south to {area:10} first."] = "向东穿过艾尔文森林的道路在{area:1002}进入赤脊山，通往赤脊山、{area:10}和艾尔文森林的道路在此交汇：先往南去{area:10}。",
	["The road east through Elwynn crosses into Redridge at {area:1002}, where the roads to Redridge, {zone:1431} and Elwynn meet: south to {zone:1431} first."] = "沿艾尔文森林的道路向东，在{area:1002}进入赤脊山。这里是通往赤脊山、{zone:1431}和艾尔文森林的岔路口；先向南去{zone:1431}。",
	["The road from Elwynn enters Redridge at {area:1002}. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "来自艾尔文森林的道路在{area:1002}进入赤脊山。{npc:464}站在通往赤脊山和{zone:1431}的道路交汇处。",
	["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {area:12}."] = "{area:442}的船停靠在{area:17203}。走进城里学技能并找{npc:1646}，然后从正门出城，沿路向东穿过{area:12}。",
	["The {area:91}"] = "{area:91}",
	["The {object:31} stands at the valley's east edge."] = "{object:31}位于山谷东缘。",
	["Train, then leave by the main gate and follow the road east through {area:12}."] = "学技能，然后从正门出城，沿路向东穿过{area:12}。",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["Use the {item:6866} on {npc:6172}"] = "对{npc:6172}使用{item:6866}",
	["West to the intact watch tower beside {area:2099}: climb it and leave the Glyph in the empty jar at the top."] = "向西到{area:2099}旁那座完好的瞭望塔，登上塔顶，把雕文放进空罐子里。",
	["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺路提示：向{npc:11867}学习长柄武器（{object:2096}，1 金）；猎人的近战武器主要用于提供属性，双手武器的属性通常更多。",
	["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); two-handers level a Warrior fastest."] = "顺路提示：向{npc:11867}学习长柄武器（{object:2096}，1 金）；战士使用双手武器升级最快。",
	["for {npc:272} in {area:42}"] = "交给{area:42}的{npc:272}",
	["{area:1001}: kill these as you meet them"] = "{area:1001}：遇到就杀",
	["{area:1097}: kill these as you meet them"] = "{area:1097}：沿途击杀以下目标",
	["{area:121}: kill these as you meet them"] = "{area:121}：沿途击杀以下目标",
	["{area:492}: kill these as you meet them"] = "{area:492}：沿途击杀以下目标",
	["{area:68}'s murlocs: kill these as you meet them"] = "{area:68}的鱼人：沿途击杀这些目标",
	["{area:68}: kill these as you meet them"] = "{area:68}：遇到就杀",
	["{item:1075}: any Shadowhide gnoll"] = "{item:1075}：任何暗皮豺狼人",
	["{item:1130}: Pygmy Venom Web Spiders, Venom Web Spiders and Green Recluses"] = "{item:1130}：小型结网毒蜘蛛、结网毒蜘蛛和绿色独行蛛",
	["{item:1309}; underwater"] = "{item:1309}；水下",
	["{item:1467} on the way"] = "{item:1467}，顺路",
	["{item:15882}: the {object:177790}"] = "{item:15882}：{object:177790}",
	["{item:280839}: meat haunches, grain sacks, water barrels"] = "{item:280839}：肉块、粮袋、水桶",
	["{item:280841}: weapon racks and swords on the ground"] = "{item:280841}：武器架和地上的剑",
	["{item:280911}: Redridge Thrashers"] = "{item:280911}：赤脊山鞭笞者",
	["{item:281046}, from the {object:673515}"] = "{item:281046}，来自{object:673515}",
	["{item:4371}, from {npc:3133}, if you have none"] = "如果没有{item:4371}，向{npc:3133}购买",
	["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：{npc:474}",
	["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}：来自{area:442}的桑迪斯的信",
	["{npc:2409}, at the north end of town"] = "{npc:2409}，在镇子北端",
	["{npc:264}, in the town hall"] = "{npc:264}，在市政厅",
	["{npc:265}, in her house by the tavern; inside"] = "{npc:265}，位于旅店旁的家中，进入屋内寻找",
	["{npc:265}, inside"] = "{npc:265}：在屋内",
	["{npc:266}, by the docks; upstairs"] = "{npc:266}，码头旁；楼上",
	["{npc:267}, in the town hall"] = "{npc:267}，在市政厅",
