	["{npc:1480}, inside"] = "{npc:1480}：在屋内",
	["{npc:1571} is the flight master by Menethil's inn: you have both flight paths since your first trip east."] = "{npc:1571}是米奈希尔港旅店旁的飞行管理员；第一次东行时，你就已经开通了这两处飞行点。",
	["{npc:1573}, in the {object:32372}"] = "{npc:1573}，在{object:32372}",
	["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}：来自{area:442}的桑迪斯的信",
	["{npc:2086}, by the keep; inside"] = "{npc:2086}，位于城堡内",
	["{npc:2086}, in the keep"] = "{npc:2086}，在城堡里",
	["{npc:2092}'s quest in {zone:1455} needs level 28. If you are short of it after these hand-ins, grind the Dragonmaw orcs at the camps along the road east to {area:836} before you go on."] = "{npc:2092}在{zone:1455}的任务需要28级。如果这些任务交完还差一点，先沿东去{area:836}的路在营地里刷龙喉兽人，再继续。",
	["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093}在路边扎营；{npc:1244}站在更东边的河旁。",
	["{npc:2094} stands by the north gate."] = "{npc:2094}站在北门旁。",
	["{npc:2094}, by the north gate"] = "{npc:2094}，在北门旁",
	["{npc:2096}, by the north gate"] = "{npc:2096}，在北门旁",
	["{npc:2096}: he won't offer 305 while you carry it"] = "{npc:2096}：任务 305 已在日志中时，他不会再次提供",
	["{npc:2097}, by the north gate"] = "{npc:2097}，在北门旁",
	["{npc:2104}, by the keep"] = "{npc:2104}，要塞旁",
	["{npc:2104}, on the top floor"] = "{npc:2104}，在顶层",
	["{npc:210995} may not offer these to every class; if he doesn't, carry on.; walks around {area:1276}: the map marks where to look"] = "{npc:210995}可能不会向所有职业提供这些任务；没有任务就继续路线。他在{area:1276}附近巡逻，地图标出了寻找范围。",
	["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}'s second loop"] = "{npc:332}：交给{zone:1436}的{npc:7024}，{zone:1431}第二轮路线结束时会去",
	["{npc:3649}: Alexston's reply, if you took it in {zone:1453}"] = "{npc:3649}：亚历克斯顿的回信，如果你在{zone:1453}接了它",
	["{npc:3663}: its circles are for your next {area:331} visit, at about 28"] = "{npc:3663}：它的巡逻圈留到你下次{area:331}之行，大约28级时",
	["{npc:3663}: its circles are for your next {zone:1440} visit, at about 28"] = "{npc:3663}：法阵留到下次来{zone:1440}时处理，约28级",
	["{npc:3664} and his voidwalkers hold the {area:412} south of the shrine. Pull his guards first."] = "{npc:3664}和他的虚空行者占据着神殿南边的{area:412}。先拉他的卫兵。",
	["{npc:3691}, in the inn"] = "{npc:3691}，在旅店里",
	["{npc:3691}: {quest:990}, from {area:442} (others take it on the next {area:331} visit)"] = "{npc:3691}：{quest:990}，来自{area:442}（其他人下次{area:331}之行再接）",
	["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}：之后交给{zone:1457}的{npc:11401}",
	["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}：之后交给{zone:1455}的{npc:11406}",
	["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}：之后交给{zone:1455}的{npc:258785}",
	["{npc:3885} stands at the {area:420} on the east shore of {area:421}; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885}站在{area:421}东岸的{area:420}；{npc:210995}在湖的西岸扎营。{npc:3917}在两者之间的湖里涉水。",
	["{npc:3894}, inside"] = "{npc:3894}：在屋内",
	["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide; inside"] = "{npc:3970}：交给米奈希尔的{npc:1480}，在本指南末尾；室内",
	["{npc:3987} (25) leads the Thistlefur furbolgs at the camp north of {area:415}. Clear his guards first, one at a time.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "25 级的{npc:3987}带领蓟皮熊怪驻扎在{area:415}北侧营地。先逐个清理守卫。\n注意：拉首领时，附近熊怪通常也会参战。先清掉他巡逻路线上的熊怪，便可单独与他战斗。",
	["{npc:4080} and {npc:4077} camp on the {area:1076}, south-west of the mine."] = "{npc:4080}和{npc:4077}的营地位于矿洞西南方的{area:1076}。",
	["{npc:4201}, in the hut north of them; inside"] = "{npc:4201}，在他们北边的小屋里；室内",
	["{npc:4201}, inside"] = "{npc:4201}：在屋内",
	["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended."] = "{npc:4276}在峭壁东端的{area:2160}挖矿。与他交谈，并在挖矿时击退风险投资公司的袭击者。\n注意：狗头人成波出现。第一波是近战，第二波会增加施法者。矿洞里的普通怪刷新很快，波次来临时可能加入战斗。建议组队。",
	["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}，在{object:2096}的奶酪店",
	["{npc:4959} and {npc:482}"] = "{npc:4959}和{npc:482}",
	["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}，在光明大教堂",
	["{npc:5082}, Mikhail and Tapoke Jahn are all at Menethil's inn; Tapoke fights you when you talk to Mikhail, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn.\n{npc:2104} stands in {area:2103}, a short walk from {npc:1242}.\n{npc:2104} stands in {area:2103}."] = "{npc:5082}、米哈伊尔和塔波克·扬都在米奈希尔的旅店里；与米哈伊尔交谈时塔波克会攻击你，但被打败后就会停手。{npc:1480}站在旅店东北不远的地方。\n{npc:2104}站在{area:2103}，离{npc:1242}不远。\n{npc:2104}站在{area:2103}。",
	["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}：之后交给{zone:1413}的{npc:6244}",
	["{object:176634}, beside him"] = "{object:176634}，在他身旁",
	["{object:2164} is in the {object:2101}."] = "{object:2164}在{object:2101}。",
	["{object:2164} is in the {object:2101}. Warlocks: {npc:6122} is in its cellar."] = "{object:2164}位于{object:2101}。术士：{npc:6122}在其地下室。",
	["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009}带着怒尾卫兵在{area:414}北端巡逻。",
	["{quest:1010}, from the plant bundles"] = "{quest:1010}，来自植物束",
	["{zone:1437}: kill these as you meet them"] = "{zone:1437}：遇到就杀",
	["{zone:1455} priests"] = "{zone:1455}的牧师",
}

G["forever/alliance/06-wetlands"] = {
	["A new {item:279996}, for the four titan watchers around the {zone:1437}; below ground. Their hearts drop from level 32 elites on the {area:205} visit"] = "新的{item:279996}，用于{zone:1437}各处的四名泰坦看守；在地下。他们的心脏由前往{area:205}时遇到的32级精英掉落",
	["Back to the Cathedral of Light: {npc:928} stands inside."] = "回到光明大教堂：{npc:928}站在里面。",
	["Back west along the road to {area:150}: {npc:2104} stands on the top floor of {area:2103}."] = "沿路向西折回{area:150}：{npc:2104}站在{area:2103}的顶层。",
	["Below ground"] = "在地下",
	["Bloodtooth Guard"] = "血牙卫兵",
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Cast {spell:18960}"] = "施放{spell:18960}",
	["Cathedral of Light"] = "光明大教堂",
	["Cursed Marine"] = "被诅咒的水兵",
	["Cursed Sailor"] = "被诅咒的水手",
	["Dartol's Rod"] = "达图尔的变形魔棒",
	["East from {npc:270637}: {npc:2093} stands beside the road."] = "从{npc:270637}向东走：{npc:2093}站在路边。",
	["Fen Creeper"] = "沼泽爬行者",
	["Flagon of Mead, from {npc:1464}"] = "蜂蜜酒壶，来自{npc:1464}",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {area:415}"] = "飞往{area:415}",
	["Fly to {area:442}"] = "飞往{area:442}",
	["Fly to {area:702}"] = "飞往{area:702}",
	["Follow the coast north out of Menethil into {area:1022}. Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "从米奈希尔沿海岸向北进入{area:1022}。鱼人棚屋里有三个容器，从南往北依次是：{object:261}、{object:142151}，最后是北端的{object:259}。",
	["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it.\nCareful: Fen Creepers hide in stealth where the river splits close to the ghost ship, and they can join a fight."] = "沿海岸向北前往沉船。被诅咒的水手在海滩上活动，被诅咒的水兵在甲板上；{npc:1159}位于船头旁海滩。巨型湿地鳄鱼潜伏在稍北侧的海岸。\n注意：幽灵船附近河道分岔处有潜行的沼泽爬行者，可能加入战斗。",
	["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "沿道路向东到{area:429}的萨特营地；{npc:3920}躲在营地边缘。",
	["Follow the road east to the {area:1025}; {npc:1244} stands by the river. {quest:277}'s flint came with you from your last {zone:1437} visit."] = "沿路向东前往{area:1025}；{npc:1244}站在河边。{quest:277}所需的燧石是你上次来{zone:1437}时带上的。",
	["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "沿道路向东到{area:419}；{npc:3916}站在月亮井旁。",
	["Follow the road east: the bigger raptors for {quest:295} hunt in the valley just west of the excavation site."] = "沿路向东：{quest:295}所需的较大迅猛龙就在挖掘场西边的山谷里活动。",
	["For Bolvar Fordragon in {object:2117}: keep it"] = "交给{object:2117}的伯瓦尔·弗塔根公爵：先留着",
	["For King Magni in {zone:1455}, at the end of 30-40/01-hillsbrad-foothills"] = "交给{zone:1455}的国王麦格尼·铜须，在30-40/01-希尔斯布莱德丘陵指南结尾",
	["For the Dragonmaw catapult, on the {zone:1437} loop of 30-40/01-hillsbrad-foothills"] = "用于龙喉投石车，在30-40/01-hillsbrad-foothills的{zone:1437}路线中处理",
	["For {npc:1284} in {zone:1453}, at the end of this guide"] = "交给{zone:1453}的{npc:1284}，在本指南末尾完成",
	["For {npc:2228} in {area:271}: keep it"] = "交给{area:271}的{npc:2228}：先留着",
	["For {npc:3649} in {area:442}, on this guide's boat trip: keep it"] = "交给{area:442}的{npc:3649}，在本指南的乘船途中完成：先留着",
	["For {quest:4581} at {area:2358}"] = "去{area:2358}交{quest:4581}",
	["Goaz Warders"] = "戈阿兹守卫者",
	["In from the north: {npc:2094} by the docks, {npc:1242} on the pier, {npc:2104} in the keep, then {npc:1239} in the inn."] = "从北面进城：{npc:2094}在码头旁，{npc:1242}在栈桥上，{npc:2104}在要塞内，然后去旅店找{npc:1239}。",
	["In {zone:1453}, join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "在{zone:1453}，把两半吊坠合成{item:15885}并施放{spell:18960}：{npc:11802}在{area:2361}。然后{area:2361}的{npc:11800}会把德鲁伊直接飞到{area:702}。{npc:11802}站在他所在建筑的楼上：从里面上去，箭头分不清楼层。",
	["Insane druids"] = "发狂的德鲁伊",
	["Inside"] = "在里面",
	["Into {zone:1457}"] = "进入{zone:1457}",
	["Mavoris Cloudsbreak"] = "马沃里斯·碎云",
	["Melyria and {npc:3901}"] = "哨兵梅丽瑞亚·霜影和{npc:3901}",
	["Mottled Razormaw"] = "斑纹镰颚龙",
	["Mottled Scytheclaw"] = "斑纹镰爪龙",
	["Next: fly to {area:42}."] = "下一步：飞往{area:42}。",
	["North from the lake to the satyr camp of {area:430}, just west of {area:2358}: the {object:19901} stands in it, and Kurothel's Knapsack lies beside it with the {item:281014}.\nCareful: The Felmusk Rogues in {area:428} often go stealthed, and {area:430} has satyr casters."] = "从湖边向北前往{area:2358}西边不远处的{area:430}萨特营地：{object:19901}就在营地里，旁边是库洛瑟尔的背包，里面有{item:281014}。\n注意：{area:428}的魔草潜行者经常潜行，{area:430}也有萨特施法者。",
	["North to {area:413}."] = "向北前往{area:413}。",
	["On the top floor"] = "在最顶层",
	["Only if you looted {quest:337} in {zone:1431}"] = "仅当你在{zone:1431}拾取了{quest:337}",
	["Ran Bloodtooth"] = "兰·血牙",
	["Raptor valley"] = "迅猛龙山谷",
	["Razormaw Incisors: from the raptors by the {area:1038}, on the {zone:1437} loop of 30-40/01-hillsbrad-foothills"] = "刺喉龙门牙：由{area:1038}附近的迅猛龙掉落，在30-40/01-hillsbrad-foothills的{zone:1437}路线中收集",
	["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; Neru stands in the north-east (use the {item:279996}).\nFen Creepers hide in the marsh pools north-west of the {area:1025}.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "红色幼龙遍布大门以西的丘陵，发狂的腐爪龙占据{area:1025}，镰颚龙在北坡；内鲁站在东北（使用{item:279996}）。\n沼泽爬行者藏在{area:1025}西北的沼泽水塘里。\n注意：脱离战斗时，沼泽爬行者会不时施放潜行，所以它们处于潜行状态，很难发现。",
	["South-east along the road to {area:415}: {npc:3691} in the inn, {npc:3961} and {npc:3894} inside, the flight master at the west end."] = "沿路向东南到{area:415}：{npc:3691}在旅店，{npc:3961}和{npc:3894}在里面，飞行管理员在西端。",
	["South-east from the dig to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "从挖掘场向东南到龙喉营地。四份进攻计划都在{area:1036}；精英{npc:2091}也站在营地里。",
	["Take the boat from {area:442}'s dock to {area:150}."] = "从{area:442}的码头坐船前往{area:150}。",
	["Take the portal up to the {area:1658}, then fly back to {area:442} for the boat to {area:150}."] = "通过传送门上去，到{area:1658}，再飞回{area:442}，坐船前往{area:150}。",
	["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "穿过隧道进入{area:419}；书在西端的废墟里。",
	["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "从{object:171524}乘{area:2257}前往{zone:1453}的{object:28027}，然后步行到{object:2098}。",
	["Taneel Darkwood"] = "塔尼尔·暗木",
	["The Bluegill hovels"] = "蓝腮鱼人小屋",
	["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "月亮井北边的疯狂的古树和{npc:3919}带着{item:5475}；它能打开的旧箱子就在它们中间。",
	["The Forsaken's camp lies in the woods south of {area:2358}.\nRusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel.\nCareful: Non-elite Forsaken of about level 28-30 guard the camp. Some of them are stealthed, and the ones around the table often aggro together."] = "被遗忘者的营地位于{area:2358}南侧树林中。\n被遗忘者营地西侧的林荫熊怪营地周围有生锈的箱子，不断打开，直到找到剑柄。\n注意：营地由约 28–30 级的非精英被遗忘者守卫，部分敌人处于潜行状态，桌子周围的敌人通常会一同参战。",
	["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one.\n{npc:270892} is elite: grouping up is advised."] = "戈阿兹守卫者就在维尔加营地的西边：在其中一只旁边使用他给你的{item:279996}。\n{npc:270892}是精英，建议组队。",
	["The boat to {area:442} leaves from the far end of Menethil's western pier."] = "前往{area:442}的船从米奈希尔西侧栈桥的尽头出发。",
	["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "船长在沉船甲板上走动；他的保险箱在货舱里。",
	["The excavation site sits on the hill south of the road: {npc:1078} at the top, {npc:1077} below ground."] = "挖掘场在道路南面的山丘上：{npc:1078}在顶上，{npc:1077}在地下。",
	["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it."] = "圣物就在挖掘场里。{npc:1353}是一只大型刺喉龙，在挖掘场西边不远的迅猛龙山谷中徘徊。",
	["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "第二个{object:19901}在{area:428}的山谷里，就在向西的路上。",
	["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "隐蔽的神龛在月亮井东南方不远处的山丘上；沿蜿蜒的小路上去。",
	["The three druids stand together at the Forsaken camp south of {area:2358}.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight."] = "三名德鲁伊一起站在{area:2358}南边的被遗忘者营地。\n小心：巢穴里有很多刷新很快的怪，包括潜行的亡灵和巡逻队，所以战斗时经常会有额外的怪加入。",
	["The two stand together at the western end of the road, south-west of {area:415}."] = "两人一起站在{area:415}西南、道路的西端。",
	["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way.\nCareful: Other mobs, some of them underwater, sit near the island. Clear them first so they don't join the fight when you pull the Oracle."] = "{npc:3931}在箱子西南侧的{quest:1035}岸边巡逻；途中可在湖北侧找到{object:669176}。\n注意：岛屿附近还有其他怪物，部分位于水下。先清理周围，避免拉神谕者时其他敌人加入战斗。",
	["The {object:19901} stands in the satyr camp of {area:430}, further east along the road.\nCareful: The Felmusk Rogues in {area:428} often go stealthed, and {area:430} has satyr casters."] = "{object:19901}立在{area:430}的萨特营地，沿路再往东。\n小心：{area:428}的邪麝盗贼常常潜行，{area:430}有萨特施法者。",
	["Tram to {zone:1453}"] = "乘地铁前往{zone:1453}",
	["Uthil Mooncall"] = "乌希尔·唤月",
	["West from {npc:3897} along the southern hills to the {area:416}: Melyria and {npc:3901} stand together by it."] = "从{npc:3897}沿南面山丘向西前往{area:416}：Melyria和{npc:3901}一起站在旁边。",
	["{area:1025}: kill these as you meet them"] = "{area:1025}：遇到就杀",
	["{area:1039}: kill these as you meet them"] = "{area:1039}：沿途击杀以下目标",
	["{area:118}: kill these as you meet them"] = "{area:118}：沿途击杀以下目标",
	["{area:150} flight master"] = "{area:150}的飞行管理员",
	["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there, {npc:221269} a few steps east of her."] = "{area:2358}是道路东端的暗夜精灵前哨：{npc:3848}站在那里，{npc:221269}在她东边几步远。",
	["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "{area:2358}是道路东端的暗夜精灵前哨：{npc:3848}站在那里。",
	["{area:415} flight master"] = "{area:415}的飞行管理员",
