G["forever/alliance/07-thousand-needles"] = {
	["Back to {area:42}"] = "回到{area:42}",
	["Below ground"] = "在地下",
	["Cursed Marine"] = "被诅咒的水兵",
	["Cursed Sailor"] = "被诅咒的水手",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "沿峡谷向东前往盐滩。{area:2240}的地精和侏儒是中立的，向两个阵营提供任务。",
	["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it.\nCareful: Fen Creepers hide in stealth where the river splits close to the ghost ship, and they can join a fight."] = "沿海岸向北前往沉船。被诅咒的水手在沙滩上走动，被诅咒的水兵在甲板上；{npc:1159}站在船头的沙滩上。巨型湿地鳄鱼潜伏在它北边的海岸。\n小心：沼泽爬行者潜行藏在靠近鬼船的河流分叉处，会加入战斗。",
	["Follow the coast north-east past the wreck: the Bluegill Raiders hold the marsh beyond the Giant Crocolisks."] = "沿海岸向东北经过沉船：蓝腮袭击者占据巨型鳄鱼后面的沼泽。",
	["For the Dragonmaw catapult, on the {zone:1437} loop of the next guide"] = "龙喉投石车，见下一份指南的{zone:1437}环线",
	["For {npc:1212} in {zone:1453}, in the next guide"] = "交给{zone:1453}的{npc:1212}，在下一份指南中",
	["For {npc:1284} in {zone:1453}, in the next guide"] = "交给{zone:1453}的{npc:1284}，在下一份指南中",
	["For {npc:482} in {zone:1453}, in the next guide"] = "交给{zone:1453}的{npc:482}，在下一份指南中",
	["For {quest:5762} in Stranglethorn, later"] = "交给荆棘谷的{quest:5762}，以后",
	["Head east again to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "再次向东前往龙喉营地。四份进攻计划都在{area:1036}；精英{npc:2091}也站在营地里。",
	["Head east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "向东前往食人魔土丘。{object:119}在入口处的营地；碎拳食人魔看守着它。",
	["Head south-west from {area:42} to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "从{area:42}向西南前往食人魔山。{object:119}在入口处的营地里，有Splinter Fist食人魔看守。",
	["Her house stands on the hill south-east of {area:42}."] = "她的房子在{area:42}东南方的山上。",
	["Inside"] = "在里面",
	["Into {zone:1413}"] = "进入{zone:1413}",
	["Nightbane Dark Runner"] = "夜行魔黑暗奔跑者",
	["Nightbane Dark Runners"] = "夜行黑暗狼人",
	["Nightbane Shadow Weaver"] = "夜行魔织影者",
