	["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "沿路向南穿过{zone:1413}，{npc:6244}在路东、{area:378}东北扎营；从东侧靠近，避开部落卫兵。",
	["On the top floor"] = "顶层",
	["On the way"] = "顺路",
	["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "仅当{npc:272273}掉落了{quest:96138}时：右键点击它",
	["Plague Spreader"] = "瘟疫传播者",
