G["forever/alliance/30-40/01-hillsbrad-foothills"] = {
	["A report for {object:2117}; inside"] = "给{object:2117}的报告，进入屋内交付",
	["Back down the road to {area:205}: {npc:1075} wants the {object:147516} explosives under the far end of the span destroyed."] = "沿路返回{area:205}：{npc:1075}要你摧毁大桥另一端下方的{object:147516}炸药。",
	["Back east along the road to the {area:1025}: {npc:270637} camps among the Fenrunners, just west of {npc:1244}. Then west again to Menethil for the boat."] = "沿路向东返回{area:1025}：{npc:270637}的营地在{npc:1244}西边不远，周围是藓皮沼泽行者。然后再向西返回米奈希尔坐船。",
	["Back over the span and down the road through {area:205} on the way south."] = "返回大桥另一侧，再沿路向南，经过{area:205}。",
	["Back to the same murlocs; not every one drops a head."] = "回到同一群鱼人那里；不是每只都掉头。",
	["Below ground"] = "在地下",
	["Boat to {area:271}"] = "乘船前往{area:271}",
	["Cathedral of Light"] = "光明大教堂",
	["Comar Villard"] = "科马尔·维拉德",
	["Comar Villard waits on the road north of {area:205}, towards the {area:880}; {npc:271322} a short walk further north-east, and Ebenezer Rustlocke's corpse lies under the span beside her. Rustlocke's parchment goes back to {npc:1075}."] = "科马尔·维拉德在{area:205}以北、通往{area:880}的路上等着；{npc:271322}再往东北走一小段就到，埃比尼泽·拉斯特洛克的尸体就在桥下她身旁。把拉斯特洛克的羊皮纸交回给{npc:1075}。",
	["Daggerspine Shorehunter"] = "刺脊海岸猎手",
	["Daggerspine Siren"] = "刺脊海妖",
	["Daggerspine naga"] = "刺脊纳迦",
	["Druid training"] = "德鲁伊训练",
	["Ebenezer Rustlocke"] = "伊贝尼瑟的尸体",
	["Farren"] = "法尔林·奥里涅尔中尉",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {area:415}"] = "飞往{area:415}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road south over the bridge to {area:205} at the {zone:1437} end, where {npc:1075} waits."] = "沿路向南过桥，到{zone:1437}一端的{area:205}，{npc:1075}在那里等着。",
	["For King Magni in {zone:1455}, at the end of this guide"] = "交给{zone:1455}的国王麦格尼·铜须，在本指南结尾",
	["For {npc:2916} in {zone:1455}, at the end of this guide"] = "交给{zone:1455}的{npc:2916}，在本指南结尾",
	["If you skipped {quest:474}, grind here to level 31.23 to stay on the route's plan."] = "如果你跳过了{quest:474}，在这里刷到31.23级，以保持路线计划。",
	["Inside"] = "在里面",
	["Level 30 and 32 spells"] = "30级和32级法术",
	["Level 30.8"] = "30.8级",
	["Level 31.23"] = "31.23级",
	["Maddened Rotclaws roam the {area:1025} around {npc:1244}."] = "狂乱的腐爪怪在{npc:1244}周围的{area:1025}游荡。",
	["Murloc heads"] = "鱼人头",
	["North along the road to {area:205}. {npc:1071}, {npc:1075} and {npc:1072} stand together in the dwarves' camp; the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "沿道路向北到{area:205}。{npc:1071}、{npc:1075}和{npc:1072}一起站在矮人营地里；{npc:271481}被关在西侧：把它带出去交给{npc:1072}。",
	["North along the road to {area:205}. {npc:271460} stands in the ruins (use the {item:279996}); the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "沿道路向北到{area:205}。{npc:271460}站在废墟里（使用{item:279996}）；{npc:271481}被关在西侧：把它带出去交给{npc:1072}。",
	["North-east to the {area:1038}: {npc:271338} stands at the gates (use the {item:279996})."] = "向东北前往{area:1038}：{npc:271338}站在大门口，使用{item:279996}。",
	["Off the boat, walk up the pier into town: {npc:2711} and Lieutenant Farren stand by the inn, {npc:2705} below it and {npc:2430} upstairs, {npc:2382} east of it; the flight master is at the north end, {npc:2381} and {npc:2438} between her and the inn, Maleb in the town hall at the west side."] = "下船后沿码头走进镇子：{npc:2711}和法尔林·奥里涅尔中尉站在旅店旁，{npc:2705}在旅店下面，{npc:2430}在楼上，{npc:2382}在旅店东边；飞行管理员在北端，{npc:2381}和{npc:2438}在她和旅店之间，赫尼·马雷布镇长在西侧的市政厅。",
	["Off the boat, {npc:251493} is the first you meet, north-west of the flight master."] = "下船后，你最先遇到的是飞行管理员西北的{npc:251493}。",
	["On the top floor"] = "在最顶层",
	["On the way"] = "途中",
	["Over the {area:880}: the Dark Irons' cache of explosives sits by its Arathi end. {npc:2696} stands a short walk west of it."] = "过了{area:880}：黑铁矮人的炸药储藏点就在它靠阿拉希的一端。{npc:2696}站在它西边不远处。",
	["Pick up everything in town before heading out. {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "出发前先把城里所有任务都接了。{npc:2381}和{npc:2438}站在飞行管理员与旅店之间，法伦和{npc:2366}在旅店，马莱布在镇公所。",
	["Skipped {quest:474} and short of 30.8? Kill the Bluegill murlocs on the coast south of Menethil until level 30.8. Or, with a group, run the {area:133} dungeon or the {area:796} dungeon (Graveyard) instead."] = "跳过了{quest:474}，还没到30.8级？在米奈希尔以南的海岸刷蓝腮鱼人，直到30.8级。也可以组队去{area:133}副本或{area:796}副本（墓地）。",
	["Snapjaws"] = "钳嘴龟",
	["South to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "向南到龙喉的{area:1036}：第一架投石车就在路上，{object:671518}在营地里。",
	["South-east from Menethil to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "从米奈希尔向东南前往龙喉的{area:1036}：第一辆投石车在途中，{object:671518}在营地内。",
	["Syndicate Footpad"] = "辛迪加扒手",
	["Syndicate Thief"] = "辛迪加窃贼",
	["Syndicate camp"] = "辛迪加营地",
	["Take the {area:2257} from the {object:28027} to {zone:1455}."] = "从{object:28027}乘{area:2257}前往{zone:1455}。",
	["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "钳嘴龟在{area:271}东边、{area:272}（部落）南边的河边晒太阳。",
	["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp, and its Footpads and Thieves are the Syndicate Maleb wants."] = "辛迪加营地在{area:287}北部、奥特兰克边境上，{area:272}（部落）西边；文件在营地里，营地里的辛迪加潜行者和盗贼就是马雷布要找的辛迪加。",
	["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp."] = "辛迪加营地在{area:287}北部、奥特兰克边境上，{area:272}（部落）西边；文件在营地里。",
	["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}.\nCareful: One camp holds a tight cluster of Oracles that all aggro together."] = "碎鳍鱼人密集分布于{area:271}西南侧的{area:295}。\n注意：其中一个营地有一群紧挨着的神谕者，拉怪时会全部参战。",
	["The Villards"] = "维拉德一家",
	["The cheese shop in the {object:2096}."] = "{object:2096}的奶酪店。",
	["The naga hold the shore south-east of {area:271}."] = "纳迦占据着{area:271}东南方的海岸。",
	["The next step, {quest:474}, pits you against an elite chieftain: skip it."] = "下一步的{quest:474}要对付一个精英酋长：跳过它。",
	["The whelps nest in the hills north-east of the {area:1036}; {quest:98283} prowls further north, and the Razormaw raptors hunt the highlands on the way north to {area:205}.\n{quest:98283} is elite: grouping up is advised."] = "雏龙栖息在{area:1036}东北的山丘；{quest:98283}在更北面游荡，刺喉迅猛龙则在向北前往{area:205}途中的高地活动。\n{quest:98283}是精英，建议组队。",
	["The yetis live in the cave in the hills north of {area:271}, on the way north to the Syndicate camp."] = "雪人住在{area:271}北边山丘上的洞穴里，就在向北去辛迪加营地的路上。",
	["The yetis live in the cave in the hills north of {area:271}, on your way back south."] = "雪人住在{area:271}北边山丘上的洞穴里，就在你向南返回的路上。",
	["The {object:2704}"] = "{object:2704}",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2091} is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents."] = "这些是精英敌人，建议寻找其他玩家组队完成。{npc:2091}是 32 级精英，多数职业到 34 级可以尝试单独击败，但可能仍需帮助。独自一人时可跳过，路线会安排刷怪补回经验。\n注意：他两侧有暗影法师，至少一名与他联动，拉他时会一同参战。帐篷环周围还分布着非精英百夫长和队长。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:271462}, {npc:271338}, {npc:271458} and {npc:271460} are level 32 elites, each called up by using the {item:279996} beside it. Skip them if you are alone. {npc:271462} stands in the south-eastern hills."] = "这些是精英敌人，建议寻找其他玩家组队完成。{npc:271462}、{npc:271338}、{npc:271458}和{npc:271460}都是 32 级精英，需要在各自近旁使用{item:279996}召唤。单人时可跳过。{npc:271462}位于东南侧山丘。",
	["To {area:2104}"] = "前往{area:2104}",
	["Torn Fin Oracle"] = "碎鳍预言者",
	["Torn Fin Tidehunter"] = "碎鳍猎潮者",
	["Torn Fin murlocs"] = "碎鳍鱼人",
	["Underwater"] = "在水下",
	["West along the road to Menethil."] = "沿道路向西到米奈希尔港。",
	["Yeti cave"] = "雪人洞穴",
	["for {npc:2700} at {area:320}, in 05-arathi-highlands"] = "在05-arathi-highlands中交给{area:320}的{npc:2700}",
	["grind on {npc:1418}"] = "反复击杀{npc:1418}补足经验",
	["the same corpse"] = "同一具尸体",
	["{area:1038}: kill these as you meet them"] = "{area:1038}：沿途击杀以下目标",
	["{area:271} flight master"] = "{area:271}的飞行管理员",
	["{area:442} flight master"] = "{area:442}飞行管理员",
	["{item:3713}, from {npc:2381}"] = "{item:3713}，来自{npc:2381}",
	["{npc:1071} stands in the dwarves' camp."] = "{npc:1071}站在矮人营地里。",
	["{npc:1075} again"] = "再次找{npc:1075}",
	["{npc:1356}, {npc:2916} and {npc:5637} stand in the {object:32356}, north-east of the flight master."] = "{npc:1356}、{npc:2916}和{npc:5637}位于飞行管理员东北侧的{object:32356}。",
	["{npc:2104} stands on the top floor of {area:2103}: go up inside, the arrow cannot tell the floors apart."] = "{npc:2104}站在{area:2103}的顶层：从里面上楼，箭头无法区分楼层。",
	["{npc:2104}: for {npc:270637}, back east along the road"] = "{npc:2104}：交给{npc:270637}，沿路向东返回",
	["{npc:2104}: for {npc:270637}; on the top floor"] = "{npc:2104}：交给{npc:270637}；在顶层",
	["{npc:211033}: only offered once you have handed in library books (the Library Books guide)"] = "{npc:211033}：交过图书馆书籍后才会提供此任务，详见《图书馆藏书》指南",
	["{npc:2228}, inside"] = "{npc:2228}：在屋内",
	["{npc:2276}, inside"] = "{npc:2276}：在屋内",
	["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}，在旅店里：交给{area:35}（04-stranglethorn-vale）",
	["{npc:2382}: the lions come later"] = "{npc:2382}：狮子稍后再说",
	["{npc:2430}, upstairs"] = "{npc:2430}：在楼上",
	["{npc:2438} also wants a {item:3719} ({skill:165}), a {item:2997} ({skill:197}) and {item:2321} (any trade supplier): the cloak is turned in when you are back in {area:271} later."] = "{npc:2438}还要一件{item:3719}（{skill:165}）、一匹{item:2997}（{skill:197}）和{item:2321}（任意专业供应商）：披风之后回到{area:271}时再交。",
	["{npc:2438} also wants a {item:3719}, a {item:2997} and {item:2321}: crafted or bought; the cloak is turned in when you are back in {area:271} later."] = "{npc:2438}还要一件{item:3719}、一匹{item:2997}和{item:2321}：制作或购买；披风之后回到{area:271}时再交。",
	["{npc:2438}: only if you have or can buy a {item:3719} ({skill:165}) and a {item:2997} ({skill:197}); no vendor sells them"] = "{npc:2438}：只有在你已有或能买到{item:3719}（{skill:165}）和{item:2997}（{skill:197}）时才做；没有商人卖这两样",
	["{npc:251493} stands north-west of the flight master, on the way north to the yeti cave."] = "{npc:251493}站在飞行管理员西北方，就在向北去雪人洞穴的路上。",
	["{npc:2695}: for King Magni, on the same {zone:1455} stop"] = "{npc:2695}：交给国王麦格尼·铜须，在同一次{zone:1455}行程中",
	["{npc:2705}, below ground"] = "{npc:2705}，在地下",
	["{npc:2708} is in the {object:2164}; {npc:211033} near the canal; {npc:5081} south of the {object:2101}."] = "{npc:2708}在{object:2164}；{npc:211033}在运河附近；{npc:5081}在{object:2101}南边。",
	["{npc:2708} is in the {object:2164}; {npc:5081} south of the {object:2101}."] = "{npc:2708}在{object:2164}内；{npc:5081}在{object:2101}南面。",
	["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}：他的线索指向阿拉希高地",
	["{npc:271458} stands in the hills between the {area:1038} and {area:205} (use the {item:279996})."] = "{npc:271458}位于{area:1038}与{area:205}之间的山丘，使用{item:279996}召唤。",
	["{npc:271460} stands in the ruins of {area:205} (use the {item:279996})."] = "{npc:271460}位于{area:205}废墟内，使用{item:279996}召唤。",
	["{npc:271462} stands in the south-eastern hills: use the {item:279996} beside it."] = "{npc:271462}站在东南方的山丘上：在它旁边使用{item:279996}。",
	["{npc:2784}, the {object:171709}"] = "{npc:2784}，{object:171709}",
	["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961}在{object:2100}的酒馆里等候；他和两个打手会和你打，但被打败后就会住手。",
	["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479}在{object:2100}的酒馆旁训练战士。{npc:6236}在{zone:1413}的{area:720}等候，在很久之后去{area:392}的路上（40-50/01）。",
	["{npc:5683} waits north of {area:205} by the {area:880}; {npc:271322} a short walk further north-east."] = "{npc:5683}在{area:205}以北、{area:880}旁等着；{npc:271322}在东北再走一小段。",
	["{object:2652}, inside"] = "{object:2652}，在里面",
	["{object:671518}: for {npc:2104}"] = "{object:671518}：交给{npc:2104}",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
	["{zone:1455} has no druid trainer: train with {npc:5504} in {zone:1453} before the tram."] = "{zone:1455}没有德鲁伊训练师：乘地铁前先在{zone:1453}找{npc:5504}学习。",
	["{zone:1455} has no druid trainer: {npc:5504} stands in {zone:1453}, north-west of the {object:2101}."] = "{zone:1455}没有德鲁伊训练师：{npc:5504}在{zone:1453}，位于{object:2101}西北。",
}

G["forever/alliance/30-40/02-desolace"] = {
	["Aged Kodo"] = "年迈的科多兽",
	["Boat to {area:17203}"] = "乘船前往{area:17203}",
	["Escort {npc:5644}"] = "护送{npc:5644}",
	["Fly to {area:415}"] = "飞往{area:415}",
	["Fly to {area:442}"] = "飞往{area:442}",
	["Follow the road west out of {area:415}; {area:413} lies north of it."] = "沿路从{area:415}向西出去；{area:413}位于其北面。",
	["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "沿道路向西经过{area:460}（部落），再向西南穿过{area:465}进入{zone:1443}；{area:608}在山口顶部。",
	["For {npc:5638}, at the end of this guide"] = "交给{npc:5638}，在本指南结尾",
	["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then back past {area:415} to the {area:1276}."] = "从{area:415}向西北进入丘陵：{quest:1738}是通往{area:413}道路北侧的一棵发光树。如果你接了{quest:65602}，{item:190309}就在{area:413}以北树林中的一座房子里（26.6,22.0）。然后经过{area:415}回到{area:1276}。",
	["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building."] = "她的哥哥{npc:5643}（36级）和火刃氏族的祭司（30-33级）在要塞里巡逻：单独把他拉出来。{npc:13019}把权杖放在要塞的主建筑里。",
	["Inside"] = "在里面",
	["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "带{npc:5644}离开要塞；离开要塞后她会自行离去。指南结尾在{area:608}向{npc:5642}交任务。",
	["Malem chest"] = "玛雷姆的箱子",
	["Out of Thunder Axe Fortress"] = "离开雷斧堡垒",
	["Scorpashi venom"] = "荒土蝎子毒液",
	["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}.\nCareful: Hatefury Rogues spawn stealthed, and Hatefury Tricksters have a poison proc on their attacks."] = "怨怒萨特占据{area:608}以东的{area:603}废墟。\n注意：怨怒潜行者出现时就处于潜行状态，怨怒欺诈者的攻击有几率触发中毒。",
	["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "科卡尔半人马在{area:609}周围的平原上游荡；它们的耳朵交给{npc:5752}。",
	["The Scorpashi scorpids hunt the hills around {area:2407} on the road south."] = "荒土蝎子在南边道路上的{area:2407}周围山丘上捕猎。",
	["The chest lies in the ruins south-west of {area:608}."] = "箱子在{area:608}西南方的废墟里。",
	["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "沉船就在{npc:11863}的塔西南方不远处；箱子在{object:177787}旁边。",
	["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "对一只{npc:4700}使用{npc:11596}的{item:13892}，然后带着驯服的科多兽走回他的营地，共五次；老迈的科多兽也会掉落皮。",
	["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp. There, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom."] = "对一只{npc:4700}使用{npc:11596}的{item:13892}，把驯服的科多兽牵回他的营地。到了那里跟科多兽对话：这样才算数，也才能驯下一只。共五只科多兽，一次一只；老迈的科多兽也会掉皮，在墓地周围捕猎的斯科尔帕什鞭笞者身上带着毒液。",
	["{area:608} flight master"] = "{area:608}的飞行管理员",
	["{item:190309}, north of {area:413}"] = "{item:190309}，在{area:413}北边",
	["{item:6767}; inside"] = "{item:6767}：在屋内",
	["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "{npc:11596}的营地在{area:609}南边的路上，{area:596}旁。",
	["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "{npc:11863}的塔在{area:599}西边的山丘上：先接他的任务，他要的权杖在要塞里。",
	["{npc:5638}: the satchel lies off the north-west coast, on the south loop at the end of 30-40 (06-badlands): keep it"] = "{npc:5638}：挎包在西北海岸外，位于30-40结尾南线（06-badlands）上：先留着它",
	["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}：沉船的箱子在{npc:11863}的塔下方，位于前往{area:599}的路上",
	["{npc:5643} and the Seer"] = "{npc:5643}和先知",
	["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644}躲在{area:608}西南方燃烧之刃的要塞里。",
	["{npc:5644}, inside"] = "{npc:5644}：在屋内",
	["{quest:5741}; on the top floor"] = "{quest:5741}，位于最顶层",
}

G["forever/alliance/30-40/03-ashenvale"] = {
	["Bloodtooth Guard"] = "血牙卫兵",
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Dartol's Rod"] = "达图尔的变形魔棒",
	["Down the {area:485} into {area:400}, then west to the wyverns' cliffs at {area:482}. Every wyvern there can drop a venom sac."] = "沿{area:485}下去进入{area:400}，再向西到{area:482}的双足飞龙悬崖。那里每只双足飞龙都可能掉落毒囊。",
	["Down the {area:485} into {zone:1441}, then west to the wyverns' cliffs at {area:482}. Every wyvern there can drop a venom sac."] = "乘{area:485}下到{zone:1441}，再向西前往{area:482}的双足飞龙悬崖。那里所有双足飞龙都可能掉落毒囊。",
	["East through the canyons. {area:484}, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth."] = "向东穿过峡谷。{area:484}是一座有卫兵的部落营地，位于这里的台地上：沿着峡谷底部走，远离它升降梯的底部。",
	["Fly to Theramore"] = "飞往塞拉摩岛",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Fly to {area:442}"] = "飞往{area:442}",
	["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "沿峡谷向东前往盐滩。{area:2240}的地精和侏儒是中立的，向两个阵营提供任务。",
	["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "沿道路向东到{area:429}的萨特营地；{npc:3920}躲在营地边缘。",
	["Follow the road west out of Theramore to the burned inn on the road toward the {zone:1413}: the black shield lies in the ashes and the hoofprints are in the mud beside the inn."] = "沿路向西离开塞拉摩，前往通往{zone:1413}道路上被烧毁的旅店：黑色盾牌在灰烬中，蹄印在旅店旁的泥地里。",
	["For {npc:1416} in {zone:1453}, after Stranglethorn"] = "交给{zone:1453}的{npc:1416}，完成荆棘谷后再交",
	["For {quest:1132} in Theramore's inn, where this guide's boat goes"] = "用于塞拉摩旅店的{quest:1132}，本指南的船会开往那里",
	["For {quest:5762} in Stranglethorn, later"] = "交给荆棘谷的{quest:5762}，以后",
	["From the raceway follow the road south out of the {area:439} into {zone:1446}; {area:976} is a short walk down it. Keep to the road. {npc:7823}, the Alliance flight master, stands inside the walls."] = "从赛道沿路向南出{area:439}进入{zone:1446}；沿路走一小段就是{area:976}。别离开道路。{npc:7823}是联盟飞行管理员，站在城墙里面。",
	["Insane druids"] = "疯狂的德鲁伊",
	["Inside"] = "在里面",
	["Into {zone:1413}"] = "进入{zone:1413}",
	["Lightforge Ingots"] = "{item:2702}",
	["Mavoris Cloudsbreak"] = "马沃里斯·碎云",
	["Melyria and {npc:3901}"] = "哨兵梅丽瑞亚·霜影和{npc:3901}",
	["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "沿着穿过{zone:1413}向南的道路，{npc:6244}在道路东边、{area:378}东北方扎营；从东边接近，避开部落守卫。",
	["Ran Bloodtooth"] = "兰·血牙",
	["Saltstone Basilisk"] = "盐石蜥蜴",
	["Saltstone Crystalhide"] = "盐石水晶皮",
	["Saltstone Gazer"] = "盐石凝视者",
	["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "穿过隧道进入{area:419}；书在西端的废墟里。",
	["Taneel Darkwood"] = "塔尼尔·暗木",
	["Tapoke \"Slim\" Jahn"] = "塔波克·“瘦子”·扬",
	["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "米奈希尔港西南方海滩上的蓝腮鱼人带着锭。",
	["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "月亮井北边的疯狂的古树和{npc:3919}带着{item:5475}；它能打开的旧箱子就在它们中间。",
	["The Forsaken's camp lies in the woods south of {area:2358}.\nRusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel.\nCareful: Non-elite Forsaken of about level 28-30 guard the camp. Some of them are stealthed, and the ones around the table often aggro together."] = "被遗忘者的营地位于{area:2358}南边的森林里。\n生锈的箱子散落在被遗忘者西边的暗影林熊怪营地周围；打开它们，直到其中一个藏有剑柄。\n小心：约28-30级的非精英被遗忘者守卫着营地。其中一些处于潜行状态，桌子周围的那几个常常会一起引到。",
	["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "飞行管理员站在{area:514}大门旁；{npc:5083}和{npc:4964}在城堡里。",
	["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "第二个{object:19901}在{area:428}的山谷里，就在向西的路上。",
	["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "隐蔽的神龛在月亮井东南方不远处的山丘上；沿蜿蜒的小路上去。",
	["The three druids stand together at the Forsaken camp south of {area:2358}.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight."] = "三名德鲁伊一起站在{area:2358}南边的被遗忘者营地。\n小心：巢穴里有很多刷新很快的怪，包括潜行的亡灵和巡逻队，所以战斗时经常会有额外的怪加入。",
	["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "飞翔鱼鹰号的残骸在城堡南侧浅水区。",
	["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way.\nCareful: Other mobs, some of them underwater, sit near the island. Clear them first so they don't join the fight when you pull the Oracle."] = "{npc:3931}在{quest:1035}岸边走动，位于箱子西南；{object:669176}在湖的北边，顺路可拿。\n小心：岛附近还有其他怪，有些在水下。先把它们清掉，免得拉先知时加入战斗。",
	["The {object:19901} stands in the satyr camp of {area:430}, further east along the road.\nCareful: The Felmusk Rogues in {area:428} often go stealthed, and {area:430} has satyr casters."] = "{object:19901}立在{area:430}的萨特营地，沿路再往东。\n小心：{area:428}的邪麝盗贼常常潜行，{area:430}有萨特施法者。",
	["Theramore"] = "塞拉摩",
	["Uthil Mooncall"] = "乌希尔·唤月",
	["{area:2240}: kill these as you meet them"] = "{area:2240}：沿途击杀以下目标",
	["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "{area:2358}是道路东端的暗夜精灵前哨：{npc:3848}站在那里。",
	["{area:415} flight master"] = "{area:415}飞行管理员",
	["{area:432}: kill these as you meet them"] = "{area:432}：遇到就杀",
	["{area:976} flight master"] = "{area:976}的飞行管理员",
	["{item:2702}; underwater"] = "{item:2702}：在水下",
	["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217}站在城堡南边的{area:2104}里，{npc:4963}和{npc:5082}也在那里等候。",
	["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217}站在米奈希尔城堡的上层。",
	["{npc:3696} and his guards camp just east of {npc:3897}.\nCareful: Wolves and spiders roam near the camp and can join a fight. Some of the wolves come in pairs."] = "{npc:3696}和他的卫兵在{npc:3897}东边扎营。\n小心：狼和蜘蛛在营地附近游荡，会加入战斗。有些狼成对出现。",
	["{npc:3894}, inside"] = "{npc:3894}，室内",
	["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "{npc:3897}是一个未受腐蚀的熊怪，坐在{area:421}下方道路的南边。",
	["{npc:3940}, inside {area:432}"] = "{npc:3940}，在{area:432}内",
	["{npc:3941}, inside {area:432}"] = "{npc:3941}，在{area:432}内",
	["{npc:3942}, inside {area:432}"] = "{npc:3942}，在{area:432}内",
	["{npc:4454}: for Martek in the {zone:1418}, at the end of 30-40"] = "{npc:4454}：交给{zone:1418}的马特克，在30-40路线末尾完成",
	["{npc:4455} stands by {area:2103}'s door, just north of the flight master."] = "{npc:4455}站在{area:2103}门口，就在飞行管理员北边。",
	["{npc:4456} is in the north of town, Captain Vimes in {area:514}; {npc:4941} stands in the town."] = "{npc:4456}在镇子北部，Captain Vimes在{area:514}；{npc:4941}也站在镇内。",
	["{npc:4456}: the wyverns are in {area:400}, later in this guide"] = "{npc:4456}：双足飞龙在{area:400}，本攻略后面会用到",
	["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619}率领{area:429}的萨特；树枝在他身上。",
	["{npc:4964}, on the top floor"] = "{npc:4964}，位于最顶层",
	["{npc:5083}, on the top floor"] = "{npc:5083}，位于最顶层",
	["{object:19868} lies all over the flats. Scorpid Reavers and Salt Flats Scavengers roam the north half, Sparkleshell Snappers (tortoises) the whole flats. Saltstone Basilisks and Crystalhides hold the middle; the Gazers (34-35) only the far south."] = "{object:19868}遍布整片平原。恐蝎劫掠者和盐湖食腐鹫出没于北半部，盐壳钳嘴龟（乌龟）则遍布平原。盐石蜥蜴和盐石水晶蜥蜴在中部；盐石凝视者（34-35级）只在最南端。",
	["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}：交给{area:415}的{npc:3961}",
	["{quest:1132}, inside the inn in the north of town"] = "{quest:1132}，在镇子北部的旅店里",
	["{quest:1132}: the wyverns are in {zone:1441}, later in this guide"] = "{quest:1132}：双足飞龙在{zone:1441}，本指南稍后会去",
	["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}：在{zone:1440}，前往{zone:1443}的路上",
	["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}：夜魔，在魅魔旁边；{item:190309}在{quest:1738}附近",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
}

G["forever/alliance/30-40/04-stranglethorn-vale"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "“海狼”麦金利，在顶层",
	["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "向南返回经过奈辛瓦里：黑豹和荆棘谷迅猛龙在营地西边通往海岸的空地上奔跑；老年荆棘谷猛虎占据西南方的山丘。",
	["Both roam the grass around the camp and along the road north."] = "两者都在营地周围的草地和向北的道路沿途游荡。",
	["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "注意：老虎活动区域附近有巨魔营地，拉怪不慎可能引来巨魔。\n注意：迅猛龙巢穴中的幼龙会在成年迅猛龙遭攻击时加入战斗。",
	["Down to {area:35}"] = "南下{area:35}",
	["Druid training"] = "德鲁伊训练",
	["Elder Stranglethorn Tiger"] = "老年荆棘谷虎",
	["Fly to {area:108}"] = "飞往{area:108}",
	["Fly to {area:35}"] = "飞往{area:35}",
	["Fly to {area:415}"] = "飞往{area:415}",
	["Fly to {area:42}"] = "飞往{area:42}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "沿主路向南穿过整片丛林，经过{object:3202}岔路，到达南部海角的{area:35}。",
	["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "沿西海岸向北；闹鬼的小岛在奈辛瓦里营地西边的近海。到达即可。",
	["For Archmage Ansirem in {zone:1416}"] = "交给{zone:1416}的大法师安斯雷姆",
	["From {area:108} the way leads south out of {zone:1436} into Stranglethorn's north-west, to the {area:310} near the coast; the Crystal Spine Basilisks around it drop the shards.\nThe haunted island lies just off the coast south-west of the mine: just reach it. The Bloodscalp trolls hold the ruins on the coast to the north."] = "从{area:108}向南离开{zone:1436}，进入荆棘谷西北部，前往海岸附近的{area:310}；周围的晶背蜥蜴会掉落碎片。\n闹鬼的岛屿就在矿洞西南边的近海，只需抵达即可。血顶巨魔占据了北边海岸上的废墟。",
	["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then take the road west to Stonetalon."] = "从{area:415}向西北进入丘陵：{quest:1738}是一棵发光的树，位于通往{area:413}的道路北边。如果接了{quest:65602}，{item:190309}就在{area:413}北边林间的一间房子里（26.6,22.0）。然后沿路向西前往石爪山。",
	["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "从{zone:1431}沿道路向南进入荆棘谷；猎人的帐篷就在经过{area:99}岔路后道路的西边。",
	["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "戈鲁格尔是营地西边海岸的一只稀有鱼人，掉落{item:4614}：遇到就拿",
	["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}."] = "缩颅者站在营地深处；突击队员潜行在营地周围和洞穴里。绿丘书页掉落时顺手捡起。\n注意：库尔森突击队员为34-35级，非精英，经常潜行刷新；濒死时会使用{spell:7964}。",
	["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "赫罗德的档案在营地西侧的一间小屋里；他的保险箱在更东边的洞口旁。",
	["Into {area:33}"] = "进入{area:33}",
	["Into {area:40}"] = "进入{area:40}",
	["Jungle Stalker"] = "丛林潜伏者",
	["Kurzen Commando"] = "库尔森突击队员",
	["Kurzen Headshrinker"] = "库尔森缩颅者",
	["Kurzen Jungle Fighter"] = "库尔森丛林战士",
	["Lashtail Raptor"] = "鞭尾迅猛龙",
	["Level 34"] = "34级",
	["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "绕行北部和中部的巨魔废墟：每处都有一块记载巨魔传说的石板。深喉猎豹潜行在周围的丛林中；{area:37}的风险投资公司营地携带打磨过的水晶。",
	["Panther"] = "豹",
	["Panthers, raptors and elder tigers"] = "猎豹、迅猛龙和老年猛虎",
	["River Crocolisks swim the river by the {area:99}."] = "淡水鳄在{area:99}旁的河中游动。",
	["River crocolisks"] = "淡水鳄",
	["Shadowmaw Panther"] = "暗齿豹",
	["Skullsplitter trolls"] = "劈颅巨魔",
	["Snapjaw Crocolisks"] = "钳嘴鳄鱼",
	["Snapjaw Crocolisks bask on the shore and islands along the coast north of {area:35}."] = "钳嘴鳄鱼趴在{area:35}北边沿海的岸边和岛上。",
	["Stranglethorn Raptor"] = "荆棘谷迅猛龙",
	["Stranglethorn Tiger"] = "荆棘谷虎",
	["Stranglethorn Tigers"] = "荆棘谷猛虎",
	["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "沿道路向北；{npc:738}在路上巡逻，营地在西边的山丘中。",
	["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "库尔森叛军占据{area:99}东边的营地；在外围活动，那里有库尔森丛林战士和库尔森药草师，并拾取帐篷旁的补给箱。",
	["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "劈颅巨魔占据奈辛瓦里和{object:3202}之间道路东边的废墟。",
	["The adult tigers prowl the hills just south and west of the camp."] = "成年猛虎在营地南边和西边的山丘上徘徊。",
	["The elder tigers come later, on the way back from the {area:99}"] = "老年猛虎稍后再打，在从{area:99}返回的路上",
	["The haunted island"] = "闹鬼的小岛",
	["The jungle ruins"] = "丛林废墟",
	["The ore drops from Drywhisker kobolds in {zone:1417}"] = "矿石由{zone:1417}的枯须狗头人掉落",
	["The quests from here on are 37: if you are short of 34, keep on the elder tigers in the hills south-west of Nesingwary's camp until level 34. Or, with a group, run the {area:796} dungeon (Library or Armory) instead."] = "接下来的任务为37级；如果还没到34级，就继续击杀奈辛瓦里营地西南丘陵中的老年猛虎，直到34级。也可组队挑战{area:796}副本（图书馆或武器库）。",
	["Thorsen patrols the road north of camp, toward the {area:99}."] = "索森在营地北边、通往{area:99}的道路上巡逻。",
	["Tram to {zone:1453}"] = "乘地铁到{zone:1453}",
	["Walk back north; the {area:310} lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards.\nThe Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "向北走回；{area:310}位于丛林中部道路的西侧。那里的水晶脊蜥蜴会掉落碎片。\n血顶巨魔占据着奈辛瓦里营地以西海岸的废墟。",
	["Young Panther"] = "幼豹",
	["Young Stranglethorn Tiger"] = "幼年荆棘谷虎",
	["Young tigers and panthers"] = "荆棘谷猛虎幼崽和猎豹幼崽",
	["grind on {npc:1085}"] = "刷{npc:1085}升级",
	["grind on {npc:1096}"] = "刷{npc:1096}",
	["{area:101}: kill these as you meet them"] = "{area:101}：沿途击杀以下目标",
	["{area:108} flight master"] = "{area:108}飞行管理员",
	["{area:150} flight master"] = "{area:150}的飞行管理员",
	["{area:301}: kill these as you meet them"] = "{area:301}：沿途击杀以下目标",
	["{area:33}: kill these as you meet them"] = "{area:33}：遇到就杀",
	["{area:35} flight master"] = "{area:35}的飞行管理员",
	["{area:442} flight master"] = "{area:442}的飞行管理员",
	["{item:190309}, north of {area:413}"] = "{item:190309}，在{area:413}北边",
	["{item:2006}: {object:58}; underwater"] = "{item:2006}：{object:58}；水下",
	["{item:2634}, from a {object:263} crate"] = "{item:2634}，来自{object:263}箱子",
	["{npc:2495}, by the bank; inside"] = "{npc:2495}，位于银行旁的屋内",
	["{npc:2495}, inside"] = "{npc:2495}：在屋内",
	["{npc:2495}: the Snapjaw Crocolisks, on the northern loop"] = "{npc:2495}：钳嘴鳄鱼，北部路线会去击杀",
	["{npc:2496}, upstairs in the tavern"] = "{npc:2496}，在旅店楼上",
	["{npc:2496}: the water elementals rise around the haunted island, on the northern loop"] = "{npc:2496}：水元素出没于闹鬼岛屿周围，北部路线会去",
	["{npc:2498}, inside"] = "{npc:2498}：在屋内",
	["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}，位于{object:56910}楼上",
	["{npc:469}, in the hut"] = "{npc:469}，在小屋里",
	["{npc:469}: {quest:200}'s records, on the northern loop (04b)"] = "{npc:469}：{quest:200}的档案，在北部环线（04b）",
	["{npc:5504}, the druid trainer, stands in {zone:1453}, north-west of the {object:2101}."] = "德鲁伊训练师{npc:5504}位于{zone:1453}，在{object:2101}西北边。",
	["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}，位于{object:56910}楼上",
	["{npc:687} on the way"] = "路上有{npc:687}",
	["{npc:715}, from {zone:1441}"] = "{npc:715}，来自{zone:1441}",
	["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716}收集{item:2755}：丛林中几乎所有人型怪都会掉落书页。边走边把书页合成章节。",
	["{npc:729} and the Lashtail raptors"] = "{npc:729}和鞭尾迅猛龙",
	["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "大老虎{npc:729}的巢穴在营地西南方的山顶；鞭尾迅猛龙在其南边、通往{area:35}的路上奔跑。",
	["{npc:737}, in the tavern"] = "{npc:737}，在旅店里",
	["{npc:737}, upstairs"] = "{npc:737}：在楼上",
	["{npc:737}: the Tumbled Crystals, on the northern loop"] = "{npc:737}：打磨过的水晶，北部路线会去收集",
	["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}：交给{area:35}的{npc:773}",
	["{npc:773}, in the tavern; upstairs"] = "{npc:773}，位于旅店楼上",
	["{npc:773}, upstairs"] = "{npc:773}：在楼上",
	["{npc:941}, below ground"] = "{npc:941}，地下",
	["{object:287}, upstairs"] = "{object:287}，楼上",
	["{object:288}, below ground"] = "{object:288}，地下",
	["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910}是港口上方的高楼；大多数任务发布者都在楼内各层或下方码头。",
	["{quest:201}: just look around the hunters' camp"] = "{quest:201}：在猎人营地四处看看即可",
	["{zone:1434}: kill these as you meet them"] = "{zone:1434}：沿途击杀以下目标",
	["{zone:1455} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{zone:1455}没有德鲁伊训练师：从{object:171524}乘{area:2257}到{zone:1453}，找{npc:5504}学习。",
}

G["forever/alliance/30-40/04b-stranglethorn-vale"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "“海狼”马克基雷，位于最顶层",
	["East to the {area:99}, on the way back to Nesingwary's camp."] = "向东前往{area:99}，顺路返回奈辛瓦里营地。",
	["East to {area:101}: Herod's records lie in a hut on its west side."] = "向东前往{area:101}：赫罗德的档案在其西侧的一间小屋中。",
	["Fly to {area:42}"] = "飞往{area:42}",
	["Follow the west coast north to the haunted island off the shore west of Nesingwary's camp: the Lesser Water Elementals rise from the water around it."] = "沿西海岸向北到奈辛瓦里营地以西近海的闹鬼小岛：次级水元素从它周围的水里升起。",
	["For Archmage Ansirem in {zone:1416}"] = "交给{zone:1416}的大法师安斯雷姆",
	["From {zone:1431} take the road south; the camp sits in the hills west of the road."] = "从{zone:1431}沿路向南；营地在道路西边的山丘中。",
	["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave, and Herod's strongbox sits by the cave mouth. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}."] = "库尔森精神医师在营地深处；库尔森特种兵潜行在营地周围及洞内，赫罗德的保险箱在洞口旁。掉落Green Hills书页时记得拾取。\n小心：库尔森特种兵为34-35级，非精英，出现时经常处于潜行状态；濒死时会使用{spell:7964}。",
	["Herod's records lie in a hut on the west side of {area:101}, east of the {area:99}."] = "赫罗德的档案在{area:101}西侧的一间小屋里，就在{area:99}东边。",
	["Into {zone:1434}"] = "进入{zone:1434}",
	["Kurzen Commando"] = "库尔森突击队员",
	["Kurzen Headshrinker"] = "库尔森缩颅者",
	["Level 36"] = "等级 36",
	["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "绕行北部和中部的巨魔废墟：每处都有一块记载巨魔传说的石板。深喉猎豹潜行在周围的丛林中；{area:37}的风险投资公司营地携带打磨过的水晶。",
	["Mauren, from Stonetalon"] = "莫伦，来自石爪山脉",
	["North along the coast to the ruins on the hill: the last two tablets lie there. Pick up Green Hills pages as they drop."] = "沿海岸向北前往山丘上的废墟：最后两块石板就在那里。掉落Green Hills书页时记得拾取。",
	["Shadowmaw Panther"] = "暗齿豹",
	["Skullsplitter trolls"] = "劈颅巨魔",
	["Snapjaw Crocolisks"] = "钳嘴鳄鱼",
	["Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to the Skullsplitter ruins."] = "钳嘴鳄鱼在丛林中央河流两侧晒太阳，向南前往劈颅废墟时会经过。",
	["South along the road: the hunters' tents stand just west of it."] = "沿路向南：猎人的帐篷就在道路西侧。",
	["South from the compound to {area:37}: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals, and the Shadowmaw Panthers prowl stealthed in the jungle south and east of it."] = "从营地向南前往{area:37}：湖岸营地中的风险投资公司地质学家携带打磨过的水晶，深喉猎豹潜行在湖南边和东边的丛林中。",
	["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "劈颅巨魔占据奈辛瓦里和{object:3202}之间道路东边的废墟。",
	["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "闹鬼岛屿就在第二块石板以西的近海：次级水元素在周围水中出现。",
	["The jungle ruins"] = "丛林废墟",
	["The {area:102}"] = "{area:102}",
	["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west."] = "向西穿过丛林前往巨魔废墟：每处都有一块记载巨魔传说的石板，前两块在奈辛瓦里营地西南的废墟中，后两块在西北的山丘上。",
	["grind on {npc:1152}"] = "刷{npc:1152}升级",
	["{item:2006}: {object:58}; underwater"] = "{item:2006}：在水下的{object:58}中寻找",
	["{npc:2495}, inside"] = "{npc:2495}：在屋内",
	["{npc:2496}, upstairs in the tavern"] = "{npc:2496}，在旅店楼上",
	["{npc:2498}, inside"] = "{npc:2498}：在屋内",
	["{npc:718}: the Shadowmaw Panthers prowl around {area:37}, after {area:101}"] = "{npc:718}：完成{area:101}之后，深喉猎豹在{area:37}周围游荡",
	["{npc:733}: the Commandos and Headshrinkers fell in the compound"] = "{npc:733}：特种兵和精神医师已经在营地击杀",
	["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}：交给{area:35}的{npc:773}",
	["{npc:773}, upstairs"] = "{npc:773}：在楼上",
	["{npc:773}: the ore drops from Drywhisker kobolds in {zone:1417}, next"] = "{npc:773}：矿石由接下来{zone:1417}的枯须狗头人掉落",
	["{npc:941}, below ground"] = "{npc:941}：在地下",
	["{object:287}, upstairs"] = "{object:287}：在楼上",
	["{object:288}, below ground"] = "{object:288}：在地下",
	["{quest:205}'s Skullsplitter trolls are 39-42. Below 36? Keep killing the Snapjaw Crocolisks along the river until level 36. Or, with a group, run the {area:796} dungeon (Armory) or the {area:1316} dungeon instead."] = "{quest:205}所需的劈颅巨魔为39-42级。还没到36级？继续沿河刷钳嘴鳄鱼，直到36级。也可以组队去{area:796}副本（军械库）或{area:1316}副本。",
	["{zone:1434}: kill these as you meet them"] = "{zone:1434}：遇到就杀",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
}

G["forever/alliance/30-40/05-arathi-highlands"] = {
	["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "一名{npc:2434}隐身潜伏在{area:271}边缘；杀死他并阅读他携带的合同。",
	["Argus Shadow Mage"] = "阿古斯暗影法师",
	["Back west through {zone:1430} to {area:42}."] = "向西穿过{zone:1430}回到{area:42}。",
	["Below ground"] = "在地下",
	["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside {npc:2320}'s house. {npc:2320} does not join when they are pulled, and a ranged attack through the doorway brings him out by himself."] = "注意：辛迪加间谍和刺客可能处于潜行状态，刺客还会施毒。\n注意：{npc:2320}的房屋内约有三名潜行辛迪加成员。拉出这些守卫时，{npc:2320}不会参战；清理后可从门外远程攻击，将他单独拉出。",
	["Crushridge ogres"] = "破碎岭食人魔",
	["Daggerspine Raider"] = "刺脊袭击者",
	["Daggerspine Sorceress"] = "刺脊女巫",
	["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "三把钥匙分别位于高地上的三个禁锢法阵，位置在碎片区以东、{area:320}附近和高地西侧。{object:2702}位于{area:320}以西。\n注意：各法阵的中心石周围约有三只 39 级元素生物，未清理就点击石头，会一起攻击你：西侧为烈焰流放者，外侧为雷霆流放者，东侧为水浪流放者。",
	["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "沿道路向东前往{area:76}。{npc:256028}怪物掉落水晶；木棒诺博鲁在废墟中游走，会掉落他的木棒。",
	["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "从{quest:681}向东穿过高地北部；碎片在{area:333}旁的山丘上闪闪发光，位于{area:314}以北。",
	["Ebenezer Rustlocke"] = "埃比尼泽·锈锁",
	["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves.\nCareful: The ambush is two level 40 water elementals, and they are immune to frost. If the fight happens inside the cave, the professor joins in instead of working and further elementals keep appearing; holding the elementals at the cave entrance, away from him, lets him finish with only the first two to deal with."] = "护送教授到海湾以北的沙滩，并在他工作时守护他；纳迦会一波波来袭。\n注意：伏击是两个40级的水元素，且免疫冰霜。如果战斗发生在洞内，教授会参战而不工作，还会不断出现更多水元素；把水元素挡在洞口、远离他，他就能只对付最初那两个并完成工作。",
	["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "护送教授上山，前往海湾上方的洞穴，并在他工作时保护他。那里会有两只40级水元素伏击，它们免疫冰霜。在洞口拦住它们，远离教授；如果在洞内战斗，教授会停下工作参战，水元素也会不断出现。",
	["Fly to {area:271}"] = "飞往{area:271}",
	["Fly to {area:42}"] = "飞往{area:42}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "沿道路向东离开{area:287}，越过{area:1057}前往{area:320}。",
	["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "沿路向北离开{area:271}进入山区。山地狮在坡上游荡；{area:280}的辛迪加成员戴着印章戒指，{npc:2306}在小镇北侧的庄园里走动。",
	["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings. {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps in the uplands north and north-west of the village."] = "沿道路向北离开{area:271}进入山区。山地狮在山坡上游荡；{area:280}的辛迪加成员戴着图章戒指。{npc:2306}（40级）每次只出现在一个地点：{area:280}旅店的地窖，或村庄北边和西北边高地上的某个辛迪加帐篷营地。",
	["Follow the road north to the draenei of the {area:657}."] = "沿道路向北前往{area:657}的德莱尼人处。",
	["For {npc:1440} in {zone:1453}: keep it"] = "交给{zone:1453}的{npc:1440}：保留它",
	["For {npc:2487} in {area:35}: keep it"] = "交给{area:35}的{npc:2487}：保留它",
	["For {npc:2542} in {area:35}: keep it"] = "交给{area:35}的{npc:2542}：保留它",
	["For {npc:2711} in {area:271}"] = "交给{area:271}的{npc:2711}",
	["From {zone:1455} take the tunnel east through {zone:1426} into {area:38} and follow the road to {area:144}."] = "从{zone:1455}经隧道向东穿过{zone:1426}进入{area:38}，再沿路前往{area:144}。",
	["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "从{zone:1455}出发，穿过{zone:1426}向东的隧道进入{zone:1432}，沿道路前往{area:144}。",
	["Hay Weevil"] = "干草象鼻虫",
	["Head back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "向东北返回，经过{area:320}；{npc:2712}和{npc:2713}在{area:314}以北的丘陵扎营。",
	["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "向北经过{area:314}；碎片在{area:333}旁的山丘上闪闪发光。",
	["Hulking Mountain Lion"] = "壮硕山地狮",
	["Inside"] = "在里面",
	["Mountain Lion"] = "山地狮",
	["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "向西北离开枯木山谷；{npc:2712}和{npc:2713}在{area:314}北侧不远的山丘扎营。",
	["Only if Gluggle gave you the pendant in Stranglethorn"] = "仅当格鲁高在荆棘谷给了你坠饰时",
	["Phizzlethorpe"] = "菲兹索普教授",
	["Shadowy Assassin"] = "暗影刺客",
	["Sorrow Spinner"] = "悲伤纺丝蛛",
	["South along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "沿西海岸向南，前往地精的海湾；哨兵鲁鲁在海湾上方的岩石上放哨。",
	["South from the {object:2691}, past {area:314}, to {area:317} in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk."] = "从{object:2691}向南，经过{area:314}，前往山丘中的{area:317}：枯木巫医站在小屋之间，枯木暗影猎手守在山谷尽头。每个巨魔都可能掉落獠牙。",
	["South-east along the loch to the dig site."] = "沿湖向东南前往挖掘场（铁环挖掘场）。",
	["South-east from Northfold to the Witherbark trolls in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley. Every troll here can drop a tusk."] = "从诺斯福德向东南到{area:314}以南山丘里的枯木巨魔；枯木巫医站在村子里，枯木暗影猎手守着山谷尽头。这里每只巨魔都可能掉落獠牙。",
	["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {area:130}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "向西南前往{area:279}以西湖岸的肯瑞托营地，刚过边界进入{area:130}：{npc:269127}就立在那里。大法师安斯雷姆站在它东南侧、圆顶旁。",
	["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "向西南前往{area:279}以西湖岸的肯瑞托营地，刚越过边界进入{zone:1421}：{npc:269127}站在那里。大法师安斯雷姆·鲁因维沃尔站在其东南的穹顶旁。",
	["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "跟随{npc:2713}潜入{area:314}并返回，途中会有部落兽人伏击。\n注意：兽人低血量时会逃跑，{npc:2713}会追击，可能引来更多怪。及时击杀或减速逃跑者。",
	["Subdue the succubus"] = "制服魅魔",
	["Summoned Incubus"] = "被召唤的男魅魔",
	["Swamp Jaguar"] = "沼泽美洲豹",
	["Syndicate Highwayman"] = "辛迪加路霸",
	["Syndicate Mercenary"] = "辛迪加雇佣兵",
	["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "破碎岭食人魔占据着{area:280}以北的山丘。再往北，一个破旧的木箱里装着{item:3706}；{quest:537}的{npc:2320}就站在旁边。",
	["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "枯须狗头人在部落城镇{area:321}以东峡谷采掘，从城镇北侧绕过。它们会掉落微粒和克拉兹克所需的矿石。\n注意：各种狗头人低血量时都会逃跑求援：普通狗头人于 30%，勘测员和掘地工于 15% 生命值逃跑，可能引来更多敌人。",
	["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "辛迪加占据着{area:320}西北的农场。一只{npc:217589}在农场里爬动：用{npc:217412}的昆虫学入门工具包抓住一只，然后勾掉任务。\n注意：辛迪加路霸是30-31级，能在脱战时施放潜行，因此常常处于潜行状态，很难发现。",
	["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "枯木巨魔住在{area:314}以南的山丘；枯木巫医在村子里，枯木暗影猎手守在山谷尽头。",
	["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "被遗忘者信使带着两名卫兵，沿道路从{area:314}向西穿过高地，最远到约24,45处，然后折返：箭头会沿道路向西指引，直到你遇到他。把他们引离道路。",
	["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "被遗忘者信使带着两名卫兵在{area:314}以西的路上行走；把他们引离道路。",
	["The shards lie at the far end of {area:318}."] = "碎片在{area:318}的尽头。",
	["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health."] = "典籍在{area:280}以西的废弃堡垒里；阿古斯暗影法师占据着废墟。\n注意：碎山好战者血量降到一半以下后，会呼叫15码内的附近盟友。",
	["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "两艘沉船在海湾以西的海湾里。海图和航海日志在船里；宝石在周围的海底。整个海湾都有刺脊纳迦游动。",
	["The western swamp"] = "西部沼泽",
	["The wrecked caravan lies off the road near Biggs.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "损毁的车队在比格斯附近的道路旁。\n注意：营地到处是38级左右的失落者。它们以2-3只连组行动，其中许多是施法者，且刷新很快。",
	["The wrecked caravan's chest lies at the north end of the {area:76}, beside {npc:5391}'s cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "被毁货车的箱子在{area:76}北端，{npc:5391}的笼子旁。\n小心：营地里到处是38级左右的迷失者。他们2-3个一组相互关联，很多是施法者，而且刷新很快。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:2417}是40级精英：大多数职业42级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "这些是精英敌人，建议寻找其他玩家组队完成。{npc:2417}是 40 级精英，多数职业到 42 级可以尝试单独击败，但可能仍需帮助。独自一人时可跳过，路线会安排刷怪补回经验。\n{npc:2417}会从箭头处向东北穿过废墟，走到约 40,47 处再返回：如果他不在箭头处，请沿他的路线寻找。",
	["Tram to {zone:1455}"] = "乘地铁前往{zone:1455}",
	["Walk back onto the span: Ebenezer lies under its Arathi end."] = "走回桥面：埃比尼泽躺在桥的阿拉希一端下方。",
	["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "沿海岸向西前往地精的海湾（法迪尔海湾）；哨兵鲁鲁在上方的岩石上放哨。",
	["Young Sawtooth Crocolisk"] = "年幼的锯齿鳄",
	["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "道路周围的沼泽里游荡着小鳄鱼、沼泽纺丝蛛和沼泽虎。",
	["{area:280}: kill these as you meet them"] = "{area:280}：沿途击杀以下目标",
	["{area:281}: kill these as you meet them"] = "{area:281}：沿途击杀以下目标",
	["{area:318}: kill these as you meet them"] = "{area:318}：沿途击杀以下目标",
	["{area:320} flight master"] = "{area:320}的飞行管理员",
	["{area:328}: kill these as you meet them"] = "{area:328}：沿途击杀以下目标",
	["{area:35} flight master"] = "{area:35}的飞行管理员",
	["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{npc:2438}的披风需要{item:2321}，如果没有就从{npc:2381}处购买",
	["{item:3658}: Crushridge ogres"] = "{item:3658}：破碎岭食人魔",
	["{item:3659}: the {object:1760}; inside"] = "{item:3659}：在{object:1760}内寻找",
	["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "从这一站附近的{npc:2572}、{npc:2573}和{npc:2574}身上获取{item:4435}",
	["{item:4492}; underwater"] = "{item:4492}：在水下",
	["{item:4525}; below ground"] = "{item:4525}：在地下",
	["{item:5040}; below ground"] = "{item:5040}：在地下",
	["{npc:1141}, {area:17203} road"] = "{npc:1141}，{area:17203}的路上",
	["{npc:12336}, Cathedral of Light"] = "{npc:12336}，光明大教堂",
	["{npc:1356}, {object:32356}: for {npc:1344} in {area:38}, next"] = "{npc:1356}、{object:32356}：给{area:38}的{npc:1344}，下一步",
	["{npc:1356}, {object:32356}: for {npc:1344} in {zone:1432}, next"] = "{npc:1356}，在{object:32356}：交给{zone:1432}的{npc:1344}，接下来会去",
	["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}，城堡里的皇家图书馆",
	["{npc:1470}, below ground"] = "{npc:1470}：在地下",
	["{npc:185335}, at the same circle"] = "{npc:185335}，在同一个法阵",
	["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}：在阿拉希、{zone:1443}和荆棘谷各捕捉一只小动物",
	["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}：捕捉它，用于{quest:93176}",
	["{npc:2276}, inside"] = "{npc:2276}：在屋内",
	["{npc:2438}, if you took his cloak quest"] = "{npc:2438}，如果你接了他的披风任务",
	["{npc:2595}, underwater"] = "{npc:2595}：在水下",
	["{npc:2596}, underwater"] = "{npc:2596}：在水下",
	["{npc:2700}: {npc:1075}'s plea, from 01-hillsbrad-foothills"] = "{npc:2700}：交01-hillsbrad-foothills中{npc:1075}的求援任务",
	["{npc:2705}, below ground"] = "{npc:2705}，在地下",
	["{npc:2712} and {npc:2713}"] = "{npc:2712}和{npc:2713}",
	["{npc:2713}'s errand"] = "{npc:2713}的差事",
	["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "食人魔法师{npc:2793}占据着枯木巨魔山谷南端的洞穴。",
	["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391}被关在避难所北端的笼子里。救出他，并在护送他出去时保护他存活；之后他的保险箱就在路边。",
	["{npc:5476} guards the road junction in the west of the swamp. {npc:217412} stands a short way north of him."] = "{npc:5476}守卫着沼泽西部的路口。{npc:217412}在他北边不远处。",
	["{npc:6122} binds the incubus to you"] = "{npc:6122}会将梦魇与你绑定",
	["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122}在{object:2101}{object:2164}的地下室等候。在那里的召唤法阵使用{item:6913}，击败召来的魅魔。如果你接了{quest:65602}，也把{item:190309}交给他，放在同一个法阵上，然后击败梦魇。",
	["{object:2652}, inside"] = "{object:2652}，室内",
	["{object:2707}; underwater"] = "{object:2707}：在水下",
	["{object:2708}; underwater"] = "{object:2708}：在水下",
	["{object:2709}; underwater"] = "{object:2709}：在水下",
	["{object:2710}; underwater"] = "{object:2710}：在水下",
	["{quest:65602}, if you took it"] = "{quest:65602}，如果你接了",
	["{zone:1455} flight master"] = "{zone:1455}飞行管理员",
}

G["forever/alliance/30-40/06-badlands"] = {
	["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "一只{npc:217590}在{area:596}里爬行：用{npc:217412}的昆虫学入门工具包中的工具抓住一只。",
	["Flesh Picker"] = "食腐者",
	["Fly to Theramore"] = "飞往塞拉摩岛",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Follow the road north to {area:608}."] = "沿道路向北到{area:608}。",
	["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "沿道路向北到{area:608}：{npc:5396}站在南端，{npc:5638}在中间，{npc:1182}在北边。",
	["Follow the road south to {area:2407}."] = "沿道路向南到{area:2407}。",
	["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "沿道路向西穿过{zone:1443}北部，到{area:2405}的废墟。{npc:11863}的塔就在那里的山丘上，在去残骸的路上。",
	["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "交给{area:2240}的{npc:4454}：{zone:1446}指南在45级时会经过，先留着",
	["Head back west to the road and follow it south out of {zone:1432} through the pass into the {area:3}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "回到西边的路上，沿路向南离开{zone:1432}，穿过山口进入{area:3}。{npc:2910}和{npc:2860}并排在挖掘场扎营。",
	["Head back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "向西回到道路，再沿路向南离开{zone:1432}，穿过山口进入{zone:1418}。{npc:2910}和{npc:2860}在挖掘场并排扎营。",
	["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "向东北前往废弃挖掘场，补给箱就在火烟食人魔之间。",
	["Head north-east to the dwarven ruins in the north of the {area:3}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "向东北前往{area:3}北部的矮人废墟；箱子在暗炉矮人中间。附近的{npc:2745}是精英：离他远点。",
	["Head north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "向东北前往{zone:1418}北侧的矮人废墟，箱子在暗炉矮人之间。附近的{npc:2745}是精英，注意避开。",
	["Head south down the road: {npc:4618} and {npc:2817} camp in the {area:1877}, on the way to {area:345}."] = "沿道路向南：{npc:4618} 和 {npc:2817} 驻扎在前往 {area:345} 途中经过的 {area:1877}。",
	["Head south to {area:345}."] = "向南前往{area:345}。",
	["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "向西进入{area:1878}；{npc:2921}在中央的机器旁工作。",
	["Into {area:3}"] = "进入{area:3}",
	["Into {zone:1418}"] = "进入{zone:1418}",
	["Lesser Rock Elementals"] = "次级石元素",
	["Maraudine centaurs"] = "玛洛迪半人马",
	["Off the boat, walk up the pier to Baldruc, the flight master by the gate of {area:514}."] = "下船后沿码头前往{area:514}大门旁的飞行管理员Baldruc。",
	["Rackmore's chest lies just south-east of the {object:177673}."] = "拉克摩尔的箱子在{object:177673}东南边不远处。",
	["Rock Elementals"] = "{npc:92}",
	["Ryedol's next errand goes into {area:1517}: skip it."] = "勘察员雷杜尔的下一个差事要进入{area:1517}：跳过。",
	["Stonevault Bonesnapper"] = "石窟断骨者",
	["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "火烟食人魔在山谷南边不远处扎营；任何一个都会掉落废料。秃鹫在东边的平原上空盘旋。\n破损的骷髅在石窟穴居人营地边缘；杀死阿格蒙德的凶手{quest:739}在石窟断骨者之间游荡。\n小心：火烟领主为44-45级。它们会使用{spell:5242}和{spell:1160}，生命值低于50%时会向15码内的同伴求援。有七个站在{area:340}以南约750码处。",
	["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nThe Lesser Rock Elementals wander the {area:1878} west of {npc:2921}.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "沙腮食人魔就在山谷南边扎营；他们中任何一个都会掉落废料。秃鹫在东边的平原盘旋。\n破烂的骷髅躺在石窟穴居人营地边缘；杀死阿格蒙德的凶手{quest:739}在断骨者中间走动。\n次级岩石元素在{npc:2921}西边的{area:1878}游荡。\n小心：沙腮领主是44-45级。他们会用{spell:5242}和{spell:1160}，生命值低于50%时会呼叫15码内的盟友支援。其中七个站在{area:340}以南约750码处。",
	["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards."] = "小型岩石元素在{npc:2921}西边的{area:1878}游荡；所有岩石元素都可能掉落{npc:1470}要的岩石元素碎片。",
	["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "玛洛迪半人马占据着墓地西边的{area:607}；每种都会掉落图腾。",
	["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "{npc:92}在{npc:2921}东南方游荡；{npc:2831}和{npc:2729}分布在它们西边的平原上。",
	["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "暗炉矮人在挖掘场北边不远处扎营；弄皱的地图在他们的帐篷之间。暗炉隧道工和暗炉巫师带着勘察员雷杜尔的镐。{npc:2727}在周围的山坡上游荡。",
	["The Slitherblade naga hold the north-west coast north of {npc:11863}'s tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}."] = "滑刃纳迦占据着{npc:11863}的塔楼北边的西北海岸；卡尼托的挎包就在近海的海底，任何纳迦都可能掉落拉克摩尔的金钥匙。游到最北端外海的{area:2406}，对{object:177673}使用{item:15766}：{npc:12369}（38级）会出现；杀死他获得{quest:6027}。",
	["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "破损的骷髅就在食人魔东边、石窟穴居人营地边缘；周围的石窟断骨者和石窟萨满祭司掉落碎片。迷失者塞尔杜林坐在更南边的废弃营地旁。",
	["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "蚌壳在荆棘谷西北海岸，在下一份指南里：先留着",
	["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "恶魔聚集在{zone:1443}南部的{area:602}：坑周围有地狱犬（噬法魔犬、法师猎手和灵能猎犬）、地狱魔女、虚空姐妹以及末日看守队长。\n注意：这里多数怪物会巡逻，容易额外引怪。",
	["The excavation crate"] = "挖掘补给箱",
	["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "飞行管理员站在{area:514}的门口；{npc:5083}和{npc:4964}在城堡内。",
	["The next guide starts in Theramore."] = "下一份指南从塞拉摩岛开始。",
	["The skeleton's next task, {quest:739}, waits until the later {area:3} guide at 43."] = "骷髅的下一个任务{quest:739}要等到后面43级的{area:3}指南。",
	["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "失事船只的箱子在{npc:11863}的塔西南边不远处。",
	["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "失事船只的箱子在{npc:11863}的塔西边不远的岸上。",
	["The {area:2657}"] = "{area:2657}",
	["The {object:126260}"] = "{object:126260}",
	["Theramore"] = "塞拉摩岛",
	["Theramore flight master"] = "塞拉摩飞行管理员",
	["To {area:2101}"] = "前往{area:2101}",
	["Undead Ravager"] = "亡灵劫掠者",
	["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "{npc:11561}在玛格拉姆村南边、集会所东边的骨原上游荡；在最东南端使用{item:15848}引出{npc:11560}。",
	["Underwater"] = "在水下",
	["escort {npc:12277} back toward the graveyard"] = "护送{npc:12277}回到墓地",
	["for the Dustwallow loop in the next guide"] = "留给下一份指南的尘泥沼泽环线",
	["for {npc:2786} in {zone:1455}: keep it"] = "交给{zone:1455}的{npc:2786}：先留着",
	["for {npc:3980} in {area:271}: keep it"] = "交给{area:271}的{npc:3980}：先留着",
	["for {npc:5637} in {zone:1455}: keep it"] = "交给{zone:1455}的{npc:5637}：先留着",
	["only if you carry {item:2868} (a blacksmith's craft)"] = "仅当你带着{item:2868}（铁匠制品）",
	["{area:144} flight master"] = "{area:144}的飞行管理员",
	["{area:345}: kill these as you meet them"] = "{area:345}：沿途击杀以下目标",
	["{area:346}: kill these as you meet them"] = "{area:346}：沿途击杀以下目标",
	["{area:598}: kill these as you meet them"] = "{area:598}：沿途击杀以下目标",
	["{item:15766}, on the {object:177673}"] = "{item:15766}，对{object:177673}使用",
	["{item:15881}, from the Slitherblade naga"] = "{item:15881}，由滑刃纳迦掉落",
	["{item:4631}; below ground"] = "{item:4631}：在地下",
	["{item:5797} on the way"] = "路上拿{item:5797}",
	["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} 被关在墓地西边的半人马营地中。救出她，并在离开营地的路上保护她活下来；她会在墓地旁停下。\n注意：护送途中触发的敌群会一起加入战斗，而且仅在护送时出现，因此无法提前清除，也无法逐个引出。不过，开始前先清除沿途的普通半人马会有所帮助。",
	["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}是一个半人马首领，在{npc:11863}的塔北边的西北海岸扎营。",
	["{npc:1470}, in the inn; below ground"] = "{npc:1470}，位于旅店地下室",
	["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}：抓住它，用于My Little Friends",
	["{npc:2893}, 130 yd north"] = "{npc:2893}，以北130码",
	["{npc:2920}, beside {npc:2921}"] = "{npc:2920}，在{npc:2921}旁边",
	["{npc:2920}, beside {npc:2921}, wants {item:2868}, a blacksmith's craft: skip him unless you carry a pair."] = "{npc:2920}就在{npc:2921}旁边，他要{item:2868}，那是锻造做的：除非你身上带着一对，否则跳过他。",
	["{npc:2921}'s last test is optional: five {item:4628}, which only the Greater Rock Elementals (42-44) in the south-western gulches drop, about one kill in five, well above your level. Take it only if you can handle them one at a time; otherwise hand in the slabs and move on."] = "{npc:2921}的最后一项试验可选：需要五个{item:4628}，只有西南沟壑的巨型石元素（42-44级）掉落，约杀五只掉一个，等级远高于你。只有能一次对付一只时才接；否则交完石片就继续赶路。",
	["{npc:2921}'s next test needs crafted gear: skip it."] = "{npc:2921}的下一个测试需要制作的装备：跳过。",
	["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {area:3}."] = "{npc:4618}和{npc:2817}一起在{area:3}中部的{area:1877}扎营。",
	["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618}和{npc:2817}一起在{zone:1418}中部的{area:1877}扎营。",
	["{npc:4964}, on the top floor"] = "{npc:4964}，顶层",
	["{npc:5083}, on the top floor"] = "{npc:5083}，顶层",
	["{npc:5638}, if 30-40/02 didn't take it: the wreck lies below {npc:11863}'s tower"] = "{npc:5638}，如果30-40/02没有接这个任务：残骸在{npc:11863}的塔下方",
	["{npc:5638}: the wreck is on the north-west coast, at the end of the loop"] = "{npc:5638}：残骸在西北海岸，在环线尽头",
	["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons."] = "{npc:6019}站在{area:2407}西南方的{area:596}边缘；{object:176751}散落在骨架之间。",
	["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019}站在{area:2407}西南方的{area:596}边缘；{object:176751}散落在骨架之间。一只{npc:217590}在墓地里爬行：用Entomology Starter Kit抓住一只，然后勾选完成。",
	["{object:177787} lies beside {object:35251}. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787}在{object:35251}旁边。他的银钥匙由残骸周围的干钳蟹掉落；金钥匙接下来从西北海岸的滑刃纳迦身上获得。",
	["{quest:739} himself (42) walks among the Bonesnappers: leave him for the later {area:3} guide at 43, and kill the Bonesnappers for this quest now."] = "{quest:739}本人（42级）在断骨者中间走动：把他留到43级时后面的{area:3}指南，现在为这个任务先杀断骨者。",
	["{quest:739} himself (42) walks among the Bonesnappers: leave him for the later {zone:1418} guide at 43, and kill the Bonesnappers for this quest now."] = "{quest:739}本人（42级）在Bonesnappers之间走动：留到43级、后面的{zone:1418}指南再打他，现在先杀Bonesnappers完成此任务。",
}

G["forever/alliance/40-50/01-stranglethorn-vale"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "“海狼”马克基雷，位于最顶层",
	["\"Stinky\" Ignatz"] = "伊格纳兹",
	["Arbor Tarantula"] = "树栖狼蛛",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "达到 40 级并准备 100 金即可学习骑术，学习时会获得坐骑。天裔可向{npc:265756}学习；这名兽栏管理员兼骑术训练师位于泽风岛的{area:16638}，在{area:17684}处，同时出售疾风陆行鸟。前往岛屿的飞空艇约每五分钟从{area:279}北侧出发。在“收集→坐骑·40 级”可查看疾风陆行鸟。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {area:12}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40级时花100金就能学骑术，学会后可获得一匹坐骑。{npc:4732}在{area:12}东部的{area:88}教人类，就在{npc:384}的马匹旁。无限可能允许任何种族向任何骑术训练师学习（未经证实）。收藏·坐骑·40级列出了所有颜色。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40级且有100金时可以学习骑术，学会后会获得一匹坐骑。{npc:4732}在{zone:1429}东部的{area:88}教授人类，旁边是{npc:384}的马。无限 可能允许任何种族向任何骑术训练师学习（未确认）。收藏指南“坐骑 · 40级”列出了所有颜色。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {area:12}. Collectibles, Mounts · Level 40 lists every colour."] = "40级时花100金就能学骑术，学会后可获得一匹坐骑。{npc:4753}在{zone:1457}教暗夜精灵，就在{npc:4730}的刃豹旁：从{area:17203}坐船到{area:442}，再飞往{area:702}。无限可能允许任何种族向任何骑术训练师学习（未经证实），例如{area:12}中{area:88}的{npc:4732}。收藏·坐骑·40级列出了所有颜色。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "40级且有100金时可以学习骑术，学会后会获得一匹坐骑。{npc:4753}在{zone:1457}教授暗夜精灵，旁边是{npc:4730}的豹：从{area:17203}乘船前往{area:442}，再飞往{area:702}。无限 可能允许任何种族向任何骑术训练师学习（未确认），例如{zone:1429}{area:88}的{npc:4732}。收藏指南“坐骑 · 40级”列出了所有颜色。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40级且有100金时可以学习骑术，学会后会获得一匹坐骑。{npc:4772}在{area:803}教授矮人，位于{area:131}东边通往{zone:1432}的路上，旁边是{npc:1261}的山羊。无限 可能允许任何种族向任何骑术训练师学习（未确认）。收藏指南“坐骑 · 40级”列出了所有颜色。",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40级且有100金时可以学习骑术，学会后会获得一匹坐骑。{npc:7954}在{area:131}东边不远的{area:189}教授侏儒，旁边是{npc:7955}的机械陆行鸟。无限 可能允许任何种族向任何骑术训练师学习（未确认）。收藏指南“坐骑 · 40级”列出了所有颜色。",
	["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "回到塞拉摩：特沃什和吉安娜女士在{area:514}的塔里等你。",
	["Bloodsail Swashbuckler"] = "血帆剑客",
	["Bloodsail camp"] = "血帆营地",
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Boat to {area:17203}"] = "乘船前往{area:17203}",
	["Boat to {area:35}"] = "乘船前往{area:35}",
	["Cold Eye Basilisks"] = "冷眼蜥蜴",
	["Cortello's scroll"] = "科泰罗的卷轴",
	["Defeat the challengers and {npc:6238}"] = "击败挑战者和{npc:6238}",
	["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "每个血帆海盗都掉落鼻烟，其中一个携带{npc:2493}的眼睛；血帆流氓在镇子北边的岸上游荡。海图和命令在{area:35}南边{area:43}的海盗营地里。",
	["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "每个赞吉尔的追随者都可能掉落药剂；{npc:2537}在营地南部走动。",
	["Fly to {area:144}"] = "飞往{area:144}",
	["Fly to {area:1537}"] = "飞往{area:1537}",
	["Fly to {area:35}"] = "飞往{area:35}",
	["Fly to {area:42}"] = "飞往{area:42}",
	["Fly to {area:442}"] = "飞往{area:442}",
	["Fly to {area:702}"] = "飞往{area:702}",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "沿道路向东返回塞拉摩。特沃什、吉安娜女士和军官们在塔楼和{area:514}里。",
	["Follow the road east back to Theramore. The officers are in {area:514}."] = "沿道路向东返回塞拉摩。军官们在{area:514}里。",
	["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "沿路向西北离开塞拉摩，前往{area:503}的瞭望塔。泥岩掘地者在塔周围的沼泽里游荡。",
	["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\n{npc:4967} waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore."] = "沿道路向西北离开塞拉摩，前往{area:503}的瞭望塔。泥石穴居龟在周围的沼泽中游荡。\n{npc:4967}在塔脚下等候：四处查看后，直接在那里向他交任务，不用回塞拉摩。",
	["Gorilla hills"] = "猩猩山丘",
	["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "交还牙齿后留下：会来三波猩猩，最后是{npc:1514}。满血再战。",
	["If you skipped {quest:193}, grind here to level 42.06 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "如果你跳过了{quest:193}，就在这里刷到42.06级，以保持攻略的节奏。或者组队去刷{area:1517}副本。",
	["If you skipped {quest:193}, grind here to level 42.23 to stay on the route's plan."] = "如果你跳过了{quest:193}，就在这里刷到42.23级，以跟上本路线的进度规划。",
	["If you skipped {quest:196}, grind here to level 42.1 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "如果你跳过了{quest:196}，就在这里刷到42.1级，以保持攻略的节奏。或者组队去刷{area:1517}副本。",
	["If you skipped {quest:196}, grind here to level 42.27 to stay on the route's plan."] = "如果你跳过了{quest:196}，就在这里刷到42.27级，以跟上本路线的进度规划。",
	["If you skipped {quest:208}, grind here to level 42.16 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "如果你跳过了{quest:208}，就在这里刷到42.16级，以保持攻略的节奏。或者组队去刷{area:1517}副本。",
	["If you skipped {quest:208}, grind here to level 42.33 to stay on the route's plan."] = "如果你跳过了{quest:208}，就在这里刷到42.33级，以跟上本路线的进度规划。",
	["If you skipped {quest:543}, grind here to level 42.46 to stay on the route's plan."] = "如果你跳过了{quest:543}，就在这里刷到42.46级，以跟上本路线的进度规划。",
	["If you skipped {quest:543}, grind here to level 42.46 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "如果跳过了{quest:543}，在这里刷怪补到42.46级，以跟上路线进度。也可以组队刷{area:1517}地下城。",
