G["forever/alliance/40-50/03-feralas"] = {
	["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "回到{area:1117}。那里的每个憎世纳迦都可能掉落鳞片。",
	["Boat to the {area:1108} and ride east across {area:357} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "坐船到{area:1108}，向东骑过{area:357}到路北的恐怖图腾营地。{npc:7956}在营地外等着；把精灵龙从中间的围栏里放出来，并保住{npc:7956}和至少六只精灵龙。",
	["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "乘船前往{area:1108}，向东骑进{area:1105}。{npc:14637}在海岸的任务需要45级。",
	["Boat to {area:1108}"] = "乘船前往{area:1108}",
	["Boat to {area:1116}"] = "乘船前往{area:1116}",
	["Feathermoon flight master"] = "羽月要塞飞行管理员",
	["Fly to {area:489}"] = "飞往{area:489}",
	["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "从{area:489}沿路向西骑行，前往道路北侧的恐怖图腾营地。{npc:7956}在营地外等候；救出中央围栏中的小精龙，并确保{npc:7956}和至少六只小精龙存活。",
	["Gordunni Brute"] = "戈杜尼蛮兵",
	["Gordunni Shaman"] = "戈杜尼萨满祭司",
	["Gordunni Warlock"] = "戈杜尼术士",
	["Gordunni ogres"] = "戈杜尼食人魔",
	["Grimtotem Naturalist"] = "恐怖图腾自然学家",
	["Grimtotem Raider"] = "恐怖图腾劫掠者",
	["Grimtotem Shaman"] = "恐怖图腾萨满祭司",
	["Grimtotem camp"] = "恐怖图腾营地",
	["Grimtotem tauren"] = "恐怖图腾牛头人",
	["Grind to 45"] = "刷到45级",
	["Hatecrest naga"] = "憎世纳迦",
	["Into {area:17}"] = "进入{area:17}",
	["Into {zone:1413}"] = "进入{zone:1413}",
	["Ride back to the {area:1108}; the goblin stands by the dock."] = "骑回{area:1108}；那个地精站在码头旁。",
	["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "沿道路向西骑回，然后向北进入怒痕山丘。这里的每个雪人都可能掉落毛皮；可能会掉落{quest:7735}，{npc:7852}也会收购。",
	["Ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "骑马向东进入{area:1105}。海岸上{npc:14637}的任务需要45级。也可以组队去{area:978}副本或{area:1517}副本。",
	["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "向东骑到雪人山谷东南方山丘上的戈杜尼营地：戈杜尼术士和戈杜尼萨满祭司占据着营地，戈杜尼蛮兵在周围和更北边的山坡上游荡。",
	["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "向北骑进雪人山谷。每个深痕雪人都可能掉落厚毛皮；{npc:5346}（48级）在中间潜行。",
	["Ride north-east to the night elf outpost on the {zone:1441} border."] = "向东北骑到{zone:1441}边境上的暗夜精灵前哨。",
	["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "向东南骑到木爪豺狼人那里；信使的背包在它们南边的营地里，其中的一个包裹会开始一个送往{area:489}的任务。祖卡什虫巢就在南边：一路打到关着拉斯卡尔的茧，救出他并在出去的路上保护他。",
	["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "{npc:5359}、{npc:5360}和{npc:5361}（精英巨人）在码头北边的海岸涉水：用{item:18904}电一只，然后杀掉缩小的巨人。{npc:5461}和{npc:5462}在同一片浪花中飘荡。",
	["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "乘船前往{area:1108}，沿海岸向南走到海滩上失事的小船。",
	["The courier's boat"] = "信使的船",
	["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121}是{area:1120}南侧的岛屿，游过去即可。这里由憎世毒蛇守卫和女巫占据，47 级的{npc:8136}在岛屿南端洞穴内等候，先清理他的守卫。",
	["The {zone:1446} guide starts with the trip east, past {area:489}."] = "{zone:1446}指南从向东赶路开始，途中经过{area:489}。",
	["Walk south along the island to the naga ruins; the gazebo stands among them."] = "沿岛向南走到纳迦废墟；索兰萨尔瞭望台在废墟中。",
	["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "你在{area:1108}的码头结束：{zone:1446}指南从这里向东出发开始。",
	["for Tyrande in {zone:1457}: the route takes you there at 47"] = "交给{zone:1457}的泰兰德·语风：路线会在47级带你去那里",
	["grind on {npc:5292} at {area:1105}, {area:357}"] = "在{area:1105}、{area:357}刷{npc:5292}",
	["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "在{zone:1444}的{area:1105}刷{npc:5292}",
	["{area:1108}: kill these as you meet them"] = "{area:1108}：沿途击杀以下目标",
	["{area:1116} stands on {area:1120}, off the {area:1108}: the boat from the coast's dock crosses to it. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{area:1116}位于{area:1108}近海的{area:1120}，可从海岸码头乘船前往。{npc:7880}在建筑楼上，从屋内上楼，箭头无法区分楼层。",
	["{area:1136}: kill these as you meet them"] = "{area:1136}：沿途击杀以下目标",
	["{area:489} flight master"] = "{area:489}的飞行管理员",
	["{item:11463}, from the backpacks"] = "{item:11463}，来自背包",
	["{item:9248}; below ground"] = "{item:9248}：在地下",
	["{npc:14637}'s refills are level 55: skip them."] = "{npc:14637}的补充任务是55级：跳过。",
	["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936}接着会让你把消息带到{zone:1457}：跳过，{area:976}会让你去那里。",
	["{npc:3936}, beside him"] = "{npc:3936}，在他旁边",
	["{npc:4048} walks around {area:489}: look inside the circle on the map"] = "{npc:4048}在{area:489}巡逻，请在地图标示的圆圈内寻找",
	["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}：他的回复之后在{area:702}等你",
	["{npc:7877}, at the top of the stronghold"] = "{npc:7877}，在要塞顶层",
	["{npc:7879}, upstairs"] = "{npc:7879}：在楼上",
	["{npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:7880}在建筑楼上，从屋内上楼，箭头无法区分楼层。",
	["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136}留到大陆环线结束时。",
	["{object:164954}, inside"] = "{object:164954}：在屋内",
}

G["forever/alliance/40-50/04-tanaris"] = {
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "注意：窃贼会缴械，游荡者会潜行隐藏，刺客会在你生命值降到 20% 或以下时使用斩杀。",
	["Dunemaul Brute"] = "砂槌蛮兵",
	["Dunemaul Enforcer"] = "砂槌打手",
	["Fly to Theramore"] = "飞往塞拉摩岛",
	["Fly to {area:348}"] = "飞往{area:348}",
	["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "沿海岸向南前往海盗海湾。南海海盗密布在海滩和船上：沿边缘推进，每次只引一名。{npc:7883} 在另一侧；{npc:7881} 被盗的货物就在营地中。\n注意：{npc:7883} 身边有两三名海盗，一旦开战，镇上还会有许多海盗加入战斗。",
	["Gives the {item:8585}"] = "获得{item:8585}",
	["Gnarled Thistleshrub"] = "多节的蓟灌木",
	["Gor'marok the Ravager"] = "蹂躏者戈玛洛克",
	["He runs off to keep Rizzle busy"] = "他会跑去拖住瑞兹尔·铜栓",
	["Pool by {area:979}"] = "{area:979}旁的水池",
	["Ride back west to {area:976}."] = "向西骑回{area:976}。",
	["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "向西骑行返回{area:976}方向，废土强盗和窃贼占据沿途沙丘，均有几率携带水袋。\n注意：43–44 级的废土游荡者会潜行移动，可能在你未察觉时靠近。",
	["Ride east across the dunes to the goblin harbour on the north-east coast."] = "向东骑过沙丘到东北海岸的地精港口热砂港。",
	["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "向西北骑行前往沙丘中的森提帕尔虫巢，所有森提帕尔异种虫都有几率掉落昆虫肢体。\n注意：森提帕尔群居蝎在战斗内外都会施放{npc:4196}，召来会打断你的幼虫。",
	["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "向西北骑到{area:979}的沙怒巨魔营地。在水池边缘使用{item:8584}；巨魔站得很近，先拉最近的。",
	["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "向南骑行进入{quest:3362}。露水收集者会掉落腺体，但只有部分是装满的，保留充满的那种。长瘤的灌木兽和根须挖掘者也在山谷内。灌木兽为 48–50 级，高于你当前等级，逐个拉怪。\n注意：附近其他灌木兽为 49–50 级，而且经常走动，容易额外引怪。",
	["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "骑行向南经过{area:1938}，前往{area:981}的哈扎里隧道，谢申克的设备在深处。\n注意：设备旁有一只虫子守卫，隧道里还有许多巡逻虫，其中一些达到 50 级，战斗经常引来额外敌人。",
	["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "向南骑到{area:1938}的挖掘营地。{npc:7771}会给你一顶探测头盔：戴上它才能看到{quest:3161}土堆，营地周围和向西南通往食人魔的沙地里到处都是。",
	["Ride south-east off the {area:439} into {area:440}. {area:976} is just inside the border."] = "骑马向东南离开{area:439}进入{area:440}。{area:976}就在边界内侧。",
	["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "向东南骑出{area:439}进入{zone:1446}。{area:976}就在边界内。",
	["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "向东南骑行前往{area:985}。{npc:7847}站在南部废土营地中央：先清理他周围的敌人。\n小心：他走到哪里都有两名潜行的废土游荡者跟随。在他的刷新营地里，两名暗影法师及其仆从离得很近，会加入战斗。到塔楼附近就可以避开他们，单独与他交战。",
	["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "向西南骑到砂槌营地。里面满是砂槌蛮兵和砂槌执行者（46-48级）；{npc:12046}（49级）站在中间，周围有卫兵：先清理卫兵。",
	["Southsea Dock Worker"] = "南海码头工人",
	["Southsea Freebooter"] = "南海劫掠者",
	["Southsea Pirate"] = "南海海盗",
	["Southsea Swashbuckler"] = "南海剑客",
	["The Wanted poster beside him"] = "他旁边的通缉布告",
	["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "小乌龟{npc:5955}躲在山谷北端。带他回家去找他妻子{npc:6015}，她在{area:977}东边不远处的水边：他走得慢，沙漠里的野兽会攻击他，保护好他。",
	["The pool by {area:979}"] = "{area:979}旁的水池",
	["The same poster: {npc:7847} comes much later, after {area:976}"] = "同一张告示：{npc:7847}要很久以后才会出现，在{area:976}之后",
	["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "更强的废土游荡者、暗影法师和刺客在{area:976}东南、强盗区域以南扎营。南侧营地中央的{npc:7847}留到稍后再处理。\n注意：废土游荡者在非战斗状态下会保持潜行，营地中隐藏的盗贼可能加入你发起的战斗。",
	["The {area:1938}"] = "{area:1938}",
	["The {area:2240} lies on the {area:439} in south-east {area:400}. {npc:4454} and {npc:4630} are in the camps beside the track.\n{npc:4709} stands by the goblin camp.\nWhile {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "{area:2240}位于{area:400}东南的{area:439}上。{npc:4454}和{npc:4630}在赛道旁的营地。\n{npc:4709}站在地精营地旁。\n趁{npc:4709}缠住里兹尔说话时，他的计划就无人看守地放在赛道对面的侏儒营地里。",
	["The {area:2240} lies on the {area:439} in south-east {area:400}: {npc:4454} is in the gnomes' camp beside the track, {npc:4709} by the goblin camp."] = "{area:2240}位于{area:400}东南的{area:439}上：{npc:4454}在赛道旁的侏儒营地，{npc:4709}在地精营地旁。",
	["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, {npc:4709} by the goblin camp."] = "{area:2240} 位于 {zone:1441} 东南部的 {area:439}：{npc:4454} 在赛道旁的侏儒营地内，{npc:4709} 在地精营地旁。",
	["Thistleshrub Rootshaper"] = "蓟灌木塑根者",
	["Underwater"] = "在水下",
	["Wastewander Assassin"] = "废土刺客",
	["Wastewander Bandit"] = "废土强盗",
	["Wastewander Rogue"] = "废土盗贼",
	["Wastewander Shadow Mage"] = "废土暗法师",
	["Wastewander Thief"] = "废土窃贼",
	["for {zone:1457}: the route takes you there at 47"] = "交给{zone:1457}：路线会在47级带你去那里",
	["grind on {npc:5474}"] = "反复击杀{npc:5474}补足经验",
	["{area:1336}: kill these as you meet them"] = "{area:1336}：沿途击杀以下目标",
