G["forever/alliance/50-60/04-western-plaguelands"] = {
	["Andorhal"] = "安多哈尔",
	["Andorhal Tower Four"] = "安多哈尔四号塔",
	["Andorhal Tower One"] = "安多哈尔一号塔",
	["Andorhal Tower Three"] = "安多哈尔三号塔",
	["Andorhal Tower Two"] = "安多哈尔二号塔",
	["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "回到{npc:7765}东南方不远处{npc:7775}的营地：{item:11242}能换三瓶维迪尔药剂。留着它们：{npc:9298}要一瓶，而{area:976}的{npc:9299}只会向喝过药剂的人现身。",
	["Below ground"] = "在地下",
	["Boat to {area:1108}"] = "乘船前往{area:1108}",
	["Cavalier Durgen"] = "骑士杜根",
	["Climb the hill west of {area:190} to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "爬上{area:190}西侧山丘，俯瞰城镇。\n注意：大门处的哨兵能够侦测潜行玩家，镇内也有更多哨兵，附近还有一名精英巡逻。",
	["Collie is up the hill behind it."] = "科利在它后面的山上。",
	["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "向东过河到{area:2261}，即区域西南部的地穴。{object:177667}在里面：它的钥匙在东北远端的{npc:12248}身上，在下一份指南中完成。",
	["Cross the river west to {npc:1855}'s hut."] = "向西过河到{npc:1855}的小屋。",
	["Cross the south of the crater to {npc:9619} by the ramp."] = "穿过环形山南部，到坡道旁找{npc:9619}。",
	["Diseased Grizzlies"] = "生病的灰熊",
	["Diseased Grizzly"] = "患病灰熊",
	["Diseased Wolf"] = "患病狼",
	["Dredge Crusher"] = "挖掘粉碎者",
	["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "掘泥摧毁者在更西边挖掘；石鞭巨钳蝎、石鞭掠夺者和石行蜘蛛在同一片沙地狩猎。",
	["Dredge Striker"] = "挖掘打击者",
	["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "掘泥打击者在要塞西北方的沙丘中挖掘；石鞭蝎和掠沙蜘蛛在四周游荡。",
	["Ends with {npc:9298} in {area:618}: keep it"] = "以{area:618}的{npc:9298}收尾：保留",
	["Ends with {npc:9298} in {zone:1452}: keep it"] = "在{zone:1452}的{npc:9298}处结束：留着",
	["Escort {npc:9999}"] = "护送{npc:9999}",
	["Fly from {area:976} to {area:541}. {npc:8737} stands at the back of the refuge; {npc:9117} is in the cave behind him.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "从 {area:976} 飞往 {area:541}。{npc:8737} 站在避难所后方；{npc:9117} 在他身后的洞穴里。\n{npc:9997} 的朋友 {npc:9999} 失踪了。",
	["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; J.D.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "从{area:976}飞往{area:541}。{npc:8737}的小屋位于庇护所西边的{area:538}；J.D.\n{npc:9997}的朋友{npc:9999}失踪了。",
	["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; {npc:9117} is up the hill behind it.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "从{area:976}飞往{area:541}。{npc:8737}的小屋在庇护所西边的{area:538}；{npc:9117}在小屋后面的山上。\n{npc:9997}的朋友{npc:9999}失踪了。",
	["Fly to Theramore"] = "飞往塞拉摩岛",
	["Fly to {area:2255}"] = "飞往{area:2255}",
