G["forever/alliance/dwarf/01-dun-morogh"] = {
	["Back east through {area:131}: the class quests here wait for level 10."] = "向东经过{area:131}返回，此处职业任务需等到 10 级。",
	["Back through the tunnel to {npc:257597}' cave above the farm."] = "穿过隧道回到农场上方{npc:257597}的洞穴。",
	["Back to the tunnel post"] = "返回隧道哨站",
	["Back to the {area:925}"] = "返回 {area:925}",
	["Back to {area:77}"] = "返回{area:77}",
	["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "回到{area:77}找{npc:257446}。他会给你{item:6635}：沿着山谷南部向西攀升、标有碎石的小路走到山脊上的灵魂石，在旁边喝下圣水并与{npc:5891}交谈，然后把它的{item:6656}带回给提欧·暴风之锤。",
	["Back to {npc:257597}"] = "返回{npc:257597}处",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:40} is next, west of {area:87}."] = "回到{npc:6122}。在{object:2164}地窖里的召唤法阵上使用{item:6928}，击败它召唤出的虚空行者。接下来去{area:40}，在{area:87}西边。",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:87} and east Elwynn are next, then {zone:1436}."] = "返回 {npc:6122} 处。在 {object:2164} 地窖的召唤法阵中使用 {item:6928}，击败召唤出的虚空行者。接下来去 {area:87} 和艾尔文东部，然后前往 {zone:1436}。",
	["Bartleby"] = "巴特莱比",
	["Below ground"] = "在地下",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Class trainer"] = "职业训练师",
	["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "{npc:1125}和{npc:1128}在{area:131}和补给站周围的田野里游荡。",
	["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "{npc:1125}和{npc:1128}在从隆布沙特的营地往东北到{area:131}和补给站之间的田野里游荡：回程路上击杀它们。",
	["Dark Iron Spy"] = "黑铁间谍",
	["Deeprun Rat"] = "矿道鼠",
	["Druid trainer"] = "德鲁伊训练师",
	["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "格瑞夫的每个任务都会给你一根{item:15908}：对他指定的野兽使用，然后把驯兽棒带回{area:131}铁匠铺交给他。{npc:1126}、{npc:1201}和{npc:1196}都在{area:131}南边和东边的田野里游荡。",
	["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats."] = "沿山地向东，前往湖泊北端的矿洞：Miners' League 的箱子在洞内隧道中，周围还有更多坑道鼠。",
	["East back into {object:171524}: the {area:2257} leaves from its east end. Ride it to {zone:1453}."] = "向东返回 {object:171524}：{area:2257} 从其东端发车。乘车前往 {zone:1453}。",
	["East from the {object:32372} into {object:171524}: the {object:660964} lie by its mailbox. From here the guide goes once round the city: north to the {object:32383}, west to the {object:32362}, south through the Commons to the {object:171709}, east through the {object:32359} and back to {object:171524} for the tram."] = "从 {object:32372} 向东进入 {object:171524}：{object:660964} 在那里的邮箱旁。接下来按指南绕城一圈：向北到 {object:32383}，向西到 {object:32362}，向南穿过平民区到 {object:171709}，再向东穿过 {object:32359}，回到 {object:171524} 乘坐地铁。",
	["East through the South Gate tunnel into {area:38}. {npc:1089} and {npc:1092} stand at the dwarven post just past it."] = "穿过南门隧道向东进入{area:38}。{npc:1089}和{npc:1092}守在刚出隧道的矮人岗哨。",
	["East through the South Gate tunnel into {zone:1432}. {npc:1089} and {npc:1092} stand at the dwarven post just past it."] = "向东穿过南门隧道，进入 {zone:1432}。{npc:1089} 和 {npc:1092} 站在隧道出口附近的矮人哨站。",
	["East to the {object:32359}: the warrior trainers and {npc:11865} in the {object:32390}, the hunter trainers beside it."] = "向东到 {object:32359}：战士训练师和 {npc:11865} 在 {object:32390} 内，猎人训练师就在旁边。",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "法森在{area:134}西边可俯瞰采掘场的山脊上扎营。与他交谈获得远视。",
	["Feather Charms, from the Frostmane Novices"] = "{item:6753}，来自{npc:946}",
	["Firewood"] = "木柴",
	["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "弗林特菲尔的货物散落在洞穴地面上，{npc:278166}在洞里某处失踪了。\n小心：洞里的雪人彼此站得很近，战斗时很容易一次引来好几只；在洞外用远程攻击一只一只地引出来就能避免。",
	["Flintfire's shipments lie on the cave floor, and {object:460004} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "燧火的货物散落在洞穴地面，{object:460004}则在洞穴某处遗失。\n小心：洞穴里的雪怪站得很近，战斗很容易同时引到好几只；在洞外用远程攻击一只一只引出来就能避免。",
	["Follow the road all the way east to the {area:806} at the {area:38} tunnel."] = "沿路一直向东，到{area:38}隧道处的{area:806}。",
	["Follow the road all the way east to the {area:806} at the {zone:1432} tunnel."] = "沿路一直向东，前往{zone:1432}隧道口的{area:806}。",
	["Follow the road east past the depot to {area:138}."] = "沿道路向东经过补给站到{area:138}。",
	["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "沿道路从{area:131}向东北到{zone:1455}道路下方的钢架补给站。",
	["Follow the road north-east from {area:131} to the depot: the whole east of {area:1} is one sweep from here."] = "从{area:131}沿路向东北前往补给站：{area:1}整个东边都可以从这里一次清完。",
	["Follow the road north-east from {area:131} to the depot: the whole east of {zone:1426} is one sweep from here."] = "从{area:131}沿路向东北前往补给站，从这里开始一轮走完{zone:1426}整个东部。",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}."] = "沿路穿过隧道，向东北前往 {area:131}。先处理室外的事：{npc:1252} 和艾瑞克的营火都在 {area:2102} 前面。",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "沿路走到{zone:1455}，乘坐{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}里，{npc:6179}和{npc:6178}在它的上层：上楼的楼梯就在{npc:5149}东北。乞丐{npc:6175}在城中游荡。他要十块{item:2589}：{area:1}的穴居人和巨魔会掉落，拍卖行也有卖。",
	["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "沿道路上到{zone:1455}，找你的职业训练师学习。{area:2257}从城市东部的{object:171524}出发。乘它前往{zone:1453}。",
	["From the {object:28027} south-west to {object:2098}: {npc:1646}'s compass is in his old house in {zone:1436}, on the way. The flight master and the {object:2096} are south of the square."] = "从 {object:28027} 向西南到 {object:2098}：{npc:1646} 的罗盘在他位于 {zone:1436} 的旧屋里，顺路可取。飞行管理员和 {object:2096} 在广场南侧。",
	["From the {quest:2997} she gives you"] = "从她给你的{quest:2997}获得",
	["From {zone:1436}, walk to {zone:1453}; the tram from {zone:1455} arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "从{zone:1436}步行到{zone:1453}；从{zone:1455}来的地铁到达{object:28027}。{npc:5480}在{object:2100}训练战士；{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为了他的杯子和你打一架。如果{npc:5480}不给{quest:1638}，就直接找{npc:6089}：没有它也会给你{quest:1639}。",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "{npc:706}遍布{npc:786}营地南边和东边的山坡。",
	["Go through the tunnel into {area:38}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "穿过隧道进入{area:38}。刚过隧道，一条用石头标记的小路沿着通往{npc:257808}营地的北路右侧爬上山。",
	["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "穿过隧道进入 {zone:1432}。刚出隧道，路右侧就有一条以石块标记的小径，沿它向北上山，前往 {npc:257808} 的营地。",
	["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}."] = "这位巡山人在{area:136}外扎营；那是{area:131}西南边的雪怪洞穴。",
	["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "离开{zone:1455}，沿路向东前往{area:212}。{npc:6177}死在湖边，对他使用{item:6866}。湖边潜行的黑铁密探携带书信。",
	["Heal and fortify {npc:12427}"] = "治疗{npc:12427}并为其施加耐力",
	["Ice Claw Bear"] = "冰爪熊",
	["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "{item:264356}，来自营地上方山坡上的{npc:706}",
	["If you skipped {quest:314}, grind here to level 11.6 to stay on the route's plan."] = "如果你跳过了{quest:314}，就在这里刷到11.6级，以符合路线规划。",
	["Inn and flight master"] = "旅店与飞行管理员",
	["Inside {area:77}"] = "在{area:77}里面",
	["Instead of walking back up to {area:1537}, go east through the South Gate tunnel into {area:38} and follow the road north to {area:144}. {npc:1681} stands on the east side of town, past the {area:2101}; his errand pays for a flight back to {area:1537}."] = "不必走回{area:1537}，改为向东穿过南门隧道进入{area:38}，沿路向北到{area:144}。{npc:1681}在小镇东侧、{area:2101}再往前；他的差事报酬足够坐飞机回{area:1537}。",
	["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "沿途击杀峭壁野猪：即使尚未接到 {npc:1267} 的任务，也能获得它们掉落的肋排，并用于该任务。回到酿酒厂后，先向 {npc:1699} 学习 {skill:185}，再把肋排交给 {npc:1267}。",
	["Large Crag Boar"] = "大型峭壁野猪",
	["Last: some classes' trainers stand outside"] = "最后处理屋外的职业训练师：部分职业的训练师站在外面",
	["Leave {zone:1453} by the main gate and follow the road south to {area:87}: east Elwynn comes before {zone:1436}."] = "从正门离开 {zone:1453}，沿路向南到 {area:87}：先去艾尔文东部，再前往 {zone:1436}。",
	["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "从正门离开{zone:1453}，向南到{area:87}，再沿道路向东到{area:62}。{npc:881}（9级）站在农舍旁。",
	["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "烈酒村和{area:133}道路周围的{npc:1211}带着齿轮。{npc:1196}、{npc:1127}和{npc:1201}在湖周围的山丘上游荡。",
	["Level 11.6"] = "11.6级",
	["Level 4 spells, before Gozwin's camp"] = "4级法术，在去戈兹温营地之前",
	["Minor Ice Elemental"] = "小型冰元素",
	["North of the post, west of the road: the Stonesplinter troggs and scouts camp in the hills. Both drop the Trogg Stone Teeth."] = "哨站北侧、道路西边：碎石穴居人和碎石怪斥候在山中扎营。两者都会掉落穴居人的石牙。",
	["North of the {object:32372}: {npc:258098}, the shaman trainer, stands at the south end of the {object:32383}, the rogue and warlock trainers and {npc:6120} just north of him."] = "{object:32372} 北侧：萨满训练师 {npc:258098} 在 {object:32383} 南端，潜行者、术士训练师和 {npc:6120} 就在他北边。",
	["North through the hills west of the road to {npc:1343} at the {area:925}. The Tunnel Rat kobolds dig in the hills on the way; Elder Black Bears, Mountain Boars and Forest Lurkers roam the same ground."] = "从道路西侧的山地向北，前往 {area:925} 找 {npc:1343}。沿途山中有坑道鼠狗头人挖掘；老黑熊、山猪和森林潜伏者也在同一区域活动。",
	["North up the road to {area:144}. {npc:1340} walks the road through town, {npc:1963} stands outside the {area:2101}, {npc:1681} on the east side of town; {npc:1572} keeps the gryphons."] = "沿路向北前往 {area:144}。{npc:1340} 在穿过镇子的路上巡逻，{npc:1963} 在 {area:2101} 外，{npc:1681} 在镇子东侧；{npc:1572} 负责狮鹫。",
	["On the road back west to {zone:1455}."] = "沿路向西返回{zone:1455}途中完成。",
	["On the way"] = "顺路",
	["On the {zone:1455} platform of the {area:2257}, {npc:12997} asks for help with the rats: use his {item:17117} on the Deeprun Rats around the platform, hand them in, then take his letter to his brother {npc:13018} at the {zone:1453} end."] = "在 {area:2257} 的 {zone:1455} 站台，{npc:12997} 请你帮忙抓老鼠：对站台周围的矿道老鼠使用他的 {item:17117}，交任务后，再将信带给 {zone:1453} 端的兄弟 {npc:13018}。",
	["Ragged Young Wolves roam the snow just south of {area:77}."] = "蓬毛幼狼在{area:77}南边的雪地里游荡。",
	["Ride the tram to {zone:1453}: {npc:13018} waits on the {zone:1453} platform. {npc:5413} stands in the {object:28027}, just outside the tram."] = "乘地铁前往 {zone:1453}：{npc:13018} 在 {zone:1453} 站台等候。{npc:5413} 在地铁出口外的 {object:28027}。",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "采掘场北边{area:212}旁的{npc:1116}和更东边的{npc:1118}掉落{quest:95214}。黑铁间谍在采掘场东边的湖岸附近潜行；其中一个掉落{item:274268}。",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "{area:212}旁、采石场以北的石颚伏击者，以及更东边的石颚碎背者掉落{quest:95214}。石颚碎骨者在采石场和湖边徘徊；黑铁间谍在湖岸潜行。其中一个间谍掉落{item:274268}。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "{npc:1115}遍布采掘场；{area:212}旁的{npc:1116}掉落{item:268548}。",
	["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "{npc:1115}、石腭碎骨者和石腭伏击者分布在采掘场及其北边的山坡上；伏击者掉落{item:268548}。",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "{npc:707}和{npc:724}在{area:77}南边的谷底到处挖掘。",
	["Sit by Eric's campfire (type /sit) and wait for the buff."] = "坐在艾瑞克的营火旁（输入 /sit），等待获得增益效果。",
	["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "坐在艾瑞克的营火旁（输入 /sit），等待获得增益效果。学会专业技能后，艾瑞克还会提供该专业的“露营 101”任务，交给对应的训练师：锻造交给{npc:1241}，{skill:129}交给{area:131}的{npc:2326}，采矿和工程学则在{area:189}交付。",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "{npc:708}在{npc:714}的营地周围和山谷西侧吃草。",
	["Snow Leopard"] = "雪豹",
	["Snow Leopard Prowler"] = "雪豹潜行者",
	["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "{npc:1201}和野猪在农场与采掘场之间的雪地里游荡。铁匠：{item:2840}可以通过熔炼{item:2770}获得，或从商人处购买。",
	["South down the road to {area:144}, finishing the ears, meat and ichor on the way."] = "沿路向南到{area:144}，顺路把耳朵、肉和脓液收齐。",
	["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "沿路向南前往 {area:144}，途中收齐耳朵、肉和毒液。{npc:1340} 在穿过镇子的路上巡逻。",
	["South through the Commons: {npc:1274} stands in the {object:171709} with King Magni."] = "向南穿过平民区：{npc:1274} 在 {object:171709}，与麦格尼国王在一起。",
	["Stonesplinter Scout"] = "碎石侦察兵",
	["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "{npc:1166}（13级）站在{npc:257808}南边、{area:923}南部的穴居人之间；{npc:1174}（12级）在湖北端的{area:149}工作。穴居人成群出现，有些会远程投掷：一次拉一个。",
	["Stonesplinter Trogg"] = "碎石穴居人",
	["Stonesplinter troggs"] = "碎石穴居人",
	["Subdue the voidwalker"] = "制服虚空行者",
	["The Fire Spirit Stone"] = "火之灵魂石",
	["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "德南的热酒只持续五分钟：直接向北到{area:77}里面找{npc:836}。",
	["The boars"] = "野猪",
	["The firewood lies in the snow around the frozen lake by the refuge."] = "木柴散落在避难所旁结冰湖泊周围的雪地里。",
	["The gryphons land in the {object:32372}: {npc:4256} works at its north end, and {npc:1573} keeps the gryphons where you landed."] = "狮鹫降落在 {object:32372}：{npc:4256} 在其北端工作，{npc:1573} 就在你降落处负责狮鹫。",
	["The paladin, priest and mage trainers are in the {object:32386}, in the {object:32362}."] = "圣骑士、牧师和法师训练师都在 {object:32362} 的 {object:32386} 内。",
	["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "飞行员们在补给站；{npc:1269}在往西回去的路上，位于{area:131}北边。",
	["The quarry lies just east of Farsen's ridge."] = "采石场就在法森所在山脊的东侧。",
	["The quarry troggs"] = "采掘场的穴居人",
	["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "三支步枪散落于避难所旁冰湖周围的雪地。小型冰元素在湖边和沿途活动，顺路击杀，完成{quest:99160}。\n如果数量仍不足，在避难所西侧小湖周围补足小型冰元素。",
	["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "地铁到达{object:28027}。{npc:5480}在{object:2100}训练战士；{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为了他的杯子和你打一架。",
	["The troggs"] = "穴居人",
	["The troll cave"] = "巨魔洞穴",
	["The tunnel"] = "隧道",
	["The tunnel post"] = "隧道哨站",
	["The west hills and the {area:925}"] = "西侧山地与 {area:925}",
	["The {area:2257}"] = "{area:2257}",
	["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "{item:2676}生长在{area:802}高处的篮子里，即{area:131}与烈酒村之间道路以北的雪坡。从{area:131}以西的道路向上攀爬，山脊上的霜鬃先知也会掉落。",
	["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "{object:176785}位于{area:136}南侧的{npc:271546}旁。",
	["The {object:269} in the basement"] = "地下室里的{object:269}",
	["The {object:270} in the distillery; below ground"] = "酒厂地下室的{object:270}",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英敌人，建议寻找其他玩家组队完成。{npc:1388}是 12 级精英，多数职业到 14 级可以尝试单独击败，但可能仍需帮助。独自一人时可跳过，路线会安排刷怪补回经验。",
	["Tram to {zone:1453}"] = "乘地铁前往{zone:1453}",
	["Upstairs"] = "在楼上",
	["Use the {item:6866} on {npc:6177}"] = "对{npc:6177}使用{item:6866}",
	["West from the {object:32383} into the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "从{object:32383}向西进入{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}里，{npc:6179}和{npc:6178}在它的上层：上楼的楼梯就在{npc:5149}东北。乞丐{npc:6175}在城中游荡。他要十块{item:2589}：{area:1}的穴居人和巨魔会掉落，拍卖行也有卖。",
	["West from the {object:32383} into the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "从 {object:32383} 向西进入 {object:32362}：{npc:5149}、{npc:6179} 和 {npc:6178} 都在 {object:32386} 内，其中 {npc:6179} 和 {npc:6178} 在楼上；上楼的楼梯入口就在 {npc:5149} 东北侧。乞丐 {npc:6175} 在城里游荡。他需要十块 {item:2589}：{zone:1426} 的穴居人和巨魔会掉落，也可从拍卖行购买。",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；猎人的近战武器主要看属性，而双手武器属性最多。",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "顺便：在{npc:11867}处学习法杖（{object:2096}，10银币）；升级期间，法杖的法术属性比单手武器更多。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "顺便：在{npc:11867}处学习剑（{object:2096}，10银币）；主手持剑能让潜行者稳定升级。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "顺路提示：向{npc:11865}学习{spell:197}（{object:32359}，10 银）；圣骑士使用双手武器升级最快。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "顺路提示：向{npc:11865}学习{spell:197}（{object:32359}，10 银）；战士使用双手武器升级最快。",
	["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "顺路提示：向{npc:11865}学习{spell:199}（{object:32359}，10 银）；战士使用双手武器升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "顺便：在{npc:11867}处学习{spell:202}（{object:2096}，10银币）；圣骑士用双手武器升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "顺便：找{npc:11867}学习{spell:202}（{object:2096}，10银币）；双手武器能让战士升级最快。",
	["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "你从{area:77}前方出发，那是山谷北端的石厅。{npc:658}在门外等候。",
