	["Windsong Crawler"] = "风歌爬行者",
	["With a profession learned, {npc:263664} also offers its Camping 101, which its trainer in {area:16624} takes on the village round."] = "学会一项专业技能后，{npc:263664}还会提供对应的露营 101，在{area:16624}巡村时交给该专业的训练师。",
	["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "你在{area:16622}醒来。{npc:251362}站在你身旁；{npc:251361}在西边几步远，{npc:251368}在林地南缘。",
