	["{npc:263664}: for {npc:257024}"] = "{npc:263664}：交给{npc:257024}",
	["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "{npc:270459}，在{npc:259084}身旁：前往{zone:1453}找{npc:5504}",
	["{npc:5141} in {zone:1455}; {area:16638} has no priest trainer"] = "前往{zone:1455}找{npc:5141}；{area:16638}没有牧师训练师",
	["{npc:5148} in {zone:1455}; {area:16624} has no paladin trainer"] = "前往{zone:1455}找{npc:5148}；{area:16624}没有圣骑士训练师",
	["{npc:5148} in {zone:1455}; {area:16638} has no paladin trainer"] = "前往{zone:1455}找{npc:5148}；{area:16638}没有圣骑士训练师",
	["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497}站在{object:2101}的塔楼巫师圣殿里；她会给你一个瓶子，用于{quest:1861}的瀑布。",
	["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{zone:1453}的德鲁伊训练师{npc:5504}会教你{spell:18960}。{npc:11802}的问候要等到{zone:1439}结尾的{spell:499}之旅时再去。",
	["{object:631299}, inside"] = "{object:631299}：在屋内",
	["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159}住在{npc:257944} 埃莱盖尔·刺爪西边。泽风之种球果散落在他的小屋和{npc:257944} 埃莱盖尔·刺爪之间的树林里。",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
}

G["forever/class/hunter/taming-the-beast-alliance"] = {
	["At 10 go to {npc:1231}, the hunter trainer at the smithy in {area:131}. The Hunter's Path from {npc:5116} in {zone:1455}, {npc:11807} north-west of {area:131} or {npc:5515} in {zone:1453} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "10级时，去找{area:131}铁匠铺里的猎人训练师{npc:1231}。{zone:1455}的{npc:5116}、{area:131}西北面的{npc:11807}或{zone:1453}的{npc:5515}给予的“猎人之道”也会指引你来这里，能额外获得少量经验；它只是引导任务。10级时人在艾尔文森林？{area:87}的{npc:251507}提供的任务链也教相同的技能。",
	["At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same."] = "10级时去找 {npc:251507}，她是猎人训练师，与其他训练师一起站在 {area:87} 的狮王之傲旅店旁；宠物训练师 {npc:258930} 在她身边。天裔角色：这是为离开 {zone:2521} 时尚未学会驯服宠物的角色准备的，教授的内容相同。",
	["At 10 go to {npc:3601}, the hunter trainer in {area:186}. The Hunter's Path from {npc:3596} at {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} or {npc:1231} in {area:131} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "10级时，去找{area:186}的猎人训练师{npc:3601}。{area:256}的{npc:3596}、{zone:1457}的{npc:4146}、{zone:1453}的{npc:5515}、{zone:1455}的{npc:5116}或{area:131}的{npc:1231}给予的“猎人之道”也会指引你来这里，能额外获得少量经验；它只是引导任务。10级时人在艾尔文森林？{area:87}的{npc:251507}提供的任务链也教相同的技能。",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "10 级时，{zone:2521} 上的猎人训练师 {npc:254084} 可能会给你 {quest:94007}，让你前往 {area:16638}。这只是引导任务：如果已经在 {area:16638}，可以跳过。",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}."] = "先解散野猪（右键点击宠物头像，选择{spell:2641}）：放出的练习宠物可能会攻击你。森林灰狼（7-8级）在{area:87}东侧、{area:18}东侧的树林中活动。",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of {area:131}, more north-west and west of it; the smaller Juvenile Snow Leopards do not count."] = "先解散野猪（右键点击宠物头像，选择{spell:2641}）：放出的练习宠物可能会攻击你。雪豹（7-8级）在{area:131}东南方的山坡上游荡，西北方和西侧也有；体型较小的雪豹幼崽不算数。",
	["Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of {area:186}."] = "解散猫科宠物。巨翼恶枭（7—8级）是猫头鹰，栖息在 {area:186} 南面、西南面和西面的树林里。",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "先解散爬行者（右键点击宠物头像，选择{spell:2641}）。暴躁的疾风陆行鸟在{area:16626}觅食，那片田野位于{area:16638}以西及西南不远处。",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "解散疾风陆行鸟。瓦尔德伦头狼也在{area:16626}猎食，位置稍靠南。",
	["Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around {area:131}, many south-east of it and more north-west toward {area:77}; their {spell:3130} hits hard, so start at full health."] = "解散豹子。冰爪熊（7-8级）在{area:131}周围的山丘游荡，东南面很多，西北往{area:77}方向也有；它们的{spell:3130}伤害很高，满血再开始。",
	["Dismiss the spider first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of {area:259}, south of {area:186}; the plain Nightsabers by the village do not count."] = "先解散蜘蛛（右键点击宠物头像，选择{spell:2641}）：放出的练习宠物可能会攻击你。夜刃捕食者（7-8级）栖息在{area:259}南方、{area:186}南方的山坡上；村庄旁的普通夜刃豹不算数。",
	["Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town."] = "解散狼。森林熊幼崽（8-9 级）在 {area:87} 正南的树林里游荡，镇子西南和东南还有更多。",
	["Gray Forest Wolf"] = "灰森林狼",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "快乐度：看宠物头像框上的表情。宠物不高兴时只造成正常伤害的四分之三，高兴时则额外造成四分之一伤害。快乐度会缓慢降低，宠物死亡后降得更快；宠物长期不高兴可能会逃跑。",
	["Hunter"] = "猎人",
	["Ice Claw Bear"] = "冰爪熊",
	["Large Crag Boar"] = "大型峭壁野猪",
	["Large Crag Boars (level 6-7) root around the fields west, south and north-west of {area:131} and respawn every 3 minutes. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, being out of range or anyone else's help breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:1231}. The boars use {spell:6268} from 25 yards, so start with the rod, not {spell:75}. Keep each rod: it goes back to {npc:1231}."] = "大峭壁野猪（6-7级）在{area:131}以西、以南及西北面的田野里拱土，每3分钟刷新。驯兽棒的用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动，任它攻击。移动、还手、超出距离或他人帮忙都会打断引导，并消耗本就不多的一次充能；若充能耗尽，销毁驯兽棒，放弃任务，再向{npc:1231}重新接受。野猪会从25码外使用{spell:6268}，所以要直接使用驯兽棒，不要先用{spell:75}。每根驯兽棒都要保留：需要交回{npc:1231}。",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "忠诚度会随相处时间和击杀增长。每提升一级忠诚等级，都能增加可用于{spell:5149}的训练点数（宠物等级乘以“忠诚等级减一”）。",
	["Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}."] = "{area:131}附近：雪豹（猫科，7-8级）遍布{zone:1426}；有伤疤的峭壁野猪（9-10级）在东部、靠近{zone:1432}的方向；山猪为10-11级，在{zone:1432}西部活动。",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "{area:16638} 附近：瓦尔德伦头狼（10级）在 {area:16626} 觅食，它们就是你最后一次练习驯服的野兽；尖啸幼兽主母（迅猛龙，9级）在 {area:16638} 西侧筑巢；影风乌萨拉（熊，10—11级）在 {zone:2521} 北部游荡。",
	["Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}."] = "{area:186} 附近：老夜刃豹（猫科，8—9级）和野生夜刃豹（猫科，10—11级）在 {zone:1438} 西北部的林中游荡。",
	["Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}."] = "{area:87} 附近没有猫科野兽：森林狼（狼，9-10 级）在艾尔文森林东部游荡，长鼻野猪（野猪，10-11 级）位于其西南尽头、靠近 {zone:1436} 边界的地方；12-13 级的幼年血牙野猪则在 {zone:1436} 北部的田野觅食。",
	["Nightsaber Stalker"] = "夜刃豹潜行者",
	["Ornery Galestrider"] = "暴躁风行者",
	["Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}."] = "宠物训练师出售各等级的{spell:1853}及抗性技能。联盟：{area:87}的{npc:258930}、{zone:1453}的{object:28027}中猎人训练师旁的{npc:2879}、{area:131}的{npc:2878}、{zone:1455}的{object:32390}中的{npc:10090}、{area:186}的凯尔达斯、{zone:1457}塞纳里奥区的西尔瓦莉雅，以及{area:16638}的{npc:254411}。",
	["Rockhide Boar"] = "石皮野猪",
	["Rockhide Boars (level 7-8) graze in three herds south and south-east of {area:87}, toward the {area:64}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use {spell:6268}, so start with the rod, not {spell:75}. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through {area:87} from here."] = "石皮野猪（7-8 级）分成三群，在 {area:87} 南侧和东南侧、靠近 {area:64} 的方向觅食。驯兽棒的用法：选中一只活着的野兽，使用 {item:15908}，在整个引导期间站着不动，任由它攻击你。移动、还击、接受他人治疗，或其他人攻击这只野兽，都会打断引导，并消耗驯兽棒为数不多的使用次数；次数耗尽后，摧毁驯兽棒、放弃任务，再重新接受。野猪会使用 {spell:6268}，因此先使用驯兽棒，不要先用 {spell:75}。击杀野猪不计入任务。每根驯兽棒都要留着，之后要交还给约瑟芬·卡森。若矮人或暗夜精灵领取的是约瑟芬·卡森的驯兽棒，而非本族训练师的，从这里起路线会引导其经过 {area:87}。",
	["Snow Leopard"] = "雪豹",
	["Strigid Screecher"] = "夜枭尖啸者",
	["Take the road west from {area:186} to {zone:1457}. {npc:4146} stands inside the {area:1658} with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her."] = "沿道路从 {area:186} 向西前往 {zone:1457}。{npc:4146} 在 {area:1658} 内与猎人训练师站在一起；宠物训练师西尔瓦莉雅在她旁边的坡道上方。",
	["Tame a beast of your level to keep"] = "驯服一只与你同级的野兽，作为长期宠物。",
	["Tame {npc:1922}"] = "驯服{npc:1922}",
	["Tame {npc:250874}"] = "驯服{npc:250874}",
	["Tame {npc:251707}"] = "驯服{npc:251707}",
	["Tame {npc:254588}"] = "驯服{npc:254588}",
	["Tame {npc:524}"] = "驯服{npc:524}",
	["Tame {npc:822}"] = "驯服{npc:822}",
	["Use the {item:15908} on a living alpha"] = "对一只活着的头狼使用{item:15908}",
	["Use the {item:15908} on a living bear"] = "对一只活熊使用 {item:15908}",
	["Use the {item:15908} on a living boar"] = "对一头活着的野猪使用{item:15908}",
	["Use the {item:15908} on a living crawler"] = "对一只活着的爬行者使用{item:15908}",
	["Use the {item:15908} on a living galestrider"] = "对一只活着的风行者使用 {item:15908}。",
	["Use the {item:15908} on a living leopard"] = "对活着的豹子使用 {item:15908}",
	["Use the {item:15908} on a living owl"] = "对一只活着的猫头鹰使用{item:15908}",
	["Use the {item:15908} on a living spider"] = "对一只活蜘蛛使用 {item:15908}",
	["Use the {item:15908} on a living stalker"] = "对一只活着的捕食者使用{item:15908}",
	["Use the {item:15908} on a living wolf"] = "对一只活着的狼使用 {item:15908}。",
	["Vuldren Alpha"] = "鹫龙首领",
	["Webwood Lurker"] = "蛛网潜伏者",
	["Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of {area:186}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their {spell:1265843} roots you but does not break the channel if you keep still. Keep each rod: it goes back to {npc:3601}."] = "树林潜伏者（5—6级）在 {area:186} 东北、西南和东侧不远处的树林中出没。驯兽棒的用法：选中活着的野兽，使用 {item:15908}，在整个引导过程中站着不动，任它攻击你；移动、攻击它或其他人的协助都会打断引导，并消耗驯兽棒为数不多的使用次数（次数耗尽后：销毁驯兽棒，放弃任务再重新接受）。它们的 {spell:1265843} 会将你定身，但只要保持不动就不会打断引导。保留每根驯兽棒：需要交回给 {npc:3601}。",
	["Windsong Crawler"] = "鸣风爬行者",
	["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to {npc:252389}."] = "风歌爬行者只生活在水边：最近的一群在{area:16638}西南方的岸边，与螃蟹混杂在一起。驯服棒用法：选中一只活着的爬行者，使用{item:15908}，在整个引导期间站着不动，任由它攻击你；移动、还击或其他人帮忙都会打断引导，并消耗驯服棒本就不多的使用次数。击杀不算数。保留每根驯服棒：要交还给{npc:252389}。",
	["Young Forest Bear"] = "幼森林熊",
	["Your first pet"] = "你的第一只宠物",
	["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "10级获得自己的宠物：用{item:15908}完成三次驯服练习，学会{spell:1515}，然后学会{spell:5149}。",
	["{npc:10090} in {zone:1455}"] = "{zone:1455}的{npc:10090}",
	["{npc:10090}, the pet trainer, stands in the {object:32390} in {zone:1455}'s {object:32359}, by the hunter trainers."] = "宠物训练师{npc:10090}站在{zone:1455}的{object:32359}内，位于{object:32390}，就在猎人训练师旁。",
	["{npc:1231} in {area:131}"] = "{area:131}的{npc:1231}",
	["{npc:1231}: the first {item:15908}"] = "{npc:1231}：第一份{item:15908}",
	["{npc:251507} in {area:87}"] = "{area:87}的{npc:251507}",
	["{npc:251507}: the first {item:15908}"] = "{npc:251507}：第一份{item:15908}",
	["{npc:252389} in {area:16638}"] = "{area:16638}的{npc:252389}",
	["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389} 与训练师们一起站在 {area:16638} 西门旁，{npc:254411} 就在她身边。",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}：第一份{item:15908}",
	["{npc:254411}, beside her: {spell:5149}"] = "{npc:254411}，在她旁边：{spell:5149}",
	["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}，在她旁边：{spell:5149}",
	["{npc:3601} in {area:186}"] = "{area:186}的{npc:3601}",
	["{npc:3601}: the first {item:15908}"] = "{npc:3601}：第一份{item:15908}",
	["{npc:4146} in {zone:1457}"] = "{zone:1457}的{npc:4146}",
	["{quest:6063} (Alliance)"] = "{quest:6063}（联盟）",
	["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515} 的用法与驯兽棒相同：目标必须是等级不高于你的野兽，引导期间不能移动，而野兽会一直攻击你。宠物在驯服后保留原有等级，并随你一起升级；它的等级永远不能超过你，因此尽量驯服等级接近自己的野兽。在无限服，每个宠物家族都有专属技能（例如野猪的冲锋）。练级时，猫科伤害最高（爪击和 {spell:17253}），野猪则更耐打。",
	["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in {area:87}, Jaeana in {zone:1457} and the innkeepers on {zone:2521} sell meat; the innkeepers of {area:131} and {area:186} sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584}：打开法术书，施放{spell:1584}，再点击一种你的宠物所属家族能吃的食物（宠物的鼠标提示会列出食谱：猫科吃肉和鱼，野猪几乎什么都吃）。从野兽身上拾取的生肉也可以。购买地点：{area:87}的屠夫托德瑞克、{zone:1457}的加伊娜以及{zone:2521}的旅店老板出售肉类；{area:131}和{area:186}的旅店老板出售面包。等级接近宠物的食物提供的快乐值最多；等级低很多的食物大约只有一半效果。战斗中无法喂食。",
	["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} on {zone:2521}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149}（法术书的综合页）可将你已掌握的技能教给当前宠物。学习新的技能或等级时：先将宠物存放在兽栏管理员处（{area:87}的旅店老板艾玛、{area:131}的{npc:9980}、{area:186}的瑟里亚迪、{zone:2521}的{npc:265756}），再驯服一只拥有该技能的野兽（其宠物法术书页会显示已掌握的技能），在战斗中使用该技能，直到游戏提示你已经学会，然后领回自己的宠物，用{spell:5149}教给它。一只宠物最多拥有四个主动技能。",
	["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "现在你的法术书中已有 {spell:883}、{spell:2641} 和 {spell:982}；到12级时，可以找训练师学习 {spell:136}。宠物死亡后需要用 {spell:982}；离你超过约100码时，宠物会被解散，可用 {spell:883} 再次召回。",
}

G["forever/class/mage/astral-knot-garment"] = {
	["A robe or a blouse for Alliance mages in their late 20s."] = "为二十多级的联盟法师准备的长袍或短衫。",
	["Back to Andromath"] = "回到高阶巫师安多玛斯那里",
	["Carrion Recluses"] = "{npc:949}",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. The {area:96} stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' {spell:2691} interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it."] = "向东穿过{zone:1429}进入赤脊山，或直接飞往{area:69}。{area:96}独立矗立在地区东侧。爬到最顶层，不要停在下一层；论文就是楼梯出口旁书架上突出的书。两只豺狼人猎犬和一名施法者守着书架，猎犬的{spell:2691}会打断拾取，应在楼梯上、避开它们视线的位置战斗。26 级精英莫甘斯在顶层另一侧，无需击杀；沿坡道左缘走，避免引到他。书被拾取两秒后就会重新出现。若死亡，可用灵魂跑上楼，在书旁复活。",
	["Mage"] = "法师",
	["The {area:96}"] = "{area:96}",
	["You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:5694} waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. ({npc:5497} may also offer you {npc:5694}, the pointer quest; it is only a pointer and you can skip it.)"] = "无需介绍信。26 级时前往{zone:1453}的{object:2101}，登上紫色高塔巫师圣殿。{npc:5694}在接近顶部的螺旋走道、刚经过传送门房间门口的位置，会直接提供任务。{npc:5497}也可能提供指向{npc:5694}的介绍任务，它只用于引路，可跳过。",
	["{area:492} in western {zone:1431}: the six Carrion Recluses (level 25-26, green, {spell:3609}) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. {npc:522}, a level 35 elite skeleton, walks the cemetery: watch for him."] = "前往{zone:1431}西部的{area:492}。六只 25–26 级、绿色且会施放{spell:3609}的食腐独行蛛分布在墓地、中央雕像及河岸，每只必掉一份丝，五分钟刷新。墓地东侧坡地的 24–25 级小型黑寡妇蜘蛛约六分之一几率掉落，等待刷新时可顺便击杀。35 级精英骷髅{npc:522}会在墓地巡逻，注意避开。",
	["{npc:1309} works at {object:23296} in the {object:2101}. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit."] = "{npc:1309}在{object:2101}的{object:23296}工作。长袍提供智力、耐力和精神；短衫提供更多智力和耐力，但没有精神。",
	["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144}在{zone:1455}的{object:32362}教导法师。之后从{object:171524}乘{area:2257}前往{zone:1453}。",
	["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}; the portal near the top of the spiral ramp takes you to her."] = "{npc:5497}位于{object:2101}紫色高塔、巫师圣殿的顶部。沿螺旋坡道上行，通过接近顶部的传送门即可到她身旁。",
	["{npc:5694} (Skyborne)"] = "{npc:5694}（天裔）",
	["{quest:1939} waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers."] = "{quest:1939}位于巫师圣殿的螺旋走道，从训练师处向下走，刚经过传送门房间门口即可找到。",
}

G["forever/class/mage/manaweave-robe"] = {
	["A robe at 15 for Alliance mages, from {zone:1453} and {zone:1432}."] = "联盟法师15级时的长袍，来自{zone:1453}和{zone:1432}。",
	["Any humanoid drops {item:2589}, and the Tunnel Rats in the {area:149} drop it while you gather the gems; the Auction House in the {object:2096} sells it. You hand in ten."] = "所有人形生物均有几率掉落{item:2589}，收集宝石时，{area:149}的坑道鼠也会掉落；{object:2096}的拍卖行可以买到。需要交付十个。",
	["Back to {npc:5497}"] = "回到{npc:5497}那里",
	["Back to {zone:1453} by the tram. {npc:1309} works at {object:23296} in the {object:2101}."] = "乘地铁回到{zone:1453}。{npc:1309}在{object:2101}的{object:23296}工作。",
	["Mage"] = "法师",
	["Rift Spawn"] = "裂隙生物",
	["Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The {area:149} is at the north end of the loch, north of {area:144}; Tunnel Rat kobolds hold it. The gems come only from the tall stacked {object:271} (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest."] = "乘{area:2257}前往{zone:1455}，再沿路向东穿过南门隧道进入{zone:1432}。{area:149}在{area:144}以北、洛克湖北端，由坑道鼠狗头人占据。宝石只来自高高叠起的{object:271}，鼠标指向时显示齿轮；单独的小箱子没有。每个箱子给一颗，总共有十四个，三到五分钟刷新。要拿六颗，可能需要深入最里面的房间。这些箱子也用于矮人的“肮脏的爪子”任务。",
	["The {area:149}"] = "{area:149}",
	["{item:7247}, on the stunned {npc:6492}"] = "对昏迷的{npc:6492}使用{item:7247}",
	["{npc:328} is the {area:87} mage trainer, upstairs in the Lion's Pride Inn."] = "{npc:328}是{area:87}的法师训练师，位于狮王之傲旅店楼上。",
	["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}: climb the spiral ramp and take the portal near the top. The {item:7247} and the {item:7308} lie on the table behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:5497}位于{object:2101}紫色高塔巫师圣殿顶部，沿螺旋坡道上行，通过接近顶部的传送门即可。她身后的桌子上有{item:7247}和{item:7308}，被拿走后均五分钟刷新。最后交任务时需要两件物品，请保留。",
	["{npc:6492}, down to the stun"] = "{npc:6492}：攻击至其昏迷",
	["{npc:7312} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:7312}在{zone:1455}的{object:32362}教导法师。之后从{object:171524}乘{area:2257}前往{zone:1453}。",
	["{object:2169} is the tavern in the {object:2101}. Read the {item:7308} inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of {spell:122} fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the {item:7247} on it while it is stunned, then click the {item:7292} it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds."] = "{object:2169}是{object:2101}的旅店。在里面阅读{item:7308}，可显现隐形的 16–17 级裂隙怒灵：地下室出现一只，阳台或厨房两只，大厅或门边三只，因此应在地下室阅读。它们伤害很高，很快挣脱{spell:122}。将一只打到低血量，它不会死亡，而会停止战斗，头顶转圈并昏迷；此时对它使用{item:7247}，再点击地面上出现的{item:7292}。未出现就点击会浪费一次使用次数。共需三个，而咒文每五分钟才能用一次，退出登录也不重置，因此要做三轮。",
}

G["forever/class/mage/staff-or-orb-alliance"] = {
	["A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand."] = "10级时在主城的法师训练师处获得一根法杖或一个副手宝珠；天行者额外获得一根魔杖。",
	["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {npc:5497}'s {quest:1861}; you get one staff-or-orb quest. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "10级时，{area:2102}中{area:131}的法师训练师{npc:1228}派你去找{zone:1455}的{npc:5144}。接受了它，{npc:5497}的{quest:1861}就不会出现；你只能做一条法杖或宝珠任务。（若侏儒在{area:87}接了{npc:328}的任务，则改走{quest:1861}的步骤；若人类接了这条，则走基兹莫尼特的步骤。）",
	["At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town."] = "10 级时，{area:16638}的法师训练师{npc:252373}会让你去找同镇几步外的法杖商人{npc:256507}。",
	["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {npc:5144}'s quest in {zone:1455}; you get one staff-or-orb quest."] = "10级时，狮王之傲旅店楼上的{area:87}法师训练师{npc:328}会让你去找{zone:1453}的{npc:5497}。接受了它，{zone:1455}的{npc:5144}的任务就不会出现；你只能做一条法杖或宝珠任务。",
	["Back to {npc:256507}"] = "返回{npc:256507}处",
	["Back to {npc:5144}"] = "返回{npc:5144}",
	["Back to {npc:5497}"] = "回到{npc:5497}那里",
	["Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "再次登上巫师圣殿，通过传送门。宝珠是与单手武器搭配的副手物品，法杖则是双手武器。",
	["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "沿道路向北进入 {zone:1453}，再向西前往 {object:2101}。{npc:5497} 站在巫师圣殿的顶端，那是一座紫色高塔：沿螺旋坡道向上，走进接近塔顶处的传送门，就会来到她身边。她会给你 {item:7207}。天裔法师首次到达 {zone:1453} 时，大约15级，可向她接受 {quest:1861}。",
	["Head west along the road to {area:133}. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone."] = "沿路向西前往{area:133}。入口北侧有两间小屋，工具箱在东侧较高、带升降梯的那间内，是底层桌子旁、半藏在桌下的小灰箱。8 级麻疯侏儒守卫小屋，逐个拉怪。工具箱只有一个，被打开后十五分钟刷新；如果没有，就在附近等候。",
	["Leave {zone:1453} by the main gate and head south-west to the waterfall that feeds {quest:1861}. Wade in under the falling water to the rock behind it and use {item:7207} there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water."] = "从正门离开{zone:1453}，向西南前往流入{quest:1861}的瀑布。涉水进入瀑布下方，贴到后方岩石，再使用{item:7207}，施法五秒；其他位置无效。瀑布两侧岩石上有 10 级迪菲亚施法者，会远程攻击，可逐个拉出，或从水中装满药瓶。",
	["Ley or {item:9514} or Orb (Alliance)"] = "魔网、{item:9514}或宝珠（联盟）",
	["Mage"] = "法师",
	["The Windstone Formations"] = "风石阵",
	["The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of {area:16636}. It does not sparkle, so look at the ground by the stones; there are two spots for it."] = "树枝落在风石阵之间的地面上，即菲里昂·炎风营地西侧高地、{area:16636}以南的风之神殿。它不会闪光，要仔细查看石块旁地面，共有两个刷新位置。",
	["The {quest:1861} waterfall"] = "{quest:1861}瀑布",
	["{item:7207}, under the falls"] = "在瀑布下使用{item:7207}",
	["{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb."] = "人类和侏儒法师也能接受 {npc:256507} 的任务。如果你前往天裔的家园 {zone:2521} 上的 {area:16638}，镇上的法师训练师 {npc:252373} 会让你去找隔壁的 {npc:256507}。后者要你从 {area:16636} 南侧的风石阵附近地面拾取一个 {item:262668}，以换取 {item:263430}。这个任务不影响你获取法杖或宝珠。",
	["{npc:256507}'s wand (optional)"] = "{npc:256507} 的魔杖（可选）",
	["{npc:5144} teaches mages in the {object:32362}, at the back of {zone:1455} past the {object:32386}."] = "{npc:5144}在{zone:1455}深处、经过{object:32386}后的{object:32362}教导法师。",
	["{npc:5144}: {item:7507} or {item:9514}"] = "{npc:5144}：{item:7507}或{item:9514}",
	["{npc:5497}: {item:7508} or {item:9513}"] = "{npc:5497}：{item:7508}或{item:9513}",
	["{quest:1861} (the next steps) waits for you with {npc:5497} in {zone:1453}, at about 15."] = "约 15 级时，可在{zone:1453}向{npc:5497}接取{quest:1861}，接着按后续步骤完成。",
}

G["forever/class/mage/teleports-alliance"] = {
	["At 20 go to the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:2485}, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches {spell:3561} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor; {npc:1308} sells them at the foot of the tower), so carry a few."] = "20 级时前往{zone:1453}的{object:2101}紫色高塔巫师圣殿。传送门训练师{npc:2485}位于最顶层，沿螺旋坡道上行，通过接近顶部的传送门即可。花费 20 银学习{spell:3561}。每次传送消耗一个{item:17031}，任意施法材料商人以 10 银出售，塔底的{npc:1308}也卖，记得随身备几个。",
	["At 30. Take the boat from {area:17203} to {area:442} in {zone:1439}, then the boat to {area:702} and the pink portal up into {zone:1457}. {npc:4165}, the portal trainer, teaches {spell:3565} for 80 silver."] = "30 级时，从{area:17203}乘船前往{zone:1439}的{area:442}，再乘船去{area:702}，通过粉色传送门到达上方的{zone:1457}。向传送门训练师{npc:4165}花费 80 银学习{spell:3565}。",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:2485} has {spell:10059} at the top of the Wizard's Sanctum; then the tram to {npc:2489} in {zone:1455}'s {object:32362} for {spell:11416}."] = "40 级时，可向训练师学习供全队穿过的传送门，每项技能 1 金 50 银。每次施放消耗一个{item:17032}，任意施法材料商人以 20 银出售。先到巫师圣殿顶部找{npc:2485}学习{spell:10059}，再乘地铁到{zone:1455}的{object:32362}，向{npc:2489}学习{spell:11416}。",
	["At 50 {npc:4165} in {zone:1457} teaches the last one, {spell:11419}, for 3 gold 20 silver. Use your {spell:3565} to get there."] = "50 级时，{zone:1457}的{npc:4165}教授最后一项{spell:11419}，费用 3 金 20 银。使用{spell:3565}即可前往。",
	["Mage"] = "法师",
	["Portals to {zone:1453} and {zone:1455}"] = "前往{zone:1453}和{zone:1455}的传送门",
	["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}. {npc:2489}, the portal trainer, stands with the mage trainers in the {object:32362} at the back of the city: {spell:3562}, 20 silver."] = "从{zone:1453}的{object:28027}乘{area:2257}前往{zone:1455}。传送门训练师{npc:2489}与法师训练师一同站在城内深处的{object:32362}，花费 20 银学习{spell:3562}。",
	["Teleports and Portals (Alliance)"] = "传送术与传送门（联盟）",
	["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "20级和30级学习主城传送术，40级和50级学习小队传送门，均可在各主城的传送门训练师处学习。",
	["{item:17031}, 10s each"] = "{item:17031}，每个 10 银",
	["{item:17032}, 20s each"] = "{item:17032}，每个 20 银",
}

G["forever/class/paladin/cloak-of-the-divine-storm"] = {
	["A rare cloak at 30 from the old {spell:407778} story; for now only Alliance paladins can finish it."] = "30级可获得的一件稀有披风，出自旧的{spell:407778}任务线；目前只有联盟圣骑士能完成它。",
	["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "横穿整个地区，返回 {zone:1440} 西部 {area:413} 的 {npc:3663} 处。",
	["Back to {npc:5495}"] = "回到{npc:5495}处",
	["Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the Strange Orb at the top: it gives you the Althalaxx Orb; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it."] = "爬到 {zone:1439} 北部 {area:444} 的塔顶。周围的暗滩狂热者比较容易对付（16-17 级），但通往宝珠的塔内有四名暗滩唤魔师（28-29 级）：每名都会召唤虚空行者，并在远处施放 {spell:686}。22-25 级时，带一两位朋友来，每次只引一名，然后躲到墙后迫使对方靠近。拾取顶层的 Strange Orb，获得 奥萨拉克斯宝珠；右键点击它开始任务。在到达 {object:409311} 之前一直把宝珠放在背包里：后面有三个任务要用到它。",
	["Motes of Mannoroth"] = "玛诺洛斯微粒",
	["Paladin"] = "圣骑士",
	["Strange Orb atop the {area:444}: right-click the Althalaxx Orb it gives"] = "{area:444}顶端的Strange Orb：右键点击它给的奥萨拉克斯宝珠",
	["The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the {item:209778}; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of {area:69} drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is {npc:334} (26): stay in the north-west."] = "黑石召唤师、黑石勇士和黑石追踪者（22-25 级，非精英）驻扎在赤脊山西北部，会掉落 {item:209778}；你需要 14 个。营地东端洞口站着两名精英黑石暗影法师（22-23 级）：拉怪时要避开它们。{area:69} 东侧的黑石营地也会掉落这种盐，但那里的暗影法师、哨兵和猎人都是精英（21-24 级），{npc:334}（26 级）也是精英：留在西北部刷。",
	["The Strange Orb"] = "Strange Orb",
	["The {object:409311}"] = "{object:409311}",
	["The {object:409311} stands at the east end of {area:435}. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the {object:409315} beside it starts the last quest."] = "{object:409311} 位于 {area:435} 的东端。把 奥萨拉克斯宝珠 放在背包里，在长矛处交还微粒：宝珠会碎裂，旁边的 {object:409315} 随即提供最后一个任务。",
	["from the {object:409315}"] = "来自{object:409315}",
	["{area:435} is in south-east {zone:1440}, east of {area:431} (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast {spell:686} and {spell:348}, Infernals keep a fire shield up. They respawn in five minutes."] = "{area:435} 位于 {zone:1440} 东南、{area:431} 以东（那里是部落营地，要绕开）。玛诺洛克鞭笞者、灼热的地狱火、地狱卫士和恶魔指挥官（29-30 级，非精英）会掉落 玛诺洛斯微粒，需要收集 12 个。大约 27 级以下很难单人应付：找另一名玩家同行，或晚些再来。地狱卫士会击倒，鞭笞者会施放 {spell:686} 和 {spell:348}，地狱火会一直保持火焰护盾。它们每五分钟刷新一次。",
	["{npc:3663} stands at {area:413} in western {zone:1440}, south of the {zone:1439} road. He sends you to {zone:1453} with the orb."] = "{npc:3663} 站在 {zone:1440} 西部的 {area:413}，位于通往 {zone:1439} 的道路南侧。他会让你带着宝珠前往 {zone:1453}。",
	["{npc:5492} stands in the Cathedral of Light; she sends you to a warlock for a second opinion."] = "{npc:5492} 站在圣光大教堂中；她会让你找一名术士听听另一种意见。",
	["{npc:5495}, the warlock trainer, is in the {object:2101}'s warlock sanctum, down in the {object:2164}'s cellar. She wants 14 {item:209778} to read the orb."] = "术士训练师{npc:5495}在{object:2101}的术士密室中，位于{object:2164}的地下室深处。她需要14个{item:209778}来解读宝珠。",
}

G["forever/class/paladin/holy-mightstone"] = {
	["A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever."] = "一次性石头，10分钟内大幅增强你对亡灵的战斗力；在无限服务器中，旧的物品选择可能已经取消。",
	["At 50 {npc:5149}, the paladin trainer in the {object:32362}, sends you to {area:3197} in the {zone:1422}. {npc:928} in {zone:1453} gives the same quest."] = "50级时，{object:32362}的圣骑士训练师{npc:5149}会派你去{zone:1422}的{area:3197}。{zone:1453}的{npc:928}也提供相同任务。",
	["At 50 {npc:928}, the paladin trainer in the Cathedral of Light, sends you to {area:3197} in the {zone:1422}. {npc:5149} in {zone:1455} gives the same quest."] = "50级时，圣光大教堂的圣骑士训练师{npc:928}会派你去{zone:1422}的{area:3197}。{zone:1455}的{npc:5149}也提供相同任务。",
	["Back to Ashlam in {area:3197}: he forges the {item:20620}. Look at the reward window before you hand in: Classic also offered the {item:20505}, the {item:20504} or the {item:20512}, and Forever's notes say that choice may be gone. Use the stone before a fight against undead ({area:2279}, {area:2057}): it lasts ten minutes and is gone after one use."] = "回到 {area:3197} 找阿什拉姆：他会铸成 {item:20620}。交还前先查看奖励窗口：经典怀旧服还可以选择 {item:20505}、{item:20504} 或 {item:20512}，而无限的说明称这项选择可能已取消。与亡灵作战前使用这块石头（{area:2279}、{area:2057}）：效果持续十分钟，使用一次就会消失。",
	["Back to {area:3197}. Ashlam needs the voodoo of the {area:1417}'s trolls for the stone."] = "返回 {area:3197}。阿什拉姆需要 {area:1417} 巨魔的巫毒力量来处理这块石头。",
	["Kill the Scourge of the {zone:1422} with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a {item:12840} about two kills in five. {area:197}, just east of {area:3197} around {area:196}, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast {spell:120} and {spell:1449} up close, Dark Summoners run for help at low health."] = "佩戴委任徽章，击杀{zone:1422}的天灾军团：骷髅、食尸鬼和教徒（50-58级）掉落{item:12840}的概率约为五只出两个。最近的刷怪地点是{area:197}，就在{area:3197}东边、{area:196}周围。避开在田野中巡逻的血肉傀儡；骷髅守护者会在近距离施放{spell:120}和{spell:1449}，黑暗召唤师则会在生命值低时逃跑求援。",
	["Minion's Scourgestones"] = "{item:12840}",
	["Paladin"] = "圣骑士",
	["The Scourge drop no Scourgestones unless you wear an {item:12846}. {npc:10840} gives you one through her quest, {item:12846}, which you hand in straight away (if you already have one from {area:2268}, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones."] = "除非戴着{item:12846}，否则天灾不会掉落天灾石。{npc:10840}会通过她的任务给你一个{item:12846}，接到后立刻交还（如果你已经从{area:2268}拿到一个，就戴那个）。把它装备在饰品栏：它会显示为一个永不消失的增益。一直戴着，直到你攒够20块石头。",
	["The Scourge drop no Scourgestones unless you wear an {quest:5401}. {npc:10840} gives you one through her quest, {quest:5401}, which you hand in straight away (if you already have one from {area:2268}, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones."] = "除非佩戴{quest:5401}，否则天灾怪物不会掉落天灾石。{npc:10840}会通过她的“{quest:5401}”任务给你一个，该任务可立即交还（如果你已经从{area:2268}拿到一个，就戴那个）。将它装备到饰品栏：会显示为一个永不消失的增益效果。收集满20块石头前一直戴着。",
	["The {area:1417}"] = "{area:1417}",
	["The {item:12846}"] = "{item:12846}",
	["The {quest:5401}"] = "{quest:5401}",
	["{area:1477}, the {area:1417}, lies in the {area:74} in eastern {zone:1435}: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first."] = "{area:1477}，也就是{area:1417}，位于{zone:1435}东部的{area:74}：沿废墟台阶上去，潜入被水淹没的大厅，再沿楼梯下行至传送门。这是适合50-55级左右五人小队的地下城。6名精英巨魔小首领（51-52级）站在神殿大型圆形大厅周围的阳台上，每个都在各自侧道的一群精英后面。它们每次必掉对应羽毛：加什尔和{npc:5716}掉琥珀色，胡库和米杉掉蓝色，祖罗和洛若尔掉绿色；6个都要击杀。胡库会召唤守护者并施放群体暗影箭，米杉会治疗：优先击杀它们。",
	["{area:3197} is the Alliance camp at the south end of the {zone:1422}, north of the Alterac foothills. {npc:10838} commands it; {npc:10840} stands in the same camp."] = "{area:3197} 是 {zone:1422} 最南端的联盟营地，位于奥特兰克山麓以北。{npc:10838} 在此指挥；{npc:10840} 也在同一个营地中。",
	["{item:12840} x20"] = "{item:12840} × 20",
	["{item:12846}: equip it"] = "{item:12846}：装备它",
	["{item:20606} x2: Gasher, {npc:5716}"] = "{item:20606} x2：加什尔、{npc:5716}",
	["{item:20607} x2: Hukku, Mijan"] = "{item:20607} x2：胡库、米杉",
	["{item:20608} x2: Zolo, Loro"] = "{item:20608} x2：祖罗、洛若尔",
	["{npc:1854} keeps watch at {area:196} on {area:197}, east of the camp. He turns your 20 stones into one {item:20612}: keep it."] = "{npc:1854} 在营地东边、{area:197} 上的 {area:196} 放哨。他会把你的 20 块石头合成一块 {item:20612}：留着它。",
}

G["forever/class/paladin/tome-of-divinity"] = {
	["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "12级时，{zone:1455}的{object:32362}内的圣骑士训练师{npc:5149}会派你上楼找{npc:6179}。这趟跑腿可做可不做，只奖励少量经验：{area:131}的{npc:1232}和{zone:1453}的{npc:928}也提供相同任务（接受其中一个，其他的就会关闭），而且即使不做，{npc:6179}也会开启任务线。",
	["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "12级时，{area:87} 的圣骑士训练师 {npc:927} 会派你去找 {zone:1453} 圣光大教堂里的 {npc:6171}。这个跑腿任务可选，只给少量经验：{zone:1455} 的 {npc:5149} 也提供相同任务（接了其中一个就无法接另一个），即使不做也能直接找 {npc:6171} 开始后续任务链。",
	["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "返回光明大教堂：将文稿交给{npc:6173}，{npc:6171}会教你{spell:7328}。",
	["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "回到大教堂。{npc:6171} 会给你 {item:6866}；受伤的 {npc:6173} 就躺在同一大厅的祭坛旁。保留这个符记：之后还需要对 {npc:6172} 使用。如果弄丢了，{npc:6171} 会再给你一个（{item:6866}）。",
	["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "回到 {object:32386} 楼上：{npc:6178} 收下书稿，{npc:6179} 教你 {spell:7328}。",
	["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "返回 {object:32386} 楼上。{npc:6179} 会给你 {item:6866}；她的丈夫 {npc:6178} 就躺在同一层。保留这枚符记，之后要对 {npc:6177} 使用。若弄丢了，{npc:6179} 会再给你一枚（{item:6866}）。",
	["Paladin"] = "圣骑士",
	["Right-click the {item:6775}"] = "右键点击{item:6775}",
	["Right-click the {item:6916}"] = "右键点击{item:6916}",
	["The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the {item:6847}. They run for help at low health: finish them or step back. They respawn in three minutes."] = "黑铁间谍（9-11 级，共十二名）潜伏在湖下方的小屋周围，就在纳姆南侧；站在他所在的山坡上就能看到。它们大约每击杀两只会掉落一个 {item:6847}。生命值低时会逃跑求援：及时击杀，或后退避开。它们每三分钟刷新。",
	["The Defias Rogue Wizards around the big stone tablet east of {npc:6172} carry the {item:6846}: about one kill in two drops it, but some players need many kills. They respawn in three minutes."] = "{npc:6172} 东侧大石碑周围的迪菲亚流浪巫师携带 {item:6846}：大约每击杀两只会掉落一个，但有些玩家需要击杀很多只。它们每三分钟刷新。",
	["The summons (Dwarf)"] = "召唤（矮人）",
	["The summons (Human)"] = "召唤（人类）",
	["The {item:6846}"] = "{item:6846}",
	["The {item:6847}"] = "{item:6847}",
	["The {item:6866}"] = "{item:6866}",
	["{item:2589} x10"] = "{item:2589} × 10",
	["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：{npc:474}",
	["{item:6847}: Dark Iron Spies"] = "{item:6847}：黑铁间谍",
	["{item:6866} on {npc:6172}'s body"] = "{npc:6172} 尸体上的 {item:6866}。",
	["{item:6866} on {npc:6177}'s body"] = "{npc:6177} 尸体上的 {item:6866}。",
	["{npc:6171} stands inside the Cathedral of Light. He hands you the {item:6775}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6171} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6171} 站在圣光大教堂内。他会给你 {item:6775}：在背包中右键点击，开始下一个任务。如果书提示任务已经完成，销毁它，再找 {npc:6171} 要一本新的。如果手头有10块 {item:2589}，带上以备下一步使用。",
	["{npc:6171}, Cathedral of Light"] = "{npc:6171}，光明大教堂",
	["{npc:6172} lies dead on {area:56}, the island in {area:86} in eastern Elwynn, on top of one of the mounds around the stone circle. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes. The Defias Rogue Wizards on the island (level 9-10) cast {spell:116} from far off: they stand apart, so pull one at a time."] = "{npc:6172}的尸体位于艾尔文森林东部{area:86}中的小岛{area:56}上，在石圈周围的一个土丘顶端。选中尸体，使用{item:6866}复活他，然后与他交谈。如果刚有其他圣骑士复活过他，尸体大约3分钟内会重新出现。岛上的迪菲亚流浪巫师（9-10级）会从远处施放{spell:116}：它们站得较分散，一次只引一个。",
	["{npc:6174} stands at a corner in the middle of the {object:2096}, outside a general goods store. She wants 10 {item:2589}: humanoids drop it (Riverpaw gnolls in {zone:1436} about every other kill, Defias and kobolds a little less), or buy it at the Auction House a few steps away in the {object:2096}."] = "{npc:6174} 站在 {object:2096} 中部的一个街角，位于一家杂货店外。她需要10块 {item:2589}：人形生物会掉落（{zone:1436} 的河爪豺狼人约每杀两只掉一块，迪菲亚成员和狗头人的掉率稍低），也可以到几步之外的 {object:2096} 拍卖行购买。",
	["{npc:6175} walks the outer ring of the Commons, past the front gate, the bank and the Auction House. He wants 10 {item:2589}: humanoids drop it ({npc:1245} in {area:131} every time, Dark Iron Ambushers about two kills in five), or buy it at the Auction House on his ring."] = "{npc:6175} 在平民区外圈行走，会经过前门、银行和拍卖行。他需要 10 个 {item:2589}：人型生物会掉落（{area:131} 的 {npc:1245} 每次都掉，黑铁伏击者大约每击杀五只掉落两次），也可以在他行走路线上的拍卖行购买。",
	["{npc:6177} lies dead in {zone:1426}, not {zone:1432}: east past {area:131}, north-east of Ironband's compound, on the smallest of three little hills between {area:212} and the {object:147516} camp. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes."] = "{npc:6177} 的尸体在 {zone:1426}，不在 {zone:1432}：向东经过 {area:131}，在铁环营地东北方、{area:212} 与 {object:147516} 营地之间的三座小山丘中最小的那座上。选中他的尸体，使用 {item:6866} 将他复活，然后与他交谈。如果刚被另一位圣骑士复活过，他的尸体会在约三分钟内重新出现。",
	["{npc:6179} stands upstairs in the {object:32386}, in the {object:32362}: take the ramp at the back of the hall. She hands you the {item:6916}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6179} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6179} 位于 {object:32362} 的 {object:32386} 楼上：走大厅后面的斜坡上去。她会给你 {item:6916}：在背包里右键点击它，开始下一个任务。如果书提示任务已经完成，就摧毁它，再向 {npc:6179} 要一本。有的话，带上 10 个 {item:2589}，下一步要用。",
	["{npc:6179}, upstairs in the {object:32386}"] = "{npc:6179}，在{object:32386}楼上",
	["{spell:7328} (Alliance)"] = "{spell:7328}（联盟）",
	["{spell:7328} at 12, the paladin's resurrection: an easy chain through your capital and its home zone."] = "12级学习{spell:7328}，圣骑士的复活技能：一条简单的任务链，途经你的主城及其所在地区。",
}

G["forever/class/paladin/verigans-fist"] = {
	["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "20级时，{object:32362} 内 {object:32386} 楼上的 {npc:6179} 会给你 {item:6776}。右键点击它：它会让你前往 {zone:1453} 的圣光大教堂寻找 {npc:6171}。从 {zone:1455} 搭乘 {area:2257} 前往 {zone:1453}。",
	["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "回到圣光大教堂：{npc:6171} 会给你盾牌 {item:9607}，并教你 {spell:5502}。",
	["Back to {npc:3649} in {area:442}: he purifies the gem."] = "回到{area:442}找{npc:3649}：他会净化宝石。",
	["Back to {npc:6241}"] = "回到{npc:6241}处",
	["Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil."] = "把四个部件带给 {zone:1455} 外的 {npc:6181}。接受他的最后一个任务，然后在他身旁等候，直到他在铁砧上铸好锤子。",
	["Goblin Woodcarvers, inside"] = "地精木匠，在副本内",
	["Paladin"] = "圣骑士",
	["Protect {npc:6182}: three waves"] = "保护{npc:6182}：三波敌人",
	["Right-click the {item:6776}"] = "右键点击{item:6776}",
	["The Alliance paladin's rare two-handed mace for the 20s, with a shield and {spell:5502} on the way."] = "联盟圣骑士20多级的稀有双手锤，途中还能拿到一面盾牌和{spell:5502}。",
	["The Blackfathom naga in the flooded passages around the {area:2797} entrance, on {zone:1440}'s north-west coast, drop the {item:6995}: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "{zone:1440} 西北海岸、{area:2797} 入口周围淹水通道里的黑暗深渊纳迦会掉落 {item:6995}：黑暗深渊海潮祭司（20—21级）、黑暗深渊智者（21—22级）和 黑暗深渊海巫（23—24级），掉率为二分之一。无需进入副本。它们全是精英：建议组队；玩家可以逐个单杀，但比较困难。它们会自疗，低血量时会逃跑求援，部分身旁还有萨特，黑暗深渊海巫 会在近距离施放 {spell:122}。有玩家反馈，处于团队中时不掉落。",
	["The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east {zone:1432}, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one."] = "矿石箱在{zone:1432}东北部莫格罗什食人魔营地中央的露天区域，位于几个洞穴之间，一棵大树和一辆破损的马车旁。营地里大约有十五个精英莫格罗什食人魔（18-19级），它们会击倒你，五分钟后刷新：建议组队；20-22级时大约需要三人。箱子每次拾取后两秒就会刷新，因此队伍中的每位圣骑士都能拿到一个。",
	["The {item:6995}"] = "{item:6995}",
	["The {item:7083}"] = "{item:7083}",
	["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581} 是 {area:20} 地下的五人地下城；副本传送门位于 {area:20} 矿井底部。地精木匠（18—19级精英）在斯尼德所在的桅杆房间里，必定掉落木材。",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}的矿洞里",
	["{area:236} is a dungeon for a group of five in the low to mid 20s, in southern {zone:1421}, Horde land: a long trip for the Alliance, through the {zone:1437}, Arathi and {area:287}. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it."] = "{area:236} 是适合 20 级出头至 25 级左右五人小队的地下城，位于部落领土 {zone:1421} 南部：联盟要走很远，途经 {zone:1437}、阿拉希和 {area:287}。锤子在地下城前段的马厩里，放在马匹对面的箱子上，位于庭院尽头、上行斜坡之前；被人取走后五分钟会重新出现。",
	["{npc:3649} is in {area:442}. Take his quest before you hunt naga: the Kor Gem never drops without it."] = "{npc:3649} 位于 {area:442}。猎杀纳迦前先接他的任务：没有任务就绝不会掉落科尔宝石。",
	["{npc:6171} stands in the Cathedral of Light. Humans get the {item:6776} from him. Right-click the book to start its quest and hand it straight back to him."] = "{npc:6171} 站在圣光大教堂中。人类可从他那里领取 {item:6776}。右键点击书籍以接受它提供的任务，然后直接交还给他。",
	["{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes."] = "{npc:6181}在{zone:1455}城门外工作，而非城内。他会给你{item:6996}：共4个部分，顺序任意。请保留笔记。",
	["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}, south of {area:20}: take the path that runs south beside the {area:1581}' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or {npc:6182} die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24."] = "{npc:6182}的农舍在{zone:1436}西南海岸、{area:20}以南：沿着{area:1581}后门出口旁向南延伸的小路走。接受任务后，她会从果园走向房屋，随后三波迪菲亚袭击者（17-18级）前来进攻：依次为三名、四名和五名。靠近她战斗，避免敌人围攻她，并在她生命值降低时为她治疗。每波之间有时间吃喝，她也会恢复满血。如果你或{npc:6182}死亡，任务就会失败：放弃后重新找她接受（她死亡后五分钟会刷新）。玩家通常认为约24级以前很难单独完成。",
	["{npc:6241} is downstairs in the house of {area:144} that has a tailoring merchant outside. His quest only opens once you hold Jordan's."] = "{npc:6241} 在 {area:144} 一栋房屋的楼下，屋外有裁缝商人。只有先接到乔丹的“正义试炼”任务，才能接受他的任务。",
	["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "{npc:6241} 会把矿石制成 {item:6993}，这就是乔丹需要的部件。",
	["{object:91138}, inside"] = "{object:91138}，在副本内",
	["{object:92420} crate"] = "{object:92420}箱子",
}

G["forever/class/priest/confounding-flash-and-contingency-plan"] = {
	["Any {quest:94820} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何 {quest:94820} 信件都交给 {npc:258785}，他位于 {zone:1455} 的 {object:32362} 中的 {object:32386}。",
	["Any {quest:94823} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何 {quest:94823} 信件都交给 {npc:258785}，他位于 {zone:1455} 的 {object:32362} 中的 {object:32386}。",
	["Any {quest:94825} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何 {quest:94825} 信件都交给 {npc:258785}，他位于 {zone:1455} 的 {object:32362} 中的 {object:32386}。",
	["Any {quest:94826} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何 {quest:94826} 信件都交给 {npc:258785}，他位于 {zone:1455} 的 {object:32362} 中的 {object:32386}。",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}."] = "在{zone:1429}达到10级时，{area:87}狮王之傲旅店楼上的{npc:377}会交给你一封{quest:94817}信件，让你送给{zone:1455}的{npc:258785}。",
	["At 10 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94817} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "10级时，在 {zone:1453} 圣光大教堂祭坛旁的 {npc:376} 会给你一封 {quest:94817} 的信，要交给 {zone:1455} 的 {npc:258785}（从 {object:28027} 乘坐 {area:2257} 前往）。",
	["At 10, go to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362} (north-west of the city), right beside {npc:11406}: she gives {quest:94817} and takes it back at once. No letter needed. {quest:94817} confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run."] = "10级时，前往 {zone:1455} 西北部 {object:32362} 内的 {object:32386}，找就在 {npc:11406} 身旁的 {npc:258785}：她会给予 {quest:94817}，并立即接受交还，不需要信。{quest:94817} 可使周围最多五个敌人迷惑3秒（受到任何伤害都会清醒），冷却时间2分钟：可趁机退后治疗，或逃跑。",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}. {area:131} is on the road up to the city."] = "达到 10 级后，{area:131} 的 {area:2102} 内的牧师训练师 {npc:1226} 会给你一封 {quest:94817} 信件，让你交给 {zone:1455} 的 {npc:258785}。{area:131} 位于上山进城的道路旁。",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94818} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "达到 20 级后，在 {zone:1453} 圣光大教堂祭坛旁的 {npc:376} 会给你一封 {quest:94818} 信件，让你交给 {zone:1455} 的 {npc:258785}（从 {object:28027} 乘坐 {area:2257} 前往）。",
	["At 20, {npc:258785} in the {object:32386} teaches {quest:94818} with a quest she gives and takes back at once. {quest:94818} wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with {spell:139} and {spell:17}). 5-minute cooldown."] = "20级时，{object:32386} 内的 {npc:258785} 会给予一个可立即交还的任务，教你 {quest:94818}。{quest:94818} 可守护一位友方目标30秒：如果其生命值降到35%以下，就会立即获得护盾和持续治疗效果（可与 {spell:139} 和 {spell:17} 叠加）。冷却时间5分钟。",
	["Follow the road up from {area:131} into {zone:1455} and to the {object:32362}: {npc:258785} in the {object:32386} takes the letter and teaches {quest:94824}."] = "从 {area:131} 沿路上山进入 {zone:1455}，前往 {object:32362}：{object:32386} 内的 {npc:258785} 会收下信件，并教你 {quest:94824}。",
	["Hand Laurena's letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "将高阶牧师劳瑞娜的信交给{npc:258785}，她在{zone:1455}的{object:32362}内的{object:32386}：从{zone:1453}的{object:28027}乘坐{area:2257}前往。",
	["Hand the letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "将信交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}：从{zone:1453}的{object:28027}搭乘{area:2257}前往。",
	["Priest"] = "牧师",
	["The Gnome priest spells, new in Forever: {quest:94817} at 10, {quest:94818} at 20. Free, no objectives."] = "无限新增的侏儒牧师法术：10级学{quest:94817}，20级学{quest:94818}。免费，没有任务目标。",
	["{npc:1226}: take his {quest:94817} letter"] = "{npc:1226}：领取他的{quest:94817}信件",
	["{npc:376}: take her {quest:94817} letter"] = "{npc:376}：领取她的{quest:94817}信件",
