	["{npc:377}: take {quest:5628}"] = "{npc:377}：接取{quest:5628}",
	["{npc:5142}: take {quest:5628}"] = "{npc:5142}：接取{quest:5628}",
	["{npc:5489}: take {quest:5628}"] = "{npc:5489}：接取{quest:5628}",
