G["forever/class/rogue/blade-of-cunning-alliance"] = {
	["A dagger at 10 from your home town's rogue quests."] = "10级时来自你家乡潜行者任务的匕首。",
	["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "10级时，{area:131}{area:2102}的潜行者训练师{npc:1234}会让你去找{zone:1455}的{npc:5165}。",
	["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "10级时，{area:186} 旅店内的盗贼训练师 {npc:3599} 会给你一朵玫瑰，要交给 {zone:1457} 的 {npc:4163}。如果丢了玫瑰，就放弃任务再重接。",
	["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "10级时，{area:87} 狮王之傲旅店楼上的盗贼训练师 {npc:917} 会给你一个包裹，要交给 {zone:1453} 的 {npc:332}。如果还没学会 {spell:921}，就先学习：这条任务线会用到它。",
	["Back to Mathias Shaw"] = "回到马迪亚斯·肖尔处",
	["Back to {npc:4163}"] = "回到{npc:4163}处",
	["Back to {npc:5165}"] = "回到{npc:5165}处",
	["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "向北前往 {zone:1453}。肖尔在 {object:2100} 的军情七处建筑楼上（任务写的是兵营，实际指军情七处）。",
	["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "向西前往{area:133}。通往入口的路旁有一座木制螺旋塔：{npc:6886}潜行待在顶部平台，旁边有一名10级的{npc:1211}，所以只有靠近才能看见他。",
	["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "向西前往{zone:1457}。{npc:4163}在{area:1658}的地下：下去的入口在大德鲁伊所在树木左侧、那棵分叉树的根部，靠近夜刃豹训练师。她的地图标记显示在地面上。",
	["Pick Pocket Sethir the Ancient for {item:7737}"] = "对远古者塞希尔使用搜索，获得{item:7737}",
	["Rogue"] = "潜行者",
	["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "{npc:6846}（10级，地精）在 {area:797} 的码头屋内工作，位于艾尔文森林南缘的河边、{area:87} 以南。潜行进去，从背后对他使用 {spell:921}：他的尸体绝不会掉落日程表。不要先用 {spell:2070}，也不要开战：他会叫来三波保镖。远离屋内壁炉，否则会被烧出潜行。死亡后他会在2到5分钟内刷新。",
	["{item:7298} (Alliance)"] = "{item:7298}（联盟）",
	["{item:7675}: {spell:921} the {npc:6846}"] = "{item:7675}：对{npc:6846}使用{spell:921}",
	["{item:7737}: Pick Pocket Sethir the Ancient"] = "{item:7737}：偷窃上古者塞希尔",
	["{npc:332}, SI:7"] = "{npc:332}，军情七处",
	["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165}在{zone:1455}北部的盗贼区{object:32383}：进入门外站着一名可疑商人的建筑，然后下楼。",
	["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909} 是12级萨特，住在 {area:264} 北面的巨大树枝上：穿过林地北侧墙上的V形缺口，沿树枝往外走。对他使用偷窃来取得日记；击杀不会掉落，开战还会引来三个塞希尔的爪牙。他会在主树枝和一根侧枝之间走动：潜行到主树枝远端等待，等他回来时从背后偷窃，然后用 {spell:2983} 跑开。他死亡后8分半刷新。",
	["{spell:921} the {npc:6846} for the {item:7675}"] = "对{npc:6846}使用{spell:921}，获得{item:7675}",
}

G["forever/class/rogue/certificate-of-thievery"] = {
	["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "达到 16 级后，{area:131} 的 {area:2102} 中的 {npc:1234} 会让你去找 {zone:1455} 的 {object:32383} 中的 {npc:5165}。",
	["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "16级时，{area:186} 旅店内的 {npc:3599} 会派你前往 {zone:1457} 进行 {quest:2259}。",
	["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "16 级时，{area:87} 狮王之傲旅店楼上的潜行者训练师 {npc:917} 会让你去 {zone:1453} 找 {npc:6946}。接下后就不能再接其他城镇的同类引导任务。",
	["Back to {npc:6966}"] = "回到{npc:6966}那里",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "向东穿过 {zone:1429} 进入赤脊山，或飞往 {area:69}。{npc:6966} 站在镇子南边 {area:69} 的某个码头上的箱子上；接到任务时他会给你 {item:5060}（{area:69} 的 {npc:3090} 也出售）。背包里没有工具就无法使用 {spell:1804}。",
	["Rogue"] = "盗贼",
	["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "16级时你的第一份开锁工作：为{quest:2300}打开{quest:2282}的{npc:6966}的锁箱。",
	["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214}站在{area:1658}。之后从{area:702}乘船到{area:442}，再从{area:442}乘船到{area:17203}。",
	["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165}在{object:32383}的一栋房子里，下楼梯即可找到；屋外有个可疑的商人。然后飞往{zone:1453}，或乘坐{area:2257}前往。",
	["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946} 在 {object:2100} 的 {quest:2300} 建筑楼上，位于潜行者训练师后方。离开前：如果还不会 {spell:1804}，可向 {quest:2300} 建筑里的 {npc:13283} 学习；下一个任务考验的就是开锁。",
	["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282}位于{area:69}东面、道路上方；附近有黑石兽人游荡。里面的练习用保险箱几乎立即刷新：持续开锁，直到能打开{object:121264}（大约需要25点开锁技能）。开锁技能上限每升一级提高5点，因此等级太低可能无法继续提升。有些箱子设有陷阱（例如冰霜陷阱），但仍可提升技能。无限中，箱子附近有20级蜘蛛游荡：先清掉它们或带个朋友来。保险箱必定装有信物，使用后2秒刷新。只要还能提升技能就继续练习：下一个职业任务约需75点。",
}

G["forever/class/rogue/poisons-alliance"] = {
	["/lay with the Doc targeted"] = "选中医生后输入 /lay。",
	["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: an engineering supplier, who keeps only a few (or an engineer or the Auction House). The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "这四样都在{zone:1453}。{item:3421}：伯纳德或{npc:1303}的花店，在{object:2096}运河旁。{item:3372}：许多杂货和炼金商人（{npc:1257}、{npc:1325}等）有售。{item:4371}：工程学供应商，存货很少（或者找工程师，或去拍卖行）。{item:8431}在运河边裁缝店{object:2177}柜台左端旁的地上；只有接了这个任务才能拾取。如果不做解毒，{item:6452}（{skill:129}）或德鲁伊的{spell:526}也能解除{spell:9810}。",
	["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "20级时，{object:2100}军情七处大楼楼上的{npc:332}会让你去找{zone:1436}的{npc:7024}。在无限，这条任务链用于学习毒药技能，不要跳过。",
	["Back to {npc:7207}"] = "回到{npc:7207}处",
	["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "无限 通过这条任务线而不是训练师教授毒药；同时获得{item:7676}的配方。",
	["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol."] = "先拿钥匙。{npc:7051}（23级，非精英）从塔楼入口出发，绕外侧巡逻；就是那个尖刺发型、身后拖着黄色光点的敌人。潜行靠近，从背后对其使用{spell:921}：必定能偷到钥匙。它伤害很高，若潜行被打破，就用{spell:2983}逃离。也要留意同时巡逻的两名迪菲亚苦工。",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {item:6947} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "穿过艾尔文森林北上前往 {zone:1453}；马迪亚斯·肖尔在军情七处楼上。他会教你毒药技能，并给你 {item:7676} 配方。毒药需要制作，不能直接购买：每批 {item:6947} 需要一份 {item:2928} 和一个 {item:3371}，军情七处旁 {object:2100} 的 {npc:1325} 和 {npc:1326} 都有出售。各买一组，从法术书中打开毒药界面制作，再将毒药涂在武器上。",
	["Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like."] = "密探吉尔妮潜行藏在一棵大树的西侧，树前有两棵小树；位置在{zone:1436}最东面、{npc:7053}的迪菲亚塔楼正北方，靠近{zone:1431}边界。想了解塔楼内部布局，可以阅读{item:8046}。",
	["Klaven's journal"] = "克拉文的日记",
	["Poisons (Alliance)"] = "毒药（联盟）",
	["Rogue"] = "潜行者",
	["Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "潜行上塔。迪菲亚巡塔员（23级）和哨兵（24级）守着各层；如果想清掉它们，用匕首伏击可以直接击杀。{npc:7053} 是26级精英，在顶层等候：用闷棍控制他，或找个朋友帮忙。他书桌旁的 {object:123214} 需要约70—75点开锁技能（先去赤脊山 {area:97} 的箱子上练习）。一个技巧：趁哨兵不在时，从椅子跳到灯上，再跳到箱子上方的书架上，解除潜行，从那里打开箱子。开箱会使你中了 {spell:9810}，让你一段时间内无法潜行，也会让无人机发现你；因此要先拿钥匙。然后离开。",
	["The cure's ingredients"] = "解药的材料",
	["The {item:7923}"] = "{item:7923}",
	["{item:7908}: the {object:123214}, top floor"] = "{item:7908}：顶层的 {object:123214}",
	["{item:7923}: {spell:921} the {npc:7051}"] = "{item:7923}：对{npc:7051}使用{spell:921}",
	["{npc:332}: Poisons"] = "{npc:332}：毒药",
	["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "你身上仍有{quest:2607}。{npc:7207}在军情七处大楼的地下室工作：向下的楼梯就在上楼楼梯下方、{npc:1325}身后。选中他并输入 /lay（后面不要加任何内容）让他检查，然后等待。若他没有反应，放弃任务后重新接受，等他要求你躺下。",
	["{spell:921} the {npc:7051} for the {item:7923}"] = "对{npc:7051}使用{spell:921}，获得{item:7923}",
}

G["forever/class/shaman/call-of-air-alliance"] = {
	["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "30级时，{zone:1455} 的萨满祭司训练师 {npc:258098} 会派你去找 {zone:1417} 的 {npc:259023}。30级的空气图腾（根基图腾、{spell:10596}）需要他给的 {item:5178}。",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "需要五个扭曲的空气图腾。{zone:1443}西部{area:2408}以北和东北方的玛洛迪半人马（36-40级）会携带；斥候的掉率接近两只出一个。玛洛迪争斗者会施放网和缴械，玛洛迪逐风者会治疗，玛洛迪狂怒者会施放{spell:9654}：每次只引一个。刷新约需五分钟。",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "五个扭曲的大地图腾。{zone:1435} 的 {area:75} 北侧及东北侧的失落者（鱼人，34-39 级）携带这些图腾；它们大多会在受伤后逃跑求援。",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "需要五个扭曲的火焰图腾。它们由 {zone:1418} 的 {area:338} 南边的石窟穴居人携带（击颅者、断骨者和萨满祭司，37-41 级）；萨满祭司会放置火焰新星图腾和 {npc:3560}，断骨者受伤后会逃跑求援。大约五分钟刷新。",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "五个扭曲的水之图腾。{zone:1445} 北部、{area:496} 东北面的 黑鳍 鱼人（35—38级）携带这些图腾。",
	["Shaman"] = "萨满",
	["The steam pools"] = "蒸汽池",
	["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "让你放置空气图腾的{item:5178}，然后在40级获得一把自选武器。",
	["Twisted Air Totems"] = "扭曲的空气图腾",
	["Twisted Earth Totems"] = "扭曲的大地图腾",
	["Twisted Fire Totems"] = "扭曲的火焰图腾",
	["Twisted Water Totems"] = "扭曲的水之图腾",
	["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} 是位于 {zone:1413} 南缘的五人地下城（箭头指向入口）；{npc:4421}（33级精英）是最终首领。她会施放 {spell:8292}、对盟友施放 {spell:139}，还会使用 纯净术；{item:274463} 只有她会掉落。",
	["{item:212792}, from the {npc:216474}"] = "{item:212792}，来自{npc:216474}",
	["{item:274463}, from {npc:4421}"] = "{item:274463}，来自{npc:4421}",
	["{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east."] = "{npc:259023} 扎营在阿拉希东北部部落城镇 {area:321} 正西方的山丘中：小心镇上的守卫。飞往 {area:320}，再向东北走。",
	["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:259023} 会给你 {item:268582}。{zone:1441} 路途遥远：可以坐船到塞拉摩，再沿路向西；或飞往 {zone:1444} 边界上的 {area:489}，再向东进入峡谷。在 {area:484} 西北方的蒸汽池放置 {item:268582}，召出被腐化的元素，然后是 {npc:216474}；仪式进行时，钢鬃野猪人会加入战斗。这是组队任务：至少带一两个朋友。{item:212792} 大约每击杀两次掉落一次，小队中每个人都能拾取。",
	["{npc:259023}: your {item:5178}"] = "{npc:259023}：你的{item:5178}",
	["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "{npc:6176} 扎营在 {zone:1416} 东部的废墟中：从 {area:272} 出发，沿镇子东边的河流向北进入山丘。选择你的武器：{item:280607}、{item:280605} 或 {item:280604}。",
	["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}：{item:280696}和你的武器",
	["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789}和风暴武器（联盟）",
}

G["forever/class/shaman/call-of-earth-alliance"] = {
	["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "回到 {area:77} 内找提欧·暴风之锤。他会给你 {item:6635}：先不要喝。",
	["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "把{item:6656}带回{area:77}里的提欧·暴风之锤处。永久将{item:5175}留在背包里：所有大地图腾都需要它。",
	["Iceclaw Bear Pendants"] = "冰爪熊坠饰",
	["Lost the {quest:94472}?"] = "弄丢了{quest:94472}？",
	["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "只有当背包里的 {quest:94472} 已经不见了（在石头以外的地方喝掉，或卖掉）才需要：提欧·暴风之锤会再给你一份。",
	["Shaman"] = "萨满祭司",
	["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "霜鬃巨魔幼崽（3-4 级）占据 {area:77} 西边和西南的雪坡，霜鬃巨魔新兵（3-4 级，会在远处发射寒冰箭）则驻扎在南边。两者都携带坠饰，大约三分钟刷新。",
	["The Spirit Stone"] = "灵魂石",
	["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "用于与大地元素沟通的石头位于{area:77}西北面的积雪山脊上。小径很容易错过：从谷底沿山坡爬上去，在接近山顶的小营地左转就能看到石头。站在旁边喝下{item:6635}，在效果消失前与{npc:5891}交谈。",
	["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "你的{item:5175}：没有它就无法施放任何大地图腾。4级时随之获得{spell:8071}。",
	["it hands you the {item:6656}: keep it"] = "它会给你 {item:6656}：留着它",
	["the level 4 shaman spells"] = "4级萨满祭司法术",
	["{item:6635}, beside the Spirit Stone"] = "{item:6635}，在灵魂石旁",
	["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446}在{area:77}内训练萨满祭司，那是{area:132}南端的大厅。任务4级即可接受。如果一直没做，现在已到10级或更高，{zone:1455}的{npc:258098}或{area:131}的{npc:258113}会给你{quest:94373}，指引你回去找提欧·暴风之锤：顺路接上，赚些经验。",
	["{npc:257446}: a new {quest:94472}"] = "{npc:257446}：新的{quest:94472}",
	["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446}：{spell:8071}和你的{item:5175}",
	["{quest:94373} (Alliance)"] = "{quest:94373}（联盟）",
}

G["forever/class/shaman/call-of-fire-alliance"] = {
	["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "10级时，{area:131}的萨满祭司训练师{npc:258113}，或{zone:1455}的萨满祭司训练师{npc:258098}，会派你去找{npc:257597}。",
	["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "穿过南门隧道返回，沿小径上山到 {npc:257597} 的洞穴。把 {item:5176} 永久留在背包里：所有火焰系图腾都需要它。",
	["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "沿小路返回上方的{npc:257808}处。他会用焦油和小袋制作{item:6636}：将它和火炬一起留着。",
	["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "确保火炬在背包中，点击神殿顶上的 {object:61934} 来放置火种，然后再点击一次，接取下一个任务：获得点燃的 {item:277329}。",
	["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "经过 {npc:257808} 后继续爬到山顶。在那里的岩石雕像旁喝下 {item:6636}，即可看见 {npc:5893}（12 级）：它会等你先动手，但放置得越久就越强，而且免疫火焰伤害。立即用 {spell:8017} 和 {spell:8042} 开战。它必定掉落 {item:6655}。",
	["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "沿路向东前往通向 {area:806} 的隧道。离开第一条隧道后靠左，经过 {npc:1959} 和塔楼：一条不易察觉、但会显示在微缩地图上的狭窄小径蜿蜒上山，通往农场上方 {npc:257597} 的洞穴。他会给你 {item:6653}：保留到任务线结束。",
	["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "从 {npc:257597} 所在的平台，可以小心跳下山进入 {zone:1432}，也可以沿隧道原路返回。{npc:257808} 看守着 {area:144} 南侧山顶的神龛：从山峰北侧的道路出发，沿一条悬崖边缘的隐秘小径攀登，沿途有石制图腾作为标记。",
	["Lost the {quest:94473}?"] = "弄丢了{quest:94473}？",
	["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "仅在 {quest:94473} 已经不在背包里时需要：{npc:257808} 会再给你一份。",
	["Shaman"] = "萨满",
	["The Shrine of Eternal Flame"] = "永恒之火神殿",
	["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "碎石怪先知（13—14级）位于湖泊南部 {area:923} 的穴居人群中，以及 {area:144} 东北面的穴居人营地内。它们能从40码外施放 {spell:1245113}，受伤后会逃跑求援：一次只引一只。大约五分钟刷新。",
	["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "坑道鼠地卜师（12-13级）只出现在洛克湖最北端、越过{area:144}后的{area:149}内。它们会在{spell:134}保护下施放{spell:2136}，低血量时会逃跑求援。",
	["The {object:61934}"] = "{object:61934}",
	["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "获得用于所有火焰图腾的{item:5176}、借此学会的{spell:3599}，以及无限的{item:263412}。",
	["{item:6636}, beside the statue"] = "{item:6636}，在雕像旁",
	["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597}：{spell:3599}、你的 {item:5176} 和 {item:263412}",
	["{npc:257808}: a new {quest:94473}"] = "{npc:257808}：新的{quest:94473}",
	["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{area:131} 的 {npc:258113}；或 {zone:1455} 的 {npc:258098}",
	["{quest:94449} (Alliance)"] = "{quest:94449}（联盟）",
}

G["forever/class/shaman/call-of-water-alliance"] = {
	["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "20级时，{zone:1455} 的 {object:32362} 中的萨满祭司训练师 {npc:258098} 会派你去 {zone:1432} 找 {npc:258043}。",
	["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "带着{item:7810}回到{area:146}旁的{npc:258043}处。他会给你{item:6637}和{item:7811}：两件都留着，去{zone:1436}时要用。",
	["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "带着 {item:7813} 返回 {npc:258043} 处。务必将 {item:5177} 永久留在背包中：所有水之图腾都需要它。",
	["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "在 {npc:258203} 洞穴下方瀑布底部、淡水与咸淡混合水交会处，装满 {item:265732}。瀑布附近有 {object:147516} 矮人游荡。",
	["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "飞往 {area:108}，再向南前往 {area:20}：{area:919} 和 {object:619896} 就在其北侧。在神殿旁喝下 {item:6637}，即可看见 {npc:5894}（22 级，会使用 {spell:8056} 和 {spell:122}；只有一个刷新点，击杀三分钟后刷新），击败它取得护腕（必定掉落），再将护腕和 {item:7811} 放在 {object:619896} 上（在这里完成任务，不是找 {npc:258043}）。再次点击神殿：{npc:5895} 会在旁边出现；离开前要与它交谈（若它已消失，在神殿处放弃并重新接受任务）。它会给你 {item:7813}。",
	["Lost the {quest:94616}?"] = "弄丢了{quest:94616}？",
	["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "仅当背包里已经没有{quest:94616}时：出发前往{zone:1436}前，向{npc:258043}再领一个。",
	["Shaman"] = "萨满",
	["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "从 {area:150} 乘船前往 {area:442}（途中会停靠 {area:271}），再飞行或向南步行穿过 {zone:1439}，前往 {zone:1440} 的 {area:415}。在城镇周围的湖中装满 {item:265772}，然后乘船返回米奈希尔港。",
	["The blue waterskin"] = "蓝色水袋",
	["The brown waterskin"] = "棕色水袋",
	["The red waterskin"] = "红色水袋",
	["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "让你能放置水图腾的{item:5177}，以及随之而来的{spell:5394}。",
	["the {item:7810}, for {npc:258043}"] = "{item:7810}，交给{npc:258043}",
	["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71} 从赤脊山东端的 {area:68} 奔流而下（从 {zone:1455} 飞往 {area:69}）。在瀑布底部鱼人夜行者聚集的地方装满 {item:265747}；先把鱼人从取水点拉走。若水囊消失却未计入任务，放弃任务，再从 {npc:258203} 处重新接受以取得新的水囊。",
	["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "{npc:258043} 的地穴小屋位于湖的西北岸，在 {area:146} 下方、{area:144} 以北。",
	["{npc:258043}: a new {quest:94616}"] = "{npc:258043}：新的{quest:94616}",
	["{npc:258043}: your {item:6637}"] = "{npc:258043}：你的{item:6637}",
	["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043}：{spell:5394}和你的{item:5177}",
	["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "{npc:258203} 的家人住在 {zone:1437} 南部瀑布下方的一座洞穴中，位于 {area:836} 以东，不在城镇里。穿过 {zone:1432} 北侧的丹奥加兹隧道，然后离开道路向东走。",
	["{npc:5895}, at the shrine"] = "{npc:5895}，在神龛处",
	["{quest:94494} (Alliance)"] = "{quest:94494}（联盟）",
}

G["forever/class/warlock/dread-mage-hat"] = {
	["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "28级左右可得的布甲头盔：任何联盟玩家都能接扎尔戴斯的差事，术士会额外获得这件奖励。",
	["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "达到 25 级后，{object:2101} 的 {object:2164} 地窖中（术士训练师旁）的 {npc:1435} 需要两种酿制材料。等升级路线带你前往 {zone:1431} 和 {zone:1437} 时再做。",
	["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "再次回去找扎尔迪斯：他会给术士提供一份奖励，由站在身边的小鬼 {npc:1733} 交给你。",
	["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "返回黑爪加尔德斯处。他会配好 {item:2788} 交给你，让你送给祈求者大厅里的 {npc:1439}，位置在进入 {object:2117} 后右侧的第一个大厅。",
	["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "根须长在{area:836}东面小瀑布下水池的岸边、{area:146}下方{object:147516}洞穴旁：是一根高而尖的木质根须，不在大坝正下方。",
	["Warlock"] = "术士",
	["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "{area:1098} 位于 {zone:1431} 东北部、{area:42} 北面。{object:321} 是斯塔文屋旁围栏花园草丛里的一朵小白花，贴近地面，很难看见，需要用鼠标扫过花园寻找。恶臭的食尸鬼（29级）在附近游荡，接敌很快：25级时，让虚空行者缠住最近的一只，拿到花就走。{npc:315}（32级）在屋内，不要招惹他。",
}

G["forever/class/warlock/felhunter-alliance"] = {
	["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "30级时，{object:32383}的{npc:6120}会让你去{area:392}找{npc:6251}。",
	["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "30级时，{object:2101}{object:2164}地下室的{npc:6122}会让你去{area:392}找{npc:6251}。",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "回到 {area:392} 找 {npc:6251}。接受任务后，他会画出召唤法阵，学徒们会在上方引导出一个更大的法阵：留在塔内，等两者都完成。然后对法阵使用 {quest:1804}。地狱猎犬（30级，非精英）会沉默并消耗法力，而且两分钟后就会消失：提前召出虚空行者，开战立刻施加持续伤害技能，让虚空行者扛住。如果你死亡或战斗失败，就放弃 {quest:1795}，再从 {npc:6251} 处重接。保留魔典：{npc:6251} 会收回它。",
	["Back to {npc:6294}"] = "返回{npc:6294}处",
	["Felhunter (Alliance)"] = "地狱猎犬（联盟）",
	["Rods of Channeling"] = "导能魔棒",
	["Rods of Channeling, from the Dragonmaw casters"] = "从龙喉施法者处获取引导魔棒。",
	["Summoned Felhunter"] = "召唤的地狱犬",
	["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "龙喉氏族占据了 {area:1036}，位于 {area:150} 通往 {area:836} 的道路东侧山丘中。只有施法者会掉落魔棒，概率为五分之四：护骨者（27 级，带骷髅宠物）和暗影守卫（28 级）。中央灵魂医者北侧有一条陡峭小路，沿路可绕过大多数战士，进入营地。",
	["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "半人马洞穴入口位于 {area:484} 北边的悬崖上，那是部落城镇，要避开守卫。进去后每个岔路都靠右走，穿过小瀑布旁的水池，打开墙边、大箱子旁的小型深色箱子：大箱子不是目标。只有接了任务才能打开。离开时，身后的半人马会重新刷新。",
	["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "地狱猎犬，对付施法者的恶魔，外加一个用来装灵魂碎片的{item:22244}。",
	["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "那本典籍是一本灰蓝色小书，躺在{area:271}西南面海岸鱼人营地的沙地上，靠近水边。有六七只鱼人守着，水下还潜伏着更多：它们会成群过来，用恐惧控制一只，让虚空行者扛住其他鱼人。走下到水边再点击书本；从山坡上点击会被箱子挡住鼠标。",
	["Warlock"] = "术士",
	["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392}是{zone:1413}海岸的一座中立地精港口：从{area:35}来的船在此停靠。{npc:6251}站在镇子上方的山丘上，工程师小屋后方、他的小塔旁；{npc:6266}和两名侍僧也在。他会派你去{zone:1455}找{npc:6294}。",
	["{item:6931}, from the {quest:1802} on the sand"] = "{item:6931}，来自沙地上的 {quest:1802}",
	["{item:6997}, in the {object:92423}"] = "{item:6997}，在{object:92423}里",
	["{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6294}在{object:32356}的图书馆里。他需要{quest:1758}遗失的两部分：一部分在{area:287}海岸，另一部分在{zone:1441}。",
	["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6294} 会将典籍拼好，并给你 {item:7006}：留着它，{npc:6251} 会连同魔棒一起收走。",
	["{quest:1804}, on the circle"] = "在法阵上使用 {quest:1804}。",
}

G["forever/class/warlock/imp-alliance"] = {
	["Feather Charms"] = "羽毛咒符",
	["Imp (Alliance)"] = "小鬼（联盟）",
	["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "迪菲亚帐篷位于修道院东侧的葡萄园。书很小：就在帐篷入口右侧的地面上，靠近一个蓝色水罐。三名迪菲亚暴徒（3-4 级）守着帐篷；逐个拉出来打，或者走进帐篷，站在他们够不到的位置点击书。书被拾取三分钟后刷新。",
	["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "霜鬃巨魔新兵（3-4级）在{area:77}南方巨魔洞穴的深处，靠近冰池旁的冷酷的格瑞克尼尔：进入洞口后走左侧通道。掉率约为五只出四个咒符，但只有两三名新兵会刷新，因此可能需要等待三分钟的刷新时间。它们会在远处施放寒冰箭；洞口的巨魔幼崽会袭击路过的人。拿到咒符后可以直接用炉石返回：新角色的炉石绑定在{area:132}。",
	["The {object:83763}"] = "{object:83763}",
	["Warlock"] = "术士",
	["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "1-4级的第一个恶魔：小鬼，在你初始地区的术士训练师处获得。",
	["Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole."] = "你的第一封信（完成“剿灭狗头人”后由{npc:197}给予的{item:9576}）会指引你去找{npc:459}，她是{area:24}旁小墓地里的术士训练师。她要你找回一本被迪菲亚偷走的书。",
	["Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms."] = "第一封信（完成“矮人的交易”后，由 {npc:658} 给予的 {item:9577}）会让你去找 {area:77} 建筑楼上的术士训练师 {npc:460}。他需要三个羽毛咒符。",
	["{item:6785}, from the {object:83763}"] = "{item:6785}，来自{object:83763}",
	["{npc:459} (Humans)"] = "{npc:459}（人类）",
	["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "交还任务时，{npc:459} 会教你 {spell:688}：马上召唤，不花钱，还能帮你战斗。",
	["{npc:460} (Gnomes)"] = "{npc:460}（侏儒）",
	["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "交还任务时，{npc:460} 会教你 {spell:688}：马上召唤，不花钱，还能帮你战斗。",
}

G["forever/class/warlock/incubus-alliance"] = {
	["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "达到 20 级后，{zone:1455} 的 {object:32383} 中的术士训练师 {npc:6120} 会让你去找 {zone:1453} 的 {npc:6122}。乘坐 {area:2257} 前往。",
	["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "20 级时，{object:2101} 的 {object:2164} 地窖内的 {npc:6122} 会让你去 {zone:1413} 找 {npc:6244}：联盟要走很远。可从 {area:150} 乘船到塞拉摩，再向西穿过 {zone:1445}；也可以从 {area:35} 乘船到 {area:392}。",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "20级时：魅魔，以及无限服务器特有的夜魔——魅魔的男性孪生恶魔，各附带一个装灵魂碎片的灵魂袋。",
	["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "带着 {quest:1738} 回去找 {npc:6122}。他会给你 {item:6913}：从他身后的楼梯下到地穴，沿最底层的走廊前进，途中左侧的支路楼梯通往有紫色法阵的房间。站在法阵上使用核心。先召出虚空行者，并将魅魔（20级，非精英）留在法阵上，否则守卫可能会杀死她，导致不计数。如果战斗失败，就再次使用核心；保留核心，{npc:6122} 会收回它。",
	["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "把雕像交给黑暗缚灵者加科因，然后在同一个法阵的中央使用{item:190309}，让虚空行者抗住伤害，击败召出的夜魔（20级，非精英；会魅惑你）。保留雕像：要交还给{npc:6122}。",
	["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "奥迪拉兰位于 {zone:1440} 西北部，在 {area:415} 以北、通往 {zone:1439} 的道路沿线。约二十名黑暗深渊教徒占据了大树周围的废墟：沿外墙走，在允许的最远距离点击 {quest:1738}。任务要交还给 {npc:6122}，不是塔卡尔。",
	["Succubus and Incubus (Alliance)"] = "魅魔与夜魔（联盟）",
	["Summoned Incubus"] = "被召唤的男魅魔",
	["Summoned Succubus"] = "召唤的魅魔",
	["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "这所房子独自坐落在 {zone:1440} 西北的树林中，在奥迪拉兰西北、{area:413} 以北很远的地方：与 {quest:1738} 一趟做完。从屋外桌子上取走 {item:190307}，在营火处点燃（自己生的 {object:29784}，或 {area:414} 上塔伦的营火），然后直接返回：{item:190308} 五分钟后就会燃尽，因此在屋旁自己生火最快。没有它，屋内的身影会阻止你。雕像在楼上。",
	["The {item:190309}"] = "{item:190309}",
	["Warlock"] = "术士",
	["the incubus"] = "男魅魔",
	["the succubus"] = "魅魔",
	["{item:190307}, on the table outside"] = "{item:190307}，在外面的桌上",
	["{item:190309}, upstairs"] = "楼上的 {item:190309}。",
	["{item:6913}, on the circle in the crypt"] = "{item:6913}，在墓穴内的法阵上",
	["{npc:185335}, at the circle in the crypt"] = "{npc:185335}，位于墓穴中的法阵旁。",
	["{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both."] = "{npc:6244} 在 {area:378} 东北方不远的岔路口旁，营火边的帐篷处扎营：这里是部落地盘，要从东边进入，避开陶拉祖的守卫。他身旁的 {npc:6247} 会开启 {item:6898} 的任务。塔卡尔提供两条分支：两条都接。",
	["{quest:1717} (Gnomes)"] = "{quest:1717}（侏儒）",
	["{quest:1739}: succubus"] = "{quest:1739}：魅魔",
	["{quest:65603}: incubus"] = "{quest:65603}：梦魇",
}

G["forever/class/warlock/voidwalker-alliance"] = {
	["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "10级时，{zone:1455}的{object:32383}内的术士训练师{npc:6120}会派你去{zone:1453}找{npc:6122}。从{object:171524}搭乘{area:2257}。如果{npc:6120}不提供任务，仍然直接去找{npc:6122}：他依然会提供后续任务。",
	["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "达到 10 级后，{area:87} 狮王之傲旅店地窖中的 {npc:6121}（下楼梯在肉案后面的里屋）会让你去找 {zone:1453} 的 {npc:6122}。",
	["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "返回 {npc:6122} 处。他会给你 {item:6928}。法阵不太好找：沿 {npc:6122} 身后的楼梯向下走；在最底层走廊中途，左侧一段楼梯通往一个房间，房间中央有发光的紫色法阵。站上去并使用项圈。虚空行者（10 级，非精英）在生命值低于 30% 时会变得危险：使用 {spell:14868}、腐蚀术和 {spell:348}，让小鬼攻击它；它靠近时使用恐惧术。若打输了，再次使用项圈。保留项圈：{npc:6122} 会收回它。",
	["Summoned Voidwalker"] = "被召唤的虚空行者",
	["Surena Caledon"] = "苏雷娜·卡莱顿",
	["Voidwalker (Alliance)"] = "虚空行者（联盟）",
	["Warlock"] = "术士",
	["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "10级的坦克恶魔：虚空行者。先取得一名黑暗女巫的项圈，再到{npc:6122}的墓穴中打一场。",
	["{item:6928}, on the circle in the crypt"] = "{item:6928}，在墓穴内的法阵上",
	["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}，狮王之傲旅店地窖。",
	["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881}（9级）在艾尔文森林东南部 {area:62} 的农舍内，靠近通往赤脊山的道路。{npc:473}（10级）和一名战士在她身旁，会一起参战；摩根会使用凿击，并攻击你的小鬼，因此要持续恐惧他。先对 {npc:881} 施加持续伤害，恐惧其余敌人，并在解决他们之前拾取她的项圈：即使随后死亡，项圈也仍归你。她会在远处施放火球，死亡三分钟后刷新。必须先接任务再杀她，否则不会掉落项圈。",
	["{quest:1685} (Humans)"] = "{quest:1685}（人类）",
	["{quest:1715} (Gnomes)"] = "{quest:1715}（侏儒）",
	["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715} 指的是 {object:2101} 的酒馆；{npc:6122} 在酒馆的地窖里，从店内楼梯下去即可。",
}

G["forever/class/warrior/fire-hardened-armor"] = {
	["A hauberk at 28, a coif, leggings and gauntlets from three smiths, and a shield on the way."] = "28级的锁甲，三位铁匠分别给出罩帽、护腿和护手，途中还有一面盾牌。",
	["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "20级时，{zone:1455}的战士训练师{npc:5113}会让你去赤脊山找{quest:1698}。",
	["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "达到 20 级后，{object:2100} 战士训练师建筑内、{npc:5480} 旁的 {npc:5479} 会让你前往赤脊山处理 {quest:1698}。",
	["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "20级时，{zone:1457}的战士训练师{npc:7315}会让你去赤脊山找{quest:1698}。",
	["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "返回{object:28027}的{npc:5413}处领取锁甲。他接着会让你去找自己种族的铁匠；另外两位铁匠提供的装备部件也可以取得：直接与他们交谈即可。",
	["Charred and Galvanized Horns"] = "烧焦的奇美拉角和{item:6840}",
	["Enter the {area:98} and come back"] = "进入{area:98}后返回",
	["Fire Hardened Armor"] = "淬火护甲",
	["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "搭乘{area:2257}从{zone:1453}前往{zone:1455}。侏儒铁匠{quest:1704}在{object:171524}工作，靠近工程学训练师。他需要20个{item:6848}。",
	["Roogug in {area:1717}"] = "{area:1717}中的鲁古格",
	["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "鲁古格是一只精英野猪人（28级），在{zone:1413}最南端的地下城{area:1717}里；这是五人地下城：需要五人小队，他的守卫也会一起参战。进去后在第一个岔路口向左，过树根桥，经过空的大锅：他就在右侧尽头，沿途大约有十只精英。他会施放{spell:403}并召唤地行者。必定掉落药瓶。",
	["Scorched Spider Fangs"] = "{item:6838}",
	["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. {npc:6170} (level 32, not elite) carries the {item:6845} (also four in five): he walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. {npc:6170} and the Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "{zone:1431} 的 {area:42} 南边和西边分布着夜行狼人（黑暗奔跑者、邪齿狼人、暗影编织者、狼人和堕落狼人，26-31 级），约每五次击杀有四次掉落 {quest:1705}。{npc:6170}（32 级，非精英）携带 {item:6845}（掉率同样约五分之四）：他在 {area:42} 东南的 {area:2161} 矿洞内与洞口之间巡逻，可在入口等候，把他引到外面。{npc:6170} 和堕落狼人会下毒和嚎叫；邪齿狼人会造成 {spell:3427}。",
	["The chimaeras live south-west of {area:460} in the {area:465}: you need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "奇美拉生活在{area:460}西南方的{area:465}：你需要从奇美拉雏兽（25-27级）和奇美拉幼崽（23-25级）身上取得12个烧焦的奇美拉角，掉率为五只出四个；还需要从{npc:6167}（28级，体型最大的那只）身上取得{item:6840}，掉率同样为五只出四个。那里只有三只奇美拉雏兽、两只幼崽和一只雌兽，每只五分钟刷新，因此要做好等待的准备。奇美拉雏兽和雌兽会喷吐{spell:3396}，幼崽会施放{spell:403}。联盟：飞往{area:467}后向南走。",
	["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once."] = "蛋壳散落在 {zone:1441} 西部 {area:482} 的双足飞龙巢穴下方地面，位置在峡谷更深处。总共只有九个，每个拾取后三分钟刷新，因此需要等待；那里一些看起来像蛋壳的东西无法拾取。风巢双足飞龙（28—31级）守护着蛋壳，有时会同时引来好几只。",
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and an Elixir of Water Breathing removes the risk."] = "{quest:1708}生长在{area:150}正南的海底，鱼人小屋和一条破船旁：那里有八株，港口东南有两株，各3分钟刷新，所以要等刷新凑够20个。鱼人在水下会用网困住你：留意呼吸条，一瓶水下呼吸药剂就能消除风险。",
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and an {item:5996} removes the risk."] = "{quest:1708}生长在{area:150}正南的海底，鱼人小屋和一条破船旁：那里有八株，港口东南有两株，各3分钟刷新，所以要等刷新凑够20个。鱼人在水下会用网困住你：留意呼吸条，一瓶{item:5996}就能消除风险。",
	["Warrior"] = "战士",
	["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "你有一小时，且{npc:6166}的{spell:8553}会让你醉上8-10分钟。向西北跑进{area:98}，紧贴崖壁避开大部分豺狼人群，深入至第一个岔路口即可；然后回到{npc:6166}处（可从山脊跳下到{area:69}）。死亡后释放灵魂会使任务失败：放弃任务，{npc:6166}会再次提供。",
	["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang. They poison; back in 5 minutes."] = "需要50颗毒牙。吸血捕猎者和洞穴捕猎者（21-22级）在{zone:1437}中部、{area:836}以北爬行；每只必掉一颗毒牙。它们会施毒；五分钟后刷新。",
	["{item:6839}, from the young chimaeras"] = "{item:6839}，由奇美拉幼崽掉落",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}，来自{npc:6167}",
	["{item:6841}, from Roogug"] = "{item:6841}，来自鲁古格",
	["{item:6845}, from {npc:6170}"] = "{item:6845}，由{npc:6170}掉落",
	["{item:6848}, from {quest:1708}"] = "{item:6848}，来自{quest:1708}",
	["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416}在{object:28027}西北部经营武器店，离{npc:5413}只有几步路。他需要20个{quest:1705}和{item:6845}。",
	["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest, with {item:6842} listing what it needs."] = "{npc:5413}在暴风城矮人区工作。他会收下{item:6843}（弄丢了？放弃任务，{npc:6166}会再给一个），并给你盾牌{item:6970}；{quest:1701}是28级任务，所需材料列在{item:6842}上。",
	["{quest:1698} sits in the inn at {area:69}. His test is timed: before you take it, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} 坐在 {area:69} 的旅店内。他的测试有时间限制：接任务前，先清掉通往 {area:69} 西北山中 {area:98} 的小路上的赤脊山豺狼人，包括洞口旁石头上的两只（从石头右侧爬上去）。",
	["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703} 在 {zone:1457} 的 {area:1660} 南侧工作。他需要20份 {quest:1710}。",
	["{quest:1705}, from the Nightbane worgen"] = "从夜行狼人处获取 {quest:1705}。",
}

G["forever/class/warrior/haggards-weapons"] = {
	["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "10 级时，{area:131} 的战士训练师 {npc:1229} 会让你去 {zone:1455} 找 {quest:1679}。任何联盟战士都可以选择三条路线中的一条，但不能同时选两条：如果 10 级时本来就在 {zone:1453}，{npc:5480} 的 {quest:1638} 能最快学会姿态（在酒馆打一架），之后还能拿到一件哈迦德难民的武器。",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "10级时，{npc:252377}与训练师们站在{area:16638}西门旁。教徒{npc:257196}在{area:16629}持有她家的盾牌。",
	["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "10 级时，{area:186} 的战士训练师 {npc:3598}，或在 {area:186} 西边道路巡逻的 {npc:2151}，会让你去 {zone:1457} 的 {area:1660} 找 {quest:1684}。任何联盟战士都可以选择三条路线中的一条，但不能同时选两条：如果 10 级时本来就在 {zone:1453}，做 {npc:5480} 的 {quest:1638}，在酒馆打一架就能学会相同的姿态。",
	["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "10级时，{area:87}旅店旁的战士训练师{npc:913}会让你去找{zone:1453}的{npc:6089}；{zone:1453}的{object:2100}里的战士训练师{npc:5480}也提供此任务。",
	["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "回到{area:1660}：{npc:4088}会给你{item:6812}；{npc:6142}在同一平台另一头的南侧工作，很容易错过。",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "返回 {area:16638} 的 {npc:252377} 处。她会教你 {spell:71}，并给你一面配套使用的盾牌 {item:275290}。等你抵达 {zone:1453} 后，下方 {npc:6090} 的任务路线仍可让你获取一把武器。",
	["Back to {npc:294}"] = "回到{npc:294}处",
	["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "返回{npc:6114}处学习{spell:71}，然后去{zone:1455}中央的{object:32372}找{quest:1680}。",
	["Bartleby"] = "巴特比",
	["Elunite under {area:442}"] = "{area:442}水下的月神矿石",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "从 {area:16638} 向西北前往 {area:16629}。{npc:257196} 站在神殿入口通路的西侧，周围是教团的守护者、唤灵者和剑圣：先逐个拉出来清掉，再对付他。他会掉落 {item:263993}。",
	["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "从{area:702}乘船前往{area:442}。沉船在{area:442}南侧码头正南方的水下，米奈希尔来的船就停靠在这个码头。打开沉船周围海底、巨大沉没海龟旁、靠海滩方向及码头下的月神矿石箱，直到收集8块；每箱都有矿石，3-5分钟刷新。灰色的{npc:6133}（11级）在沉船中部附近漂浮，必定掉落勋章：看见时就选中它，方便上浮换气后再找到。留意呼吸时间；蛇颈龙可能加入战斗。",
	["Warrior"] = "战士",
	["Zaal Stormshield"] = "扎尔·风盾",
	["from {npc:6093}"] = "由 {npc:6093} 掉落",
	["{item:263993}, from {npc:257196}"] = "{item:263993}，由{npc:257196}掉落",
	["{item:6782}, from {object:85563}"] = "{item:6782}，来自 {object:85563}",
	["{item:6800}, from {object:85562}"] = "{item:6800}，来自 {object:85562}",
	["{item:6808}, from Crates of Elunite"] = "{item:6808}，从艾鲁尼特矿石箱中获得",
	["{item:6809}, from the {npc:6133}"] = "{item:6809}，来自{npc:6133}",
	["{npc:252377} in {area:16638}"] = "{area:16638}的{npc:252377}",
	["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "{npc:294} 的庄园位于艾尔文森林东部 {area:88} 的东南边缘，在一条不与主路相连的短路尽头。",
	["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089} 和 {npc:6090} 都在 {object:2100} 的猪与哨声旅店中；{npc:6090} 是吧台最里端的酒鬼。{npc:6090}（10 级）的伤害高于同级怪物，因此要满血开战；他在生命值低时会认输，不会死亡。若他打赢了，会消失约三分钟：保留任务，等他回来后再交谈。若矮人、侏儒或暗夜精灵从 {npc:5480} 处接受了 {quest:1638}，而非走本族任务路线，从这里起会被引导经过 {zone:1453}。",
	["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093}（11级）在艾尔文森林最东南方扎营。他身边有一名守卫，营地周围散布着迪菲亚成员和狼（偶尔还有一名较稀有的守卫）：逐个清理，再击杀杰克。他必定掉落 {item:6783}；打开他身旁货箱中的 {object:85563}，取得 {item:6782}。杰克死亡3分钟后刷新，箱子开启1分钟后刷新。",
	["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678}（11级，独自一人的巨魔）在{area:135}南方山丘上的小屋等候，小屋靠近山脉，位于一段短坡的顶端，周围没有其他巨魔；{area:135}前方那间小屋不是。他使用{spell:71}作战，还会破甲；{spell:6343}能减慢他的攻击速度。他的头颅必定掉落；死后约八分钟刷新。",
	["{quest:1679} in {zone:1455}"] = "{zone:1455} 的 {quest:1679}",
	["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679} 位于 {object:32359} 的 {object:32390} 内。",
	["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681} 位于 {zone:1426} 东部、{area:212} 南侧下方。沿途有黑铁间谍（8-10 级），间距足够逐个引来击杀。{object:85562} 在最南边房子的地下室里；{npc:6124}（11 级）站在旁边，看到你就会冲过来。箱子里必定有矿石，打开后 15 分钟重新补满。",
	["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683}（10级，萨特）站在{area:186}西边山坡上一处隐蔽的月亮井旁。小路很难发现：起点在一个瘤背熊怪营地后方，沿着有灯柱的之字形山路向上。下面的熊怪可能成群出现。他的角必定掉落；死后五分钟刷新。",
	["{quest:1684} in {zone:1457}"] = "{zone:1457} 的 {quest:1684}",
	["{quest:1684} stands on the {area:1660}."] = "{quest:1684} 站在 {area:1660}。",
	["{spell:71} and a Weapon (Alliance)"] = "{spell:71}和一把武器（联盟）",
	["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "10级获得{spell:71}，并从{zone:1453}、{zone:1455}或{zone:1457}获得一把自选的单手武器。",
}

G["forever/collectibles/mounts/alliance/black-war-mounts"] = {
	["Black War Mounts"] = "黑色战斗坐骑",
	["PvP rank 11"] = "PvP军衔11级",
	["{item:18243}, {spell:10907}, 100g"] = "{item:18243}，{spell:10907}，100 金",
	["{item:18244}, {spell:826}, 100g"] = "{item:18244}，{spell:826}，100 金",
	["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783}在{zone:1453}的{object:2100}、{area:2918}旁出售坐骑，就在其他荣誉军需官旁边。无限客户端标价每只100金币。每种还需要对应的骑术：人类骑战马，暗夜精灵骑虎，侏儒骑作战机械陆行鸟，矮人骑山羊。天裔或选择其他种族坐骑的玩家，必须先向对应训练师学习该骑术（需对应种族主城声望达到崇拜）。",
	["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}，{spell:824}，100金币",
	["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "{spell:1299382}来自战场、PvP任务和赛季每周任务，每周有获取上限；达到统帅（军衔11级）可解锁黑色作战坐骑。角色界面的玩家对战分页会显示你的军衔和可购买的物品。要运用{skill:762}全速骑乘，需要中级{skill:762}（60级）。Polestar无法读取你的军衔，因此此步骤会等待你达到60级并学会中级{skill:762}。",
	["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}，{spell:828}，100金币",
}

G["forever/collectibles/mounts/alliance/horse"] = {
	["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "所有联盟种族都能购买这些马，但骑乘还需要{spell:824}，只有人类学习{skill:762}时会同时获得。其他种族需先将{faction:72}声望提升至崇拜，再找{npc:4732}学习（详见暴风城声望指南）。在那之前，不要为这个角色买马。",
	["Horse"] = "马",
	["Learn to ride"] = "学习骑术",
	["Pick a colour"] = "挑选颜色",
