G["forever/collectibles/mounts/alliance/swift-ram"] = {
	["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "任何联盟种族都能购买这些山羊，但骑乘还需要 {spell:826}，只有矮人在学习 {skill:762} 时会同时学到。其他种族需要将 {faction:47} 声望提升至崇拜，才能向 {npc:4772} 学习（铁炉堡声望指南会提供路线）。在此之前，不要为这个角色购买山羊。",
	["Journeyman {skill:762}"] = "中级{skill:762}",
	["Pick a colour"] = "选择颜色",
	["Swift Ram"] = "迅捷山羊",
	["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 60 {npc:4772} teaches Journeyman {skill:762} to Dwarves for 1,000g (10% less at Honored with {faction:47}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift ram costs 200g here."] = "{area:803} 位于 {area:131} 东面、通往 {zone:1432} 的道路上；{npc:4772} 站在 {npc:1261} 的山羊旁。60级时，{npc:4772} 以1,000金币向矮人教授中级 {skill:762}（{faction:47} 达到尊敬可优惠10%）；暴雪称会附赠一只坐骑。其他种族在本族的骑术训练师处学习。这里每只迅捷山羊售价200金币。",
	["{item:18785}, 200g"] = "{item:18785}，200金",
	["{item:18786}, 200g"] = "{item:18786}，200金",
	["{item:18787}, 200g"] = "{item:18787}，200金",
	["{npc:1261} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:1261}出售其他颜色（无限客户端中每匹200金）。想要哪个就买哪个；如果喜欢已获得的坐骑，也可以不买。",
	["{npc:4772}, riding trainer"] = "{npc:4772}，骑术训练师",
	["{spell:826} for other races"] = "其他种族学习{spell:826}",
}

G["forever/collectibles/mounts/alliance/swift-saber"] = {
	["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "联盟任何种族都能购买这些夜刃豹，但骑乘还需要 {spell:828}，只有暗夜精灵学习 {skill:762} 时会一并获得。其他种族在 {faction:69} 声望达到崇拜后，可向 {npc:4753} 学习（“达纳苏斯声望”指南中有具体方法）。达到之前，不要给这个角色购买夜刃豹。",
	["Journeyman {skill:762}"] = "中级{skill:762}",
	["Pick a colour"] = "挑选颜色",
	["Swift Saber"] = "迅捷豹",
	["{item:18766}, 200g"] = "{item:18766}，200金",
	["{item:18767}, 200g"] = "{item:18767}，200金",
	["{item:18902}, 200g"] = "{item:18902}，200金",
	["{npc:4730} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:4730}出售其他颜色（无限 客户端中每只200金）。想要哪只就买哪只；如果喜欢送你的那只，也可以不买。",
	["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 60 {npc:4753} teaches Journeyman {skill:762} to Night Elves for 1,000g (10% less at Honored with {faction:69}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift saber costs 200g here."] = "{npc:4753} 和 {npc:4730} 的夜刃豹位于 {faction:69} 境内 {area:1658} 的骑术训练场。60级时，{npc:4753} 以1,000金币向暗夜精灵教授中级 {skill:762}（{faction:69} 达到尊敬可优惠10%）；暴雪称会附赠一只坐骑。其他种族在本族的骑术训练师处学习。这里每只迅捷夜刃豹售价200金币。",
	["{npc:4753}, riding trainer"] = "{npc:4753}，骑术训练师",
	["{spell:828} for other races"] = "其他种族学习{spell:828}",
}

G["forever/collectibles/mounts/alliance/winterspring-frostsaber"] = {
	["The Forever client lists it at 200g and level 60. It runs at full speed yet needs no riding training at all, only Honored with the {faction:589}, so you can skip the 1,000g Journeyman Riding if this is your fast mount."] = "无限客户端列出的售价为 200 金币，要求 60 级。它的速度达到最高档，却完全不需要学习骑术，只需 {faction:589} 声望尊敬；如果把它作为高速坐骑，就可以省下 1,000 金币的中级骑术费用。",
	["{npc:10618} stands on top of {area:2241} in the far north of {zone:1452}. Only the Alliance can earn the {faction:589}' favour, from level 58: three repeatable quests worth 50 each, about 840 turn-ins from Neutral to Exalted. Frostsaber Provisions is open from the start, Winterfall Intrusion from halfway through Neutral and Rampaging Giants from Honored. The Wintersaber Trainers Reputation guide takes you through it."] = "{npc:10618} 站在 {zone:1452} 最北端的 {area:2241} 顶上。只有联盟能从 58 级起提升 {faction:589} 声望：三个可重复任务，每次奖励 50 点，从中立到崇拜大约要交还 840 次。“霜刃豹的食物”一开始就能接，“冬泉熊怪的侵扰”在中立进度过半后开放，“狂暴的巨人”在尊敬后开放。“冬刃豹训练师声望”指南会带你完成。",
	["{npc:10618}, 200g"] = "{npc:10618}，200金",
}

G["forever/collectibles/pets/chicken-egg"] = {
	["Buy one {item:11109} (25 copper) from {npc:233} at his farm first: it is not a quest item, and the chicken stays friendly only for a short while."] = "先在{npc:233}的农场向他买一个{item:11109}（25铜）：它不是任务物品，而且小鸡只会短暂保持友好。",
	["Loot the {object:161513} the chicken lays"] = "拾取小鸡下的{object:161513}",
	["Target one of the chickens around Saldean's farm and type /chicken at it, again and again, until it offers {quest:3861}; this can take several minutes. Then /cheer at a chicken until it turns friendly (green) and hand in the feed; right-clicking a chicken before it is friendly attacks it. The chicken lays an egg on the ground: loot it for your {item:11110}."] = "选中萨丁农场周围的一只鸡，反复对它输入 /chicken，直到它提供 {quest:3861}；这可能要花几分钟。然后对一只鸡使用 /cheer，直到它变为友善（绿色），再交还饲料；鸡还未变为友善时，右键点击会攻击它。鸡会在地上下一枚蛋：拾取即可获得你的 {item:11110}。",
}

