G["forever/reputation/darnassus"] = {
	["About 3,700 {faction:69} reputation from low-level quests in {zone:1438} and {zone:1439} (in Classic, a fifth of it at 60)"] = "{zone:1438}和{zone:1439}的低等级任务约给3,700点{faction:69}声望（经典版中60级时只有五分之一）",
	["Black Broodling"] = "黑色雏龙",
	["Black Dragonspawn"] = "黑色龙人",
	["Black Drake"] = "黑色幼龙",
	["Black Wyrmkin"] = "黑色龙兽",
	["Blackwood Pathfinder"] = "黑木探路者",
	["Blackwood Windtalker"] = "黑木语风者",
	["Cloth, {item:11040} and the {zone:1438} and {zone:1439} hubs: the quests pay most while you level."] = "布料、{item:11040}以及{zone:1438}和{zone:1439}的任务据点：升级期间做任务给的声望最多。",
	["Darnassus Reputation"] = "达纳苏斯声望",
	["Den Mother"] = "母熊",
	["Dig {quest:3764} from the dirt mounds all over the crater; most of the crater's beasts and the Gorishi silithids drop it too, about one kill in three. Take far more than 20: every pouch use takes 2, about 18 for each 10 {item:11040}."] = "从环形山各处的土堆挖取{quest:3764}；环形山大部分野兽和格里什异种虫也会掉落，概率约三只出一个。不要只拿20个，要多拿很多：每次使用小袋消耗2个，每获取10个{item:11040}约消耗18个。",
	["Every 10 {item:11040}: 50 reputation at {npc:4217}. Keep the pouch and buy seeds as you go. It is slow: about 9 casings, 90 minutes of pouch waits, 18 {quest:3764} and 9 seed packets for each hand-in, a little over 30 reputation an hour, so run it beside the {item:14047}. {npc:7879} at {area:1116} in {zone:1444} takes {item:11040} at the same rate, 25 for 5, after his own quest."] = "每10份 {item:11040} 可在 {npc:4217} 处换50声望。保留种子袋，沿途购买种子。进度很慢：每次交还大约需要9份壳、90分钟的种子袋等待时间、18次 {quest:3764} 和9包种子，每小时仅略高于30声望，所以应与收集 {item:14047} 同时进行。{zone:1444} 的 {area:1116} 内的 {npc:7879} 在完成自己的任务后，也以相同比例收取 {item:11040}，每5份换25声望。",
	["Exalted with {faction:69}: in Classic, other races may buy the nightsabers"] = "{faction:69}崇拜：在经典版中，其他种族可购买夜刃豹",
	["Gnarlpine Ambusher"] = "瘤背伏击者",
	["Gnarlpine Mystic"] = "瘤背秘法师",
	["Honored: in Classic Darnassus's vendors take 10% off for you, Lelanai's nightsabers (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}."] = "尊敬：经典怀旧服中，达纳苏斯商人会给你 10% 折扣，包括莱兰奈出售的夜刃豹（20 金币，迅捷型 200 金币）；无限尚未确定，指南网站报告为友善 5%，逐步提高到崇拜 20%。尊敬到崇敬需要 12,000 点声望：交还 240 次，共 4,800 个 {item:14047}。",
	["Mangy Nightsaber"] = "癞皮夜刃豹",
	["Optional: the Night Elf start glade in north-east {zone:1438}, about 1,050 reputation (210 at a fifth) in 30 minutes at 60. The givers stand around {area:256}, the great tree. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{zone:1438}东北的暗夜精灵起始林间空地，60级时30分钟约1,050点声望（按五分之一算是210点）。发布任务的NPC站在大树{area:256}周围。经典版中，比你低6级以上的任务收益会减少（60级时为五分之一）；一份无限测试服报告称它们仍按全额给。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些枢纽。跳过这一步就等于跳过该枢纽。",
	["Optional: the village on the road to {faction:69}, about 1,250 reputation (250 at a fifth) in 45 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：通往{faction:69}的路上的村庄，60级时45分钟约1,250点声望（按五分之一算是250点）。经典版中，比你低6级以上的任务收益会减少（60级时为五分之一）；一份无限测试服报告称它们仍按全额给。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些枢纽。跳过这一步就等于跳过该枢纽。",
	["Optional: {area:442} in {zone:1439}, a boat trip from {area:702}, about 1,400 reputation (280 at a fifth) in an hour at 60. The givers stand along the town's street and pier. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{zone:1439}的{area:442}，从{area:702}坐船可达，60级时一小时约1,400点声望（按五分之一算是280点）。发布任务的NPC站在镇上的街道和码头沿线。经典版中，比你低6级以上的任务收益会减少（60级时为五分之一）；一份无限测试服报告称它们仍按全额给。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些枢纽。跳过这一步就等于跳过该枢纽。",
	["Rabid Thistle Bear"] = "狂暴蓟熊",
	["Reputation · Cities"] = "声望·主城",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, Lelanai at the {area:1658} in {faction:69} sells her nightsabers to other races in Classic; the Saber and Swift Saber guides cover them."] = "崇敬到崇拜需要21,000声望：交还420次，共8,400个{item:14047}。经典旧世中，达到崇拜后，{faction:69}的{area:1658}里的莱兰奈会向其他种族出售夜刃豹；“豹”和“迅捷豹”指南有相应说明。",
	["The Blackwood furbolgs camp south of town; the grells of {quest:955}, east of town, drop the earrings; the sea turtle remains lie on the beach west of town."] = "黑木熊怪在镇子南面扎营；镇子东面的{quest:955}小劣魔会掉落耳环；海龟遗骸在镇子西面的沙滩上。",
	["The four relics of Wakening lie in the {area:262}, south-west of {area:186}; Ferocitas and the Gnarlpine Mystics camp east of the village."] = "四件唤醒遗物位于 {area:186} 西南的 {area:262}；菲罗斯塔和瘤背秘法师驻扎在村落东边。",
	["The furbolg camp south of town counts for How Big a Threat; the Rabid Thistle Bears roam the woods south of town; the Highborne ghosts of the Ruins of Ameth'Aran, south-east of town, carry the relics, and Anaya's ghost walks there too; the bones lie on the beach south of town; the mushrooms grow in the {area:445} cave to the north-east."] = "镇子南边的熊怪营地可完成 熊怪的威胁；狂暴蓟熊在镇子南边的森林中游荡；镇子东南方亚米萨兰废墟中的上层精灵幽灵带着遗物，安娜雅的幽灵也在那里走动；骸骨在镇子南边的海滩上；蘑菇长在东北方 {area:445} 的洞穴里。",
	["The nightsabers and boars roam the glade; the grells around {area:256} drop the {item:3297}; the totems stand in the furbolg camp north-west of the tree; the Webwood spiders live in the cave north of the glade. {npc:8584} waits outside that cave."] = "夜刃豹和野猪在林间空地游荡；{area:256} 周围的劣魔会掉落 {item:3297}；图腾位于大树西北方的熊怪营地；树林北侧洞穴中有树林蜘蛛。{npc:8584} 在那座洞穴外等待。",
	["The timberlings by the lake drop seeds and sprouts; the Gnarlpine Ambushers lurk on the road west to {faction:69}; {npc:2038} waits deep in {area:258}, north-west of the village; the dreamcatcher lies in the furbolg camp east of the village, by {npc:2107}; the Nightsabers west of the village carry the pelts."] = "湖边的林精会掉落种子和新芽；瘤背伏击者潜伏在向西通往 {faction:69} 的路上；{npc:2038} 在村庄西北方 {area:258} 的深处等候；捕梦网在村庄东边、{npc:2107} 旁的熊怪营地里；村庄西边的夜刃豹带着所需毛皮。",
	["The {item:5338} drops from the satyrs of {quest:956}; destroy the seal at the flame there. The {npc:6788} lairs north-east of {quest:956}; the Moonstalker Sires and Matriarchs roam the south of {zone:1439}."] = "{item:5338} 由 {quest:956} 的萨特掉落；在那里的火焰处摧毁封印。{npc:6788} 栖息在 {quest:956} 东北；月夜雄虎和月夜雌虎则在 {zone:1439} 南部游荡。",
	["The {quest:917} lies at the back of the spider cave; the mushrooms grow by the trees, the lilies by the pools, and the {item:10640} drops from the Webwood Lurkers."] = "{quest:917} 在蜘蛛洞穴深处；蘑菇长在树旁，百合长在水池旁，{item:10640} 由树林潜伏者掉落。",
	["Thistle Boar"] = "蓟野猪",
	["Ursal the Mauler"] = "重击者乌尔萨",
	["Young Nightsaber"] = "年幼的夜刃豹",
	["Young Thistle Boar"] = "年幼的蓟野猪",
	["the blue aura in the ruins of {quest:954}"] = "{quest:954} 废墟中的蓝色光环",
	["the seal at the ancient flame"] = "远古火焰处的封印。",
	["{area:186}: first hand-in"] = "{area:186}：首次交还",
	["{area:186}: the relics and Ferocitas"] = "{area:186}：遗物和菲罗斯。",
	["{area:186}: the woods around the village"] = "{area:186}：村庄周围的林地。",
	["{area:186}: {npc:2080} and the lake"] = "{area:186}：{npc:2080} 和湖泊。",
	["{area:188}: first hand-in"] = "{area:188}：首次交还",
	["{area:188}: last hand-in"] = "{area:188}：最后一次交任务",
	["{area:188}: the egg and the antidote"] = "{area:188}：卵与解毒剂",
	["{area:188}: the glade and the spider den"] = "{area:188}：林地与蜘蛛巢穴",
	["{area:442}: first hand-in"] = "{area:442}：首次交还",
	["{area:442}: second hand-in"] = "{area:442}：第二次交还",
	["{area:442}: the coast and the woods"] = "{area:442}：海岸和树林",
	["{area:442}: the furbolgs, the bears and the grells"] = "{area:442}：熊怪、熊和小劣魔",
	["{area:442}: the seal, the {npc:6788} and the pelts"] = "{area:442}：封印、{npc:6788} 和毛皮",
	["{item:11040} (optional)"] = "{item:11040}（可选）",
	["{item:11040}: grow it here and open the casings"] = "{item:11040}：在这里种植，并打开外壳",
	["{item:14047} drops from humanoids level 50 and up: the Deadwood furbolgs of {zone:1448}, the Winterfall furbolgs of {zone:1452}, the Scourge cultists of the Plaguelands. Keep any {item:14047} past the first 60 for {quest:7801}."] = "{item:14047} 由50级及以上人型生物掉落：{zone:1448} 的死木熊怪、{zone:1452} 的冬泉熊怪，以及瘟疫之地的天灾教徒。最初60块之外的 {item:14047} 请保留，用于 {quest:7801}。",
	["{item:2592}: furbolgs, satyrs and naga in {zone:1439} and {zone:1440}"] = "{item:2592}：来自 {zone:1439} 和 {zone:1440} 的熊怪、萨特与纳迦。",
	["{item:4306} drops from humanoids level 23 to 40: the satyrs and furbolgs of {zone:1440}, the Thistlefur and Foulweald camps, the Grimtotem of Stonetalon."] = "{item:4306}由23至40级人型生物掉落：{zone:1440}的萨特和熊怪、蓟皮和污林营地，以及石爪山脉的恐怖图腾成员。",
	["{item:4338} drops from humanoids level 35 to 50: the Hatecrest naga and Gordunni ogres of {zone:1444}, the Dunemaul ogres of {zone:1446}."] = "{item:4338} 由35至50级人型生物掉落：{zone:1444} 的憎世纳迦和戈杜尼食人魔，以及 {zone:1446} 的砂槌食人魔。",
	["{item:8050}, from {quest:2459}"] = "{item:8050}，来自{quest:2459}",
	["{npc:14725} takes cloth for {faction:69}; he stands in the {area:1659}, in the north-east of {faction:69}, by the tailors. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7801} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the {area:1662} is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1438} (levels 1-12), {zone:1439} (11-20) and {zone:1440} (18-30) while you level through them. After the donations come {quest:4183} in the {zone:1428} and {item:11040}, a second repeatable turn-in; then the optional hubs, best rate first: {area:188} (about 35 a minute at full value), {area:186} (28), {area:442} (23). Every {faction:69} gain also gives a quarter as much to {zone:1453}, {zone:1455} and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14725} 为 {faction:69} 接收布料；他站在 {faction:69} 东北的 {area:1659}，靠近裁缝。毛料、丝绸、魔纹布和 {item:14047} 各首次捐献 60 个，都能获得一次 150 点声望；完成 {item:14047} 的首次捐献后，可无限重复交还 {quest:7801}，每 20 个 {item:14047} 换 50 点。{area:1662} 的拍卖行是最快的布料来源。经典怀旧服中，任务最多比你低 5 级时仍给予完整声望，所以升级经过 {zone:1438}（1-12 级）、{zone:1439}（11-20 级）和 {zone:1440}（18-30 级）时就做完当地任务。捐献之后是 {zone:1428} 的 {quest:4183} 和另一项可重复交还的 {item:11040}；之后是可选任务点，按效率从高到低为：{area:188}（完整奖励时约每分钟 35 点）、{area:186}（28 点）、{area:442}（23 点）。除 1-10 级起始地区的任务外，每次获得 {faction:69} 声望，还会同时给 {zone:1453}、{zone:1455} 和诺莫瑞根流亡者各增加其四分之一的声望。传承天赋“外交家”使每次获取量最多额外提高 10%。",
	["{npc:14725}, the cloth quartermaster"] = "布料军需官{npc:14725}",
	["{npc:2080} tends his garden on the south-east shore of {area:259}; {npc:2107} stands upstairs in a house in {area:260}, east of {area:186}: go up inside, the arrow cannot tell the floors apart."] = "{npc:2080}在{area:259}东南岸照料他的花园；{npc:2107}在{area:186}东边{area:260}一座房子的楼上：从屋内上楼，箭头无法区分楼层。",
	["{npc:344} waits in the town hall of {area:69}; his next quest takes you to {object:2117} (the {zone:1453} guide follows it). Other {faction:69} quests at this level, for when you pass by: {npc:7916} in {area:702} has a wildkin chain into {zone:1452} (325 in all, with Ranshalla's escort), Arei's escort in {zone:1448} pays 150 after the {area:2479}'s chain, {npc:10739} at the {area:202} in the {zone:1422} 100 for the {item:12663}, and Put Her Down in Upper Blackrock Spire 100 with a group."] = "{npc:344} 在 {area:69} 的市政厅等你；他的下一个任务会让你前往 {object:2117}（{zone:1453} 指南会继续跟进）。此等级段沿途可做的其他 {faction:69} 任务：{area:702} 的 {npc:7916} 提供通往 {zone:1452} 的枭兽任务链（连同兰莎尔拉的护送共 325 点）；完成 {area:2479} 的任务链后，{zone:1448} 的埃雷护送任务提供 150 点；{zone:1422} 的 {area:202} 中的 {npc:10739} 收取 {item:12663}，提供 100 点；黑石塔上层的“座狼之源”组队完成可获得 100 点。",
	["{npc:4217}: {quest:3803}, +50"] = "{npc:4217}：{quest:3803}，+50",
	["{npc:8584}, outside the spider cave"] = "{npc:8584}，在蜘蛛洞外",
	["{npc:9047}, beside Fandral in the {area:1658}, takes the soil. {npc:4217} sells the {item:11020} and Packets of Tharlendris Seeds. With a seed packet and 2 {quest:3764} in your bags, use the pouch to grow an {item:11024} and open it: about one casing in three holds {item:11040} (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things."] = "{area:1658} 的范达尔身边，{npc:9047} 会收下泥土。{npc:4217} 出售 {item:11020} 和萨伦迪斯种子包。背包里带着一包种子和 2 个 {quest:3764} 时，使用种植袋长出 {item:11024}，再打开：约三分之一的果壳里有 {item:11040}（1 至 5 个），其余是其他草药。种植袋每 10 分钟能用一次，所以做其他事情时，冷却一好就用。",
	["{npc:9562} at {area:2418}, in the south-east of the {zone:1428}, starts {quest:4183}: 175 {faction:69} reputation for two quests (level 54: in Classic 140 at 60), and the chain goes on to {object:2117} for 175 {zone:1453}. The Black Broodlings and the {npc:7044} live on the slopes north of the Vigil; the {npc:7040} and {npc:7041} west of it, in the middle of the zone."] = "{zone:1428}东南部{area:2418}的{npc:9562}提供{quest:4183}：两个任务共175点{faction:69}声望（任务54级：经典旧世中60级时为140），后续任务链会前往{object:2117}，奖励175点{zone:1453}声望。黑色小龙和{npc:7044}在岗哨北面的山坡活动；{npc:7040}和{npc:7041}在岗哨以西、地区中央。",
	["{quest:3763}, +10"] = "{quest:3763}，+10",
	["{quest:3764}, +100"] = "{quest:3764}，+100",
	["{quest:3781}, +10"] = "{quest:3781}，+10",
	["{quest:3781}, +100"] = "{quest:3781}，+100",
	["{quest:3803} takes 10 {item:11040} for 50, as often as you like, and pays in full at 60. The chain before it is level 50 (in Classic a fifth at 60): 220 at full. {npc:6735} sends you to {npc:3516} in the {area:1658}; he wants 20 {quest:3764}. (The innkeepers of {zone:1453} and {zone:1455} give the same start.)"] = "{quest:3803}每10个{item:11040}换50点，想做多少次都行，60级时仍给全额。它之前的任务链是50级（经典版60级时给五分之一）：全额220点。{npc:6735}派你去{area:1658}的{npc:3516}；他要20个{quest:3764}。（{zone:1453}和{zone:1455}的旅店老板也提供同样的起点。）",
	["{quest:3803}: 50 reputation for every 10 {item:11040}, as often as you like"] = "{quest:3803}：每10个{item:11040}给50点声望，可无限重复",
	["{quest:4182}, +100"] = "{quest:4182}，+100",
	["{quest:4183}, +75"] = "{quest:4183}，+75",
	["{quest:486}, a big bear, roams the {area:478} in south-west {zone:1438}."] = "{quest:486} 是一只大熊，在 {zone:1438} 西南部的 {area:478} 游荡。",
	["{quest:7801} to Exalted"] = "{quest:7801}刷到崇拜",
	["{quest:7801} to Honored"] = "{quest:7801}刷到尊敬",
	["{quest:7801} to Revered"] = "{quest:7801}刷到崇敬",
	["{quest:7801}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Night Elves start 900 higher: 88 turn-ins; Skyborne start at Neutral 500, so 7,900 away: 158, two fewer after Exploring the Alliance). {quest:4183} and the {item:11040} chain above take 8 turn-ins off, and every 10 {item:11040} you hand in counts as one more; each hub you did takes 20 to 28 more off if it paid in full. More quests pay {faction:69}, in full while they are no more than 5 levels below you: the rest of {zone:1439} (about 3,400 more), {area:415} in {zone:1440} (about 3,900) and Feathermoon in {zone:1444} (about 1,700). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7801}：每20个{item:14047}换50点声望，想做多少次都行。完成最初四次捐献后，人类、矮人或侏儒处于友善6,000中的700，离尊敬还差5,300点：106次交任务，2,120个{item:14047}（暗夜精灵起始高900点：88次；天裔从中立500起步，所以差7,900点：158次，完成“探索联盟”后少两次）。上面的{quest:4183}和{item:11040}任务链能抵掉8次交任务，每交10个{item:11040}又算多一次；你每做满一个枢纽（若给全额）能再抵20到28次。还有更多任务给{faction:69}声望，任务最多比你低5级时给全额：{zone:1439}其余部分（约3,400点）、{zone:1440}的{area:415}（约3,900点）以及{zone:1444}的羽月（约1,700点）。每获一点主城声望，也会给其他三个联盟主城四分之一（此处不计）。把所有{item:14047}一次性交完。",
}

G["forever/reputation/gnomeregan-exiles"] = {
	["400 {area:133} reputation from {npc:9616}'s ooze jars and {quest:4262} (level 52-54)"] = "{npc:9616}的软泥罐和{quest:4262}（52-54级）可获得400点{area:133}声望",
	["About 3,000 {area:133} reputation from low-level quests in {zone:1426}, paid to {zone:1455} too (in Classic, a fifth of it at 60)"] = "约3,000点{area:133}声望来自{zone:1426}的低级任务，同时也会给{zone:1455}（经典旧世里60级时只有五分之一）",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Cloth, {npc:9616}'s ooze quests and the {zone:1426} hubs, which pay {zone:1455} too: best done while leveling."] = "布料、{npc:9616}的软泥怪任务以及{zone:1426}的任务点，同时也会提升{zone:1455}声望：最好在升级时完成。",
	["Coldridge: on to {area:131}"] = "寒脊山谷：前往 {area:131}",
	["Coldridge: the hot Mornbrew"] = "寒脊山谷：热腾腾的晨酒。",
	["Coldridge: wolves, troggs and {npc:8416}'s things"] = "寒脊山谷：狼、穴居人和 {npc:8416} 的物品。",
	["Coldridge: {area:77} and {npc:714}"] = "寒脊山谷：{area:77}和{npc:714}",
	["Coldridge: {npc:786} and the troll cave"] = "寒脊山谷：{npc:786} 与巨魔洞穴",
	["Dark Iron Spy"] = "黑铁间谍",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Exalted with {faction:54}: in Classic, other races may buy the mechanostriders"] = "{faction:54}达到崇拜：在经典版中，其他种族可购买机械陆行鸟",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Gnomeregan Exiles Reputation"] = "诺莫瑞根流亡者声望",
	["Honored: in Classic the {faction:54}' vendors take 10% off for you, {npc:7955}'s mechanostriders (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}."] = "尊敬：经典怀旧服中，{faction:54} 商人会给你 10% 折扣，包括 {npc:7955} 出售的机械陆行鸟（20 金币，迅捷型 200 金币）；无限尚未确定，指南网站报告为友善 5%，逐步提高到崇拜 20%。尊敬到崇敬需要 12,000 点声望：交还 240 次，共 4,800 个 {item:14047}。",
	["Ice Claw Bear"] = "冰爪熊",
	["Optional: eastern {zone:1426}, from {npc:264936}'s camp to the {area:134} and {area:803}, about 500 reputation (100 at a fifth) in 30 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{zone:1426}东部，从{npc:264936}的营地到{area:134}和{area:803}，60级时30分钟约500点声望（按五分之一算是100）。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 无限 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Optional: the Dwarf and Gnome start valley south-west of {area:131}, about 1,150 reputation (230 at a fifth) in 30 minutes at 60. {npc:658} and {npc:713} stand at {area:77}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:131}西南的矮人与侏儒新手山谷，60级时30分钟约1,150点声望（按五分之一算是230）。{npc:658}和{npc:713}站在{area:77}。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 无限 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Optional: {area:131} and the Brewnall and {area:133} roads around it, about 1,300 reputation (260 at a fifth) in 50 minutes at 60. Most givers stand in and around the {area:2102} and at {area:189} east of it. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:131}以及周围布瑞恩诺尔和{area:133}的道路，60级时50分钟约1,300点声望（按五分之一算是260）。大多数任务发布者站在{area:2102}及其周边，以及它东边的{area:189}。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 无限 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Overmaster Pyron"] = "至尊匹隆",
	["Reputation · Cities"] = "声望 · 城市",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:7955} at {area:189} in {zone:1426} sells her mechanostriders to other races in Classic; the Mechanostrider and Swift Mechanostrider guides cover them."] = "从崇敬到崇拜需要21,000声望：交还420次，共8,400块 {item:14047}。在经典旧世中，达到崇拜后，{zone:1426} 的 {area:189} 内的 {npc:7955} 会向其他种族出售她的机械陆行鸟；机械陆行鸟和迅捷机械陆行鸟指南有详细说明。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Snow Leopard"] = "雪豹",
	["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill one and use an empty jar on its remains."] = "被诅咒的软泥怪和被污染的软泥怪在{area:1763}与{area:1765}周围的溪流、邪能水池间蠕动：击杀一只，再对残骸使用空瓶。",
	["The Dark Iron Spies lurk around Farsen's camp; the troggs dig in the {area:134}; {npc:1388}, a big snow leopard, prowls the hills above {area:803}."] = "黑铁密探潜伏在法森的营地周围；穴居人在{area:134}挖掘；大雪豹{npc:1388}在{area:803}上方山丘游荡。",
	["The Primal Oozes live in the pools around {area:537} in the middle of the crater; the Muculent and Glutinous Oozes fill the jars too. Kill one and use a jar on its remains."] = "原生软泥怪生活在环形山中央 {area:537} 周围的水池中；胶质软泥怪和粘稠的软泥怪也能装进罐子。击杀一只，再对其遗骸使用罐子。",
	["The Scalding Mornbrew cools in five minutes: run straight to {npc:836} at {area:77}."] = "滚烫的晨酒五分钟后会变凉：直接跑到 {area:77} 找 {npc:836}。",
	["The boars and bears roam around {area:131}; the wendigos live in the {area:136} south-west of town; the leper gnomes at the {area:133} road carry the cogs and gears; Rumbleshot's ammo lies at his camp west of town."] = "野猪和熊在{area:131}周围游荡；雪怪住在镇子西南面的{area:136}；{area:133}道路上的麻风侏儒携带两种齿轮；海格纳·重枪的弹药在镇子西面的营地。",
	["The quarry and {area:803}"] = "采石场和 {area:803}。",
	["The quarry: troggs, spies and {npc:1388}"] = "采石场：穴居人、间谍和 {npc:1388}",
	["The wolves roam the valley floor; the troggs dig in the camps east of {area:77}; {npc:8416}'s box, chest and bucket lie in the trogg camps."] = "狼在谷底活动；穴居人在{area:77}东侧的营地挖掘；{npc:8416}的盒子、箱子和水桶就在穴居人营地里。",
	["walk to the back of the cave"] = "走到洞穴深处。",
	["{area:131}: Brewnall and {quest:287}"] = "{area:131}：涌冰湖和 {quest:287}",
	["{area:131}: back in town"] = "{area:131}：回到镇上",
	["{area:131}: last hand-in"] = "{area:131}：最后一次交任务",
	["{area:131}: the hills and the depot"] = "{area:131}：山丘与仓库",
	["{area:2418}: hand in"] = "{area:2418}：交任务",
	["{area:254} stands in the west of the {zone:1428}. {quest:4262}, a fire elemental, walks the lava paths inside it, near the door of {area:1584} but outside the dungeon: at 60 you take him alone."] = "{area:254} 位于 {zone:1428} 西部。{quest:4262} 是一只火元素，在山内的熔岩小路上活动，靠近 {area:1584} 大门，但在地下城外：60 级可单独击败。",
	["{item:14047} drops from humanoids level 50 and up: the Scourge cultists and Scarlet Crusade in the Plaguelands, the Deadwood furbolgs of {zone:1448}, the Winterfall furbolgs of {zone:1452}. Keep any {item:14047} past the first 60 for {quest:7812}."] = "{item:14047} 由50级及以上人型生物掉落：瘟疫之地的天灾教徒和血色十字军、{zone:1448} 的死木熊怪，以及 {zone:1452} 的冬泉熊怪。最初60块之外的 {item:14047} 请保留，用于 {quest:7812}。",
	["{item:2592}: troggs, gnolls and kobolds in {zone:1432} and the {zone:1437}"] = "{item:2592}：来自 {zone:1432} 和 {zone:1437} 的穴居人、豺狼人和狗头人。",
	["{item:4306} drops from humanoids level 23 to 40: the Dragonmaw of the {zone:1437}, the Syndicate of Alterac and Arathi, Stranglethorn's trolls."] = "{item:4306} 由23到40级人形生物掉落：{zone:1437} 的龙喉兽人、奥特兰克和阿拉希的辛迪加成员，以及荆棘谷的巨魔。",
	["{item:4338} drops from humanoids level 35 to 50: the Shadowforge and {object:147516} dwarves of the {zone:1418} and {zone:1427}, the Dunemaul ogres of {zone:1446}, the Hatecrest naga of {zone:1444}."] = "{item:4338} 由 35 至 50 级的人型生物掉落：{zone:1418} 和 {zone:1427} 的暗炉矮人与 {object:147516} 矮人、{zone:1446} 的砂槌食人魔、{zone:1444} 的憎世纳迦。",
	["{npc:1252}, in {area:131}"] = "{npc:1252}，位于 {area:131}",
	["{npc:1274}, in the throne room"] = "{npc:1274}，在王座厅内",
	["{npc:1374} stands by {area:137} on the lake north-west of {area:131}; {quest:287} is the troll cave west of it."] = "{npc:1374} 站在 {area:131} 西北方湖边的 {area:137} 旁；{quest:287} 位于其西边的巨魔洞穴。",
	["{npc:14724} takes cloth for the {faction:54}; he stands in {object:171524} in {zone:1455}, by the tram. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7812} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the Commons is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1426} (levels 1-12) and {npc:4077}'s quests in Stonetalon (20-25) while you level. After the donations come {npc:9616}'s ooze quests and {quest:4262} (400), then the optional {zone:1426} hubs, best rate first: {area:132} (about 38 a minute at full value), {area:131} (26), the quarry (17). Every {area:133} gain also gives a quarter as much to {zone:1453}, {zone:1455} and {zone:1457}, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14724} 为 {faction:54} 接收布料；他站在 {zone:1455} 的 {object:171524}，靠近地铁。毛料、丝绸、魔纹布和 {item:14047} 各首次捐献 60 个，都能获得一次 150 点声望；完成 {item:14047} 的首次捐献后，可无限重复交还 {quest:7812}，每 20 个 {item:14047} 换 50 点。平民区的拍卖行是最快的布料来源。经典怀旧服中，任务最多比你低 5 级时仍给予完整声望，所以升级时就做完 {zone:1426}（1-12 级）以及石爪山脉 {npc:4077} 的任务（20-25 级）。捐献之后是 {npc:9616} 的软泥怪任务和 {quest:4262}（400 点），然后是 {zone:1426} 的可选任务点，按效率从高到低为：{area:132}（完整奖励时约每分钟 38 点）、{area:131}（26 点）、采石场（17 点）。除 1-10 级起始地区的任务外，每次获得 {area:133} 声望，还会同时给 {zone:1453}、{zone:1455} 和 {zone:1457} 各增加其四分之一的声望。传承天赋“外交家”使每次获取量最多额外提高 10%。",
	["{npc:14724}, the cloth quartermaster"] = "布料军需官{npc:14724}",
	["{npc:6806}, in the inn"] = "{npc:6806}，在旅店里",
	["{npc:786} camps south of {area:77}, at the mouth of the troll cave; the journal lies at the back of the cave."] = "{npc:786}在{area:77}南面的巨魔洞口扎营；日记在洞穴深处。",
	["{npc:9561} at {area:2418}, in the south-east of the {zone:1428}, wants {quest:4262} dead: 100 {area:133} reputation (level 52: in Classic 40 at 60). Her next quest, Incendius!, needs a {area:1584} group: 100 more, in full."] = "{zone:1428} 东南部 {area:2418} 的 {npc:9561} 要求杀死 {quest:4262}：奖励100点 {area:133} 声望（任务等级52；在经典旧世中，60级做时只有40点）。她的后续任务“伊森迪奥斯!”需要 {area:1584} 小队：再给100点，全额获得。",
	["{npc:9616} in {object:171524} wants ooze samples for her research: 150 {area:133} reputation for each of her two quests (level 52 and 54: in Classic 60 and 120 of it at 60). She hands you the empty jars."] = "{object:171524} 内的 {npc:9616} 需要软泥怪样本进行研究：她的两个任务各奖励150点 {area:133} 声望（任务等级52和54；在经典旧世中，60级做时分别只有60和120点）。她会给你空罐子。",
	["{object:171524}: hand in"] = "{object:171524}：交还",
	["{object:171524}: the second jars"] = "{object:171524}：第二批罐子",
	["{quest:4262}, +100"] = "{quest:4262}，+100",
	["{quest:4512}, +150"] = "{quest:4512}，+150",
	["{quest:7812} to Exalted"] = "{quest:7812}刷到崇拜",
	["{quest:7812} to Honored"] = "{quest:7812}刷到尊敬",
	["{quest:7812} to Revered"] = "{quest:7812}刷到崇敬",
	["{quest:7812}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Night Elf stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Gnomes start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). {npc:9616}'s and {npc:9561}'s quests above take 8 turn-ins off; each {zone:1426} hub you did takes 10 to 26 more off if it paid in full. Outside Dun Morogh Gnomeregan pays little: {npc:4077}'s quests in Stonetalon (about 500) and {object:171524}'s {area:133} dungeon quests. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7812}：每20个{item:14047}换50点声望，想交多少次都行。四次首次捐赠之后，人类、矮人或暗夜精灵处在友善700/6,000，离尊敬还差5,300点：106次上交、2,120个{item:14047}（侏儒初始高900点：88次；天裔从中立2,000开始，差6,400点：128次，做了“探索联盟”后少两次）。上面{npc:9616}和{npc:9561}的任务能减掉8次上交；你做过的每个{zone:1426}任务点，如果按全额给，还能再减10到26次。丹莫罗以外，诺莫瑞根的声望给得很少：{npc:4077}在石爪山的任务（约500点）和{object:171524}的{area:133}副本任务。每份主城声望收益还会以四分之一的比例给其他三个联盟主城（这里未计入）。把所有{item:14047}一次交清。",
	["{zone:1448}: Cursed and Tainted Oozes"] = "{zone:1448}：被诅咒的软泥怪和被污染的软泥怪。",
	["{zone:1449}: Primal Oozes"] = "{zone:1449}：原生软泥怪",
}

G["forever/reputation/ironforge"] = {
	["About 2,900 {faction:47} reputation from low-level quests in {zone:1426}, most of it paid to {area:133} too (in Classic, a fifth of it at 60)"] = "在{zone:1426}做低级任务可获得约2,900点{faction:47}声望，其中大部分也会给{area:133}（经典旧世里60级时只有五分之一）",
	["About 600 {faction:47} reputation from level 52-59 quests in the {zone:1428} and {zone:1452}; {zone:1459}'s quests pay {faction:47} too"] = "{zone:1428}和{zone:1452}的52-59级任务约提供600点{faction:47}声望；{zone:1459}的任务也会提升{faction:47}声望",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Cloth, the {zone:1428} quests and the {zone:1426} hubs, which pay {area:133} too; {zone:1459} adds more."] = "布料、{zone:1428}的任务和{zone:1426}的任务点（同时提升{area:133}声望）；{zone:1459}还能提供更多。",
	["Coldridge: on to {area:131}"] = "寒脊山谷：前往 {area:131}",
	["Coldridge: the hot Mornbrew"] = "寒脊山谷：热腾腾的晨酒。",
	["Coldridge: wolves, troggs and {npc:8416}'s things"] = "寒脊山谷：狼、穴居人和 {npc:8416} 的物品。",
	["Coldridge: {area:77} and {npc:714}"] = "寒脊山谷：{area:77}和{npc:714}",
	["Coldridge: {npc:786} and the troll cave"] = "寒脊山谷：{npc:786} 与巨魔洞穴",
	["Dark Iron Spy"] = "黑铁间谍",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Exalted with {faction:47}: in Classic, other races may buy the rams"] = "{faction:47}达到崇拜：在经典版中，其他种族可购买山羊",
	["Firegut Brute"] = "火腹蛮兵",
	["Firegut Ogre"] = "火腹食人魔",
	["Firegut Ogre Mage"] = "火腹食人魔法师",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Hear {npc:8879} out"] = "听完{npc:8879}的话",
	["Honored: in Classic Ironforge's vendors take 10% off for you, {npc:1261}'s rams (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}."] = "尊敬：经典怀旧服中，铁炉堡商人会给你 10% 折扣，包括 {npc:1261} 出售的山羊（20 金币，迅捷型 200 金币）；无限尚未确定，指南网站报告为友善 5%，逐步提高到崇拜 20%。尊敬到崇敬需要 12,000 点声望：交还 240 次，共 4,800 个 {item:14047}。",
	["Ice Claw Bear"] = "冰爪熊",
	["Ironforge Reputation"] = "铁炉堡声望",
	["Optional: eastern {zone:1426}, from {npc:264936}'s camp to the {area:134} and {area:803}, about 500 reputation (100 at a fifth) in 30 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{zone:1426}东部，从{npc:264936}的营地到{area:134}和{area:803}，60级时30分钟约500点声望（按五分之一算是100）。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 无限 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Optional: the Dwarf and Gnome start valley south-west of {area:131}, about 1,100 reputation (220 at a fifth) in 30 minutes at 60. {npc:658} and {npc:713} stand at {area:77}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:131}西南的矮人与侏儒新手山谷，60级时30分钟约1,100点声望（按五分之一算是220）。{npc:658}和{npc:713}站在{area:77}。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 无限 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Optional: {area:131} and the Brewnall and {area:133} roads around it, about 1,300 reputation (260 at a fifth) in 50 minutes at 60. Most givers stand in and around the {area:2102} and at {area:189} east of it. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:131}以及周围布瑞恩诺尔和{area:133}的道路，60级时50分钟约1,300点声望（按五分之一算是260）。大多数任务发布者站在{area:2102}及其周边，以及它东边的{area:189}。经典旧世里，低于你6级以上的任务奖励更少（60级时为五分之一）；一份 无限 测试报告称会全额发放。第一次上交就能看出是哪种：如果只给五分之一，就跳过这些任务点。跳过这一步就跳过该任务点。",
	["Plant {npc:9176}'s head on the soft dirt mound at the top of {area:249}."] = "把 {npc:9176} 的头颅插在 {area:249} 顶部的松软土堆上。",
	["Reputation · Cities"] = "声望 · 城市",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:1261} at {area:803} in eastern {zone:1426} sells his rams to other races in Classic; the Ram and Swift Ram guides cover them."] = "崇敬到崇拜需要21,000声望：交还420次、8,400块{item:14047}。经典版中，崇拜后{zone:1426}东部{area:803}的{npc:1261}会向其他种族出售山羊；山羊和迅捷山羊指南有详细说明。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Royal Historian Archesonus"] = "皇家史学家阿克森努斯",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Snow Leopard"] = "雪豹",
	["Thaurissan and {area:252}"] = "索瑞森与{area:252}",
	["The Dark Iron Spies lurk around Farsen's camp; the troggs dig in the {area:134}; {npc:1388}, a big snow leopard, prowls the hills above {area:803}."] = "黑铁密探潜伏在法森的营地周围；穴居人在{area:134}挖掘；大雪豹{npc:1388}在{area:803}上方山丘游荡。",
	["The Scalding Mornbrew cools in five minutes: run straight to {npc:836} at {area:77}."] = "滚烫的晨酒五分钟后会变凉：直接跑到 {area:77} 找 {npc:836}。",
	["The Thaurissan relics are the carved stones in the ruins around {area:251}, west along the road: click twelve of them. {npc:9176} and the Blackrock orcs and worgs hold the camps at the foot of {area:254}, further west; each may drop a {item:11467} (about one kill in three), and {npc:9177} wants fifty. The orcs are level 50 and up, so they drop {item:14047} too: keep it for {quest:7806}."] = "索瑞森遗物是道路西边、{area:251} 周围遗迹里的雕刻石块：点击十二个。再往西，{npc:9176}、黑石兽人和座狼占据 {area:254} 山脚的营地；每只都可能掉落 {item:11467}（约三分之一），{npc:9177} 需要五十个。兽人是 50 级及以上，也会掉落 {item:14047}：留着用于 {quest:7806}。",
	["The boars and bears roam around {area:131}; the wendigos live in the {area:136} south-west of town; the leper gnomes at the {area:133} road carry the cogs and gears; Rumbleshot's ammo lies at his camp west of town."] = "野猪和熊在{area:131}周围游荡；雪怪住在镇子西南面的{area:136}；{area:133}道路上的麻风侏儒携带两种齿轮；海格纳·重枪的弹药在镇子西面的营地。",
	["The quarry and {area:803}"] = "采石场和 {area:803}。",
	["The quarry: troggs, spies and {npc:1388}"] = "采石场：穴居人、间谍和 {npc:1388}",
	["The wolves roam the valley floor; the troggs dig in the camps east of {area:77}; {npc:8416}'s box, chest and bucket lie in the trogg camps."] = "狼在谷底活动；穴居人在{area:77}东侧的营地挖掘；{npc:8416}的盒子、箱子和水桶就在穴居人营地里。",
	["These quests are level 52 to 59, so they pay in full at 60, or nearly: about 600 {faction:47} reputation (in Classic about 450 at 60, as the {zone:1428} ones are level 52 to 54). {npc:8879} stands beside King Magni in the {object:171709}; he sends you to the ruins of Thaurissan in the {zone:1428}."] = "这些任务是52到59级，所以60级时仍能全额或接近全额：约600点{faction:47}声望（经典旧世里60级时约450点，因为{zone:1428}的那些任务是52到54级）。{npc:8879}站在{object:171709}里麦格尼国王身旁；他派你去{zone:1428}的索瑞森废墟。",
	["With a group, {area:1584} pays more: Archesonus's chain goes on with {npc:9021} (100) and The Fate of the Kingdom (Emperor Thaurissan, 150), and {npc:9177} takes 20 Dark Iron Fanny Packs from the dwarves inside (The Good Stuff, 100). {zone:1459}, from level 51, pays {faction:47} too: its one-time quests about 1,900 as your Stormpike standing grows (the {zone:1459} guide walks them), and inside the battle 25 for every 10 Irondeep or {item:17542} and 50 for 5 Storm Crystals, as often as you like."] = "组队前往{area:1584}可获得更多：皇家历史学家阿克瑟努斯的任务线后续有{npc:9021}（100）和“王国的命运”（索瑞森大帝，150），{npc:9177}还会收取里面矮人掉落的20个黑铁挎包（“好东西”，100）。51级起可参加的{zone:1459}也奖励{faction:47}声望：随着雷矛声望提升，一次性任务共约1,900（{zone:1459}指南会带你完成）；战场内每交10个深铁矿洞补给品或{item:17542}奖励25声望，每交5个风暴水晶奖励50声望，可无限重复。",
	["walk to the back of the cave"] = "走到洞穴深处。",
	["{area:131}: Brewnall and {quest:287}"] = "{area:131}：涌冰湖和 {quest:287}",
	["{area:131}: back in town"] = "{area:131}：回到镇上",
	["{area:131}: last hand-in"] = "{area:131}：最后一次交任务",
	["{area:131}: the hills and the depot"] = "{area:131}：山丘与仓库",
	["{area:2418} sits in the south-east of the {zone:1428}, at the top of the pass up from Redridge. {npc:9177} wants the Firegut ogres of {area:249}, north of the Vigil, thinned out; the Brutes keep to the rock's east side."] = "{area:2418} 位于 {zone:1428} 东南部，从赤脊山上来的山口顶端。{npc:9177} 要你削减岗哨北面 {area:249} 的火腹食人魔数量；蛮兵 聚集在岩石东侧。",
	["{area:2418}: hand in"] = "{area:2418}：交任务",
	["{faction:47}: Archesonus again"] = "{faction:47}：再次找阿克鲁努斯。",
	["{item:14047} drops from humanoids level 50 and up: the Scourge cultists and Scarlet Crusade in the Plaguelands, the Deadwood furbolgs of {zone:1448}, the Winterfall furbolgs of {zone:1452}. Keep any {item:14047} past the first 60 for {quest:7806}."] = "{item:14047} 由50级及以上人型生物掉落：瘟疫之地的天灾教徒和血色十字军、{zone:1448} 的死木熊怪，以及 {zone:1452} 的冬泉熊怪。最初60块之外的 {item:14047} 请保留，用于 {quest:7806}。",
	["{item:2592}: troggs, gnolls and kobolds in {zone:1432} and the {zone:1437}"] = "{item:2592}：来自 {zone:1432} 和 {zone:1437} 的穴居人、豺狼人和狗头人。",
	["{item:4306} drops from humanoids level 23 to 40: the Dragonmaw of the {zone:1437}, the Syndicate of Alterac and Arathi, Stranglethorn's trolls."] = "{item:4306} 由23到40级人形生物掉落：{zone:1437} 的龙喉兽人、奥特兰克和阿拉希的辛迪加成员，以及荆棘谷的巨魔。",
	["{item:4338} drops from humanoids level 35 to 50: the Shadowforge and {object:147516} dwarves of the {zone:1418} and {zone:1427}, the Dunemaul ogres of {zone:1446}, the Hatecrest naga of {zone:1444}."] = "{item:4338} 由 35 至 50 级的人型生物掉落：{zone:1418} 和 {zone:1427} 的暗炉矮人与 {object:147516} 矮人、{zone:1446} 的砂槌食人魔、{zone:1444} 的憎世纳迦。",
	["{npc:11755} in {area:2255} sends you west to {npc:10301} at {area:2253}. {npc:10301}'s damaged crate and wrecked wagon lie at {area:2245}, down the valley to the south-east; his supplies lie around the wagon and the owlbeasts nearby carry his amulet. The last quest is level 59: 100 {faction:47} in full."] = "{area:2255} 的 {npc:11755} 会让你向西去找 {area:2253} 的 {npc:10301}。{npc:10301} 损坏的箱子和货车残骸位于东南方山谷下方的 {area:2245}；物资散落在货车周围，附近枭兽携带着他的护符。最后一个任务为 59 级：可获得全额的 100 点 {faction:47} 声望。",
	["{npc:1252}, in {area:131}"] = "{npc:1252}，位于 {area:131}",
	["{npc:1274}, in the throne room"] = "{npc:1274}，在王座厅内",
	["{npc:1374} stands by {area:137} on the lake north-west of {area:131}; {quest:287} is the troll cave west of it."] = "{npc:1374} 站在 {area:131} 西北方湖边的 {area:137} 旁；{quest:287} 位于其西边的巨魔洞穴。",
	["{npc:14723} takes cloth for {faction:47}; she stands outside the clothier on the north side of the {object:32372}, among the tailors. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7806} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the Commons is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1426} (levels 1-12), {zone:1432} (10-20) and the {zone:1437} (20-30) while you level through them. After the donations come the level 52-59 quests of the {zone:1428} and {zone:1452} (about 600), then the optional {zone:1426} hubs, best rate first: {area:132} (about 37 a minute at full value), {area:131} (26), the quarry (17). Every {faction:47} gain also gives a quarter as much to {zone:1453}, {zone:1457} and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14723}接收布料，提供{faction:47}声望；她站在{object:32372}北侧服装店外的裁缝群中。毛料、丝绸、魔纹布和{item:14047}各首次捐赠60个时，分别一次性奖励150声望；完成{item:14047}的首次捐赠后，{quest:7806}每20个{item:14047}奖励50，可无限重复。平民区拍卖行是最快的布料来源。经典旧世中，任务比你低不超过5级时仍奖励全额声望，因此应在练级时顺路完成{zone:1426}（1-12级）、{zone:1432}（10-20级）及{zone:1437}（20-30级）。捐赠后先做{zone:1428}和{zone:1452}的52-59级任务（约600），再选做{zone:1426}任务区，按效率从高到低为：{area:132}（全额时每分钟约37）、{area:131}（26）、采石场（17）。每次获得{faction:47}声望时，{zone:1453}、{zone:1457}和诺莫瑞根流亡者也会获得四分之一，1-10级初始地区的任务除外。传承系统“外交家”使每次声望获取最多增加10%。",
	["{npc:14723}, the cloth quartermaster"] = "布料军需官{npc:14723}",
	["{npc:6806}, in the inn"] = "{npc:6806}，在旅店里",
	["{npc:786} camps south of {area:77}, at the mouth of the troll cave; the journal lies at the back of the cave."] = "{npc:786}在{area:77}南面的巨魔洞口扎营；日记在洞穴深处。",
	["{quest:3701}, +10"] = "{quest:3701}，+10",
	["{quest:3701}, +100"] = "{quest:3701}，+100",
	["{quest:3823}, +100"] = "{quest:3823}，+100",
	["{quest:3824}, +100"] = "{quest:3824}，+100",
	["{quest:3825}, +100"] = "{quest:3825}，+100",
	["{quest:4283}, +100"] = "{quest:4283}，+100",
	["{quest:4861}, +100"] = "{quest:4861}，+100",
	["{quest:7806} to Exalted"] = "{quest:7806}刷到崇拜",
	["{quest:7806} to Honored"] = "{quest:7806}刷到尊敬",
	["{quest:7806} to Revered"] = "{quest:7806}刷到崇敬",
	["{quest:7806}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Night Elf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Dwarves start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). The level 52-59 quests above take 12 turn-ins off; each {zone:1426} hub you did takes 10 to 26 more off if it paid in full. More hubs pay {faction:47}, in full while they are no more than 5 levels below you: {area:144} in {zone:1432} (about 3,500 in all) and {area:150} in the {zone:1437} (about 2,500). From level 51 {zone:1459}'s one-time quests add about 1,900. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7806}：每20个{item:14047}换50点声望，想交多少次都行。四次首次捐赠之后，人类、暗夜精灵或侏儒处在友善700/6,000，离尊敬还差5,300点：106次上交、2,120个{item:14047}（矮人初始高900点：88次；天裔从中立2,000开始，差6,400点：128次，做了“探索联盟”后少两次）。上面52-59级的任务能减掉12次上交；你做过的每个{zone:1426}任务点，如果按全额给，还能再减10到26次。更多任务点会给{faction:47}，只要最多低于你5级就按全额：{zone:1432}的{area:144}（共约3,500点）和{zone:1437}的{area:150}（约2,500点）。从51级起，{zone:1459}的一次性任务再加约1,900点。每份主城声望收益还会以四分之一的比例给其他三个联盟主城（这里未计入）。把所有{item:14047}一次交清。",
}

G["forever/reputation/kirin-tor"] = {
	["Alliance Skyborne start Friendly with the {faction:2740}, and their arrival quests The Magical City of Dalaran and Exploring the Alliance pay 100 more each, so {npc:32287} sells you the Azure recipes at once (10g each, they need skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}, past the Sky Enclave. Buy the ones for your profession."] = "联盟天裔起始对 {faction:2740} 为友善，到达后的 魔法之城达拉然 和 联盟之旅 任务又各奖励100点，因此可以立即向 {npc:32287} 购买碧蓝圣殿骑士配方（每张10金币，需要技能175）。他在 {area:279} 经过苍穹领地后那栋挂着 {faction:2740} 旗帜的建筑楼上。购买你专业对应的配方。",
	["Back to Modera's image"] = "返回大法师茉德拉的影像的影像处",
	["Back to {npc:264265}"] = "返回{npc:264265}处",
	["City of Dalaran runs to Exalted"] = "跑达拉然城的任务至崇拜",
	["City of Dalaran runs to Friendly"] = "反复打达拉然城至友善",
	["Eight Azure helm and shoulder recipes at Friendly ({skill:164}, {skill:165}, {skill:197})"] = "友善时可购八种蔚蓝头盔和护肩配方（{skill:164}、{skill:165}、{skill:197}）",
	["Kirin Tor Reputation"] = "肯瑞托声望",
	["Mana Echo"] = "法力回响",
	["New in Forever: {area:279}'s mages sell Azure armour recipes at Friendly and their tabard at Exalted."] = "无限新增：{area:279}的法师在友善时出售蔚蓝护甲配方，在崇拜时出售其战袍。",
	["Nothing is sold at Honored or Revered in the game's data. Friendly to Exalted is 39,000 reputation, all from City of Dalaran kills. In Classic most dungeon kills stop paying at Honored or Revered; whether these do is not known yet."] = "游戏数据中没有任何物品要求尊敬或崇敬才能购买。从友善到崇拜需要39,000声望，全部来自达拉然城的击杀。在经典旧世中，多数地下城击杀会在尊敬或崇敬后停止提供声望；这里是否如此尚不清楚。",
	["Reputation · World"] = "声望 · 世界",
	["Saturated Remnant"] = "饱和残渣",
	["Seeking Remnant"] = "寻觅残渣",
	["Skyborne: the recipes now"] = "天裔：现在领取配方",
	["The City of Dalaran"] = "达拉然城",
	["The City of Dalaran is a dungeon for levels 28 to 33: go in through the sewers with the key Modera gave you. The arcane elementals throughout the city count for {quest:92457}. The {npc:246020}, the last boss, waits in the Purple Parlor above the Violet Citadel (a portal by {npc:246748} in the Citadel takes you up) and drops the {item:251961}. Beta players saw every kill in the dungeon pay {faction:2740} reputation, the bosses the most. Group of five advised below level 35."] = "达拉然城是 28 至 33 级地下城：用茉德拉给你的钥匙，从下水道进入。城内各处的奥术元素都计入 {quest:92457}。最终首领 {npc:246020} 在紫罗兰城堡上方的紫色天台等待（城堡内 {npc:246748} 旁的传送门可将你送上去），会掉落 {item:251961}。测试版玩家发现，地下城内每次击杀都能获得 {faction:2740} 声望，首领给得最多。35 级以下建议五人组队。",
	["The quests leave a non-Skyborne at about 320 of the 3,000 Friendly needs. The rest comes from kills in the City of Dalaran dungeon: run it until Friendly. How much each kill pays is not in the game's data; the bosses pay the most. At 60 you clear it alone."] = "完成这些任务后，非天裔角色的声望约为320点，达到友善需要3,000点。剩下的靠击杀 达拉然城 地下城中的敌人获得：反复刷到友善。游戏数据中没有每次击杀的具体奖励；首领奖励最多。60级时可以单刷。",
	["The {area:796} stands in the north-east of {zone:1420}; Doan waits at the end of the Library wing. Group of five advised below level 40."] = "{area:796} 位于 {zone:1420} 东北；杜安在图书馆区的尽头等候。低于 40 级建议五人组队。",
	["The {item:285327}"] = "{item:285327}",
	["you get the {item:277507} with it"] = "还会一并获得 {item:277507}",
	["{item:251961}, from the {npc:246020}"] = "{item:251961}，来自{npc:246020}",
	["{item:273169}, from {npc:6487}"] = "{item:273169}，由{npc:6487}掉落",
	["{npc:246748}'s image"] = "{npc:246748} 的影像",
	["{npc:247264} of the {faction:2740} waits in {area:271}. He sends you to {npc:246748}'s image by the shore of {area:1338}, outside {area:279}'s walls. The {faction:2740} quests start at level 24 to 30 and pay full reputation while they are at most 5 levels below you; in Classic a quest 6+ levels below you pays less (a fifth at 60)."] = "{faction:2740}的{npc:247264}在{area:271}等待。他派你去{area:279}城墙外、{area:1338}岸边的{npc:246748}影像处。{faction:2740}的任务从24到30级开始，只要最多低于你5级就按全额给声望；经典旧世里低于你6级以上的任务给的更少（60级时为五分之一）。",
	["{npc:252085} waits in the Violet Citadel in {area:279}."] = "{npc:252085} 在 {area:279} 的紫罗兰城堡中等待。",
	["{npc:264265} in {area:279} wants a book back from {npc:6487}, the last boss of the {area:796}'s Library (levels 33 to 41), in {zone:1420}."] = "{area:279} 的 {npc:264265} 要你从 {npc:6487} 处取回一本书，他是 {zone:1420} 的 {area:796} 图书馆区的最终首领（33到41级）。",
	["{npc:32287} and {npc:28776}, the tabard vendor in {area:279}, sell the {item:285327} at Exalted for 25g."] = "{npc:32287}及{area:279}的战袍商人{npc:28776}会在崇拜后出售{item:285327}，售价25金币。",
	["{npc:32287} sells the Azure helm and shoulder recipes at Friendly, 10g each (skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}. Buy the ones for your profession."] = "{npc:32287} 在友善后出售碧蓝圣殿骑士头盔和肩部配方，每张 10 金币（技能 175）。他位于 {area:279} 内、挂有 {faction:2740} 旗帜的建筑楼上。购买适合自己专业的配方。",
	["{npc:32287}: the Azure recipes"] = "{npc:32287}：碧蓝圣殿骑士配方",
}

