G["forever/alliance/02-westfall"] = {
	["{item:814}: keep five for {npc:392} at the {area:115}, later on the route"] = "{item:814}：留五个，路线后面交给{area:115}的{npc:392}",
	["{npc:376} is in the Cathedral of Light, across {object:2098} from {npc:1646}."] = "{npc:376}在光明大教堂，就在{npc:1646}隔着{object:2098}的对面。",
	["{npc:5480} trains warriors in {object:2100}, near {npc:1323}'s shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480}在{object:2100}训练战士，就在{npc:1323}的商店附近；从{zone:1455}开来的地铁到达{object:28027}，就在它北边。{npc:6089}和{npc:6090}一起站在那里的{object:2152}旁。{npc:6090}会为了他的杯子和你打一架。如果{npc:5480}不给{quest:1638}，就直接去找{npc:6089}：不用它他也会给{quest:1639}。",
