G["forever/alliance/03-darkshore-return"] = {
	["Cure {npc:12298}"] = "治愈{npc:12298}",
	["From the dock, up to the north end of the village first ({npc:3649}, {npc:3702} by the moonwell, {npc:2913}), then down the main street: the WANTED poster outside the inn, {npc:3693} at its east end, where the road leaves south. {npc:3694} stands beside {npc:3693} by the flight master; if she isn't there, she has been killed and respawns shortly: wait a moment."] = "从码头先上到村子北端（{npc:3649}，{npc:3702}在月井旁，{npc:2913}），再沿主街往南：旅店外的通缉令，{npc:3693}在街的东端，也就是道路向南出村的地方。{npc:3694}在飞行管理员旁、{npc:3693}边上；如果她不在，说明刚被击杀，很快就会刷新：稍等片刻。",
	["The {object:12666}, once it has {quest:949}"] = "接了{quest:949}后使用{object:12666}",
	["{npc:3649}, north end of the village: {npc:1646}'s reply"] = "{npc:3649}，在村子北端：{npc:1646}的回信",
	["{npc:3694}, beside {npc:3693}: for {npc:3691} in {area:415}, in the next guide"] = "{npc:3694}，在{npc:3693}旁边：为{area:415}的{npc:3691}，下一份指南",
}

G["forever/alliance/03-loch-modan"] = {
	["Elder Mountain Boars, {npc:270693} and the loch crocolisks"] = "老山地野猪、{npc:270693}和洛克鳄",
	["For {npc:3649}, where the boat lands"] = "在船靠岸处交给{npc:3649}",
	["From the bridge, head north to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "从桥边向北到{area:86}。{npc:6172}躺在湖的南边：对他使用{item:6866}。他周围的迪菲亚流氓巫师带着{item:6846}。",
	["Kept five Flasks of Oil from {zone:1436}'s Harvest Watchers? {npc:392} takes them for his lighthouse fire."] = "从{zone:1436}的看守傀儡那里留了五瓶灯油？{npc:392}会收去点灯塔的火。",
	["No Defias Brotherhood from Wiley (it starts with {npc:234}'s letter in {zone:1436}): skip {zone:1436}. North along the road from {area:87} to {zone:1453}: {npc:466} sits on his horse at the far end of the bridge outside the main gate. Then the gryphons in the {object:2096}, back to {area:69}."] = "别从威利那里接迪菲亚兄弟会（它始于{zone:1436}的{npc:234}的信）：跳过{zone:1436}。从{area:87}沿路向北到{zone:1453}：{npc:466}骑着马站在正门外桥的另一端。然后去{object:2096}坐狮鹫，回{area:69}。",
	["South along the west shore. The {object:665289} lies on the loch bed at one of several places: east of {area:144} (48.1,39.7), a little south-west of there (45.7,43.4), or at the south end of the loch (48.7,54.4 or 50.6,53.3). If it isn't at the arrow, try the next place. Click it for the quest; the {item:278051} comes with it."] = "沿西岸往南。{object:665289}躺在湖底，位置有这几处：{area:144}东边（48.1,39.7）、那里往西南一点（45.7,43.4），或湖的南端（48.7,54.4 或 50.6,53.3）。如果箭头处没有，就试下一个位置。点击它接任务，{item:278051}会一起拿到。",
	["The Elder Mountain Boars roam the hills north-west of the lodge, along the east shore: {quest:258} runs for 12 minutes, so the boars come first. {npc:270693}, a crocolisk, patrols the shore below them among the Loch Crocolisks."] = "老山地野猪在旅舍西北、沿东岸的丘陵游荡：{quest:258}持续12分钟，所以先打野猪。{npc:270693}是一只鳄鱼，在它们下方的岸边、洛克鳄群中巡逻。",
	["The road east to Redridge"] = "向东通往赤脊山的路",
	["{item:2924}: Loch Crocolisks"] = "{item:2924}：洛克鳄",
	["{item:3636}: {npc:391}, on the beach north-east of the lighthouse"] = "{item:3636}：{npc:391}，在灯塔东北边的沙滩上",
	["{npc:1154}: the loch crocolisks below the lodge"] = "{npc:1154}：旅舍下方的洛克鳄",
	["{npc:1646} stands at the east side of {object:2098}, on the way from the {object:28027} to the harbour."] = "{npc:1646}站在{object:2098}东侧，在从{object:28027}去港口的路上。",
	["{npc:6173} and {npc:6171} are in the Cathedral of Light, on {object:2098}, on the way to the harbour."] = "{npc:6173}和{npc:6171}在光明大教堂，就在{object:2098}上、去港口的路上。",
	["{zone:1453}'s gate"] = "{zone:1453}的正门",
}

G["forever/alliance/04-redridge-mountains"] = {
	["Already carrying six? Hand them in now"] = "已经带了六个？现在就交",
	["Follow the road south from {area:1002} into {zone:1431}; {area:42} lies on the east side of the forest.\nNo {item:4371} for {quest:174}? {npc:3133}, in the house beside {npc:276}, keeps only one and is usually sold out. Without one, right-click the quest in the guide window and skip it.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "沿路向南从{area:1002}进入{zone:1431}；{area:42}在森林东侧。\n没有{item:4371}做{quest:174}？{npc:3133}在{npc:276}旁的房子里只备一个，通常已经卖光。没有的话，在指南窗口中右键点击该任务并跳过。\n{npc:276}的房子在小镇东端。{npc:3133}在它旁边的房子里卖工程学商品。",
	["For {npc:288}, at {quest:163} on the next {zone:1431} loop"] = "为{npc:288}：{quest:163}，在下一圈{zone:1431}环路中完成",
	["From the keep head back west along the lake's north shore and north up the {area:95}. Just south of {area:997}, {npc:518}, a level 25 gnoll, walks among the Redridge Alphas and Mystics."] = "从要塞沿湖北岸向西折回，再向北沿{area:95}上行。{area:997}南边一点，25级的豺狼人{npc:518}在赤脊山首领和赤脊山秘法师之间走动。",
	["Greater Tarantulas crawl on the slopes around {quest:98386}, north-east of the lake; their Tarantula Eggs lie on the ground among them: click six."] = "巨型狼蛛在湖东北边{quest:98386}周围的山坡上爬行；狼蛛卵就散落在它们中间的地上：点六个。",
	["The road into {zone:1429}"] = "进入{zone:1429}的路",
	["Train, then leave by the main gate and follow the road east through {zone:1429}.\n{quest:174} in {area:42} needs a {item:4371}. Its vendors keep only one or two, and {npc:3133} in {area:42} is nearly always sold out: buy one at the Auction House in the {object:2096} on your way out. An engineer can make one too."] = "学完技能后从正门出去，沿路向东穿过{zone:1429}。\n{area:42}的{quest:174}需要一个{item:4371}。商人们只备一两个，{area:42}的{npc:3133}几乎总是卖光：出门时顺路在{object:2096}的拍卖行买一个。工程师也能自己做一个。",
	["{item:2251}: keep the ones these spiders drop, for {npc:272} in {area:42}"] = "{item:2251}：留着这些蜘蛛掉落的，给{area:42}的{npc:272}",
	["{item:4371}: the Auction House, for {quest:174} in {area:42}"] = "{item:4371}：拍卖行，为{area:42}的{quest:174}",
	["{npc:272}: six Gooey Spider Legs, which {zone:1431}'s spiders drop even without the quest"] = "{npc:272}：六条粘糊的蜘蛛腿，{zone:1431}的蜘蛛即使没接任务也会掉落",
	["{npc:415}, by the road at the north end of the bridge"] = "{npc:415}，在桥北端路边",
	["{npc:415}, by the road on the way to the bridge"] = "{npc:415}，在去桥的路边",
}

G["forever/alliance/05-duskwood"] = {
	["Carrion Recluses lurk in the woods on the way west, and Venom Web Spiders, Pygmy Venom Web Spiders and Green Recluses crawl just south of {npc:311}'s camp: each can drop a leg."] = "食腐独行蛛潜伏在西行路上的树林里，结网毒蜘蛛、小型结网毒蜘蛛和绿色独行蛛就在{npc:311}营地南边爬动：每种都可能掉一条腿。",
	["For {npc:288}, at {area:94} on the way west"] = "为{npc:288}：在西行路上的{area:94}",
	["Gooey Spider Legs"] = "粘糊的蜘蛛腿",
	["Hearth back to {area:42} if you bound at the Scarlet Raven Tavern on the first loop, or head back east along the road."] = "如果第一圈把炉石绑在猩红渡鸦酒馆，就用炉石回{area:42}；否则沿路向东返回。",
	["{item:4371}: the Auction House, {object:2096}; {npc:5519} keeps one and is nearly always sold out"] = "{item:4371}：{object:2096}的拍卖行；{npc:5519}只备一个，几乎总是卖光",
	["{npc:272} is in the Scarlet Raven Tavern too."] = "{npc:272}也在猩红渡鸦酒馆里。",
}

G["forever/alliance/06-ashenvale"] = {
	["Escort {npc:11218} south along the road to his bag at the southern edge of {zone:1439}, then go on to {npc:11219} at {area:413}."] = "护送{npc:11218}沿路向南，到{zone:1439}南端他放包的地方，再继续去{area:413}找{npc:11219}。",
	["Follow the road south-east from {area:413} back to {area:415}: {npc:3845} stands by the flight master."] = "从{area:413}沿路向东南回到{area:415}：{npc:3845}站在飞行管理员旁。",
	["For {npc:3649}, back in {area:442} (06-wetlands)"] = "为{npc:3649}：回到{area:442}（06-wetlands）",
	["From {area:415} head south-west to the {area:412} south of the shrine: {npc:3664} and his voidwalkers hold them. Pull his guards first."] = "从{area:415}向西南前往神殿南边的{area:412}：{npc:3664}和他的虚空行者守在那里。先拉他的守卫。",
	["Head south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}, north of the {area:2160}."] = "向南经过{area:421}进入{area:1276}隧道；出口在石爪山的{area:461}，{area:2160}北边。",
	["Hearth back to {area:150} if you bound at the {area:2104}, or walk west along the road into Menethil: {npc:2096} by the road in at the north gate, {npc:2111} and {npc:1480} at the inn, {npc:2086} in the keep, {npc:2094} on the west side by the docks, {npc:1242} on the pier north of the inn."] = "如果你把炉石绑在{area:2104}，就用炉石回{area:150}；否则沿路向西走进米奈希尔：{npc:2096}在北门进城的路边，{npc:2111}和{npc:1480}在旅店，{npc:2086}在要塞，{npc:2094}在西侧码头旁，{npc:1242}在旅店北边的栈桥上。",
	["Keep {npc:4276} alive while he mines, below ground"] = "在地下采矿时护住{npc:4276}不死",
	["South from {npc:3987}'s camp, {area:415} is on the way west: {npc:3691} in the inn, {npc:3894} inside the building beyond it."] = "从{npc:3987}的营地往南，{area:415}就在西行路上：{npc:3691}在旅店，{npc:3894}在旅店后面那栋建筑里。",
	["The tram comes in at the {object:28027}; walk west to the {object:2098}. {npc:376} is in the Cathedral of Light."] = "矿道地铁到站在{object:28027}；向西走到{object:2098}。{npc:376}在光明大教堂。",
	["The tram comes in at the {object:28027}; walk west to the {object:2098}: {npc:1646} stands at its east side. (The route hands his letter in at the end of 03-loch-modan; this is for a character still carrying it.)"] = "矿道地铁到站在{object:28027}；向西走到{object:2098}：{npc:1646}站在它东侧。（路线会在03-loch-modan结尾交掉他的信；这一条是给身上还带着信的角色。）",
	["{npc:3691}: {quest:990}, from {area:442}"] = "{npc:3691}：{quest:990}，来自{area:442}",
	["{npc:4276}'s defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone.\n{npc:4276} mines at the bottom of the {area:2160} at the east end of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails."] = "这个等级单做{npc:4276}的防守很难：建议组队，找人一起做。如果只有一个人就跳过。\n{npc:4276}在{area:2160}底部、峭壁东端采矿，要穿过那里的狗头人（19-23级）。跟他对话，然后在他采矿的五分钟里保住他：十来只甚至更多狗头人会一波波扑向他，先是近战，再是施法者，矿里的狗头人还会刷新加入战斗。他一死任务就失败。",
}

G["forever/alliance/06-wetlands"] = {
	["Alexston's reply, if you still carry it (the route hands it in on 03-darkshore-return's first {area:442} stop)"] = "亚历克斯顿的回信，如果你还带着（路线会在03-darkshore-return第一次停靠{area:442}时交掉）",
	["Cast {spell:18960}. With both half pendants in your bags, stand by the {area:2362} on the north-west shore of the lake and use a half to join them, then go to {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}。两半吊坠都在背包里后，站到湖西北岸的{area:2362}旁，用其中一半把它们合起来，再去{area:2361}找{npc:11802}。{npc:11802}在他建筑的楼上：从里面上楼，箭头分不清楼层。",
	["Fen Creepers along the river"] = "沿河的沼泽爬行者",
	["Hearth back to {area:150} if you bound at the {area:2104}, or walk west along the road: {npc:2104} stands on the top floor of {area:2103}, {npc:1217} in the {area:2104} south of it, {npc:2094} by the docks on the way to the boat."] = "如果你把炉石绑在{area:2104}，就用炉石回{area:150}；否则沿路向西：{npc:2104}站在{area:2103}的顶层，{npc:1217}在它南边的{area:2104}，{npc:2094}在去坐船路上的码头旁。",
	["North from the dig into the Dragonmaw camp: click the four sets of Attack Plans. The {zone:1455} plan lies at the camp's west end, the other three further east. {npc:2091}, an elite, stands apart to the south-east: {quest:98221} doesn't need him."] = "从挖掘场向北进入龙喉营地：点击四份进攻计划。{zone:1455}的计划在营地西端，另外三份在更东边。精英{npc:2091}独自站在东南边：{quest:98221}不需要他。",
	["North-west from {npc:2093} to the river: Fen Creepers hide in its pools and along its banks all the way west to {area:1024}. Work west along it until you have twelve, then back east to {npc:1244}.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "从{npc:2093}向西北到河边：沼泽爬行者藏在水潭里、沿岸一路向西到{area:1024}都有。沿河往西杀，凑够十二只，再往东回{npc:1244}。\n小心：脱战后沼泽爬行者会时不时施放潜行，因此处于潜行状态、很难发现。",
	["Optional: {npc:3848} also offers {quest:1012}, three level 32 druids deep in {area:432}, a cave of quickly respawning, stealthed mobs, and back to her afterwards. It is above your level here: take it only if you are grouped or want the extra XP; the guide doesn't need it."] = "可选：{npc:3848}还会给{quest:1012}，要深入{area:432}对付三名32级德鲁伊，那是个怪刷新很快、还有潜行怪的洞穴，之后再回来找她。在这里它超出你的等级：只在组了队或想要额外经验时接，本指南不需要它。",
	["South-east along the road to {area:415}: {npc:3691} in the inn, the flight master at the west end."] = "沿路向东南到{area:415}：{npc:3691}在旅店，飞行管理员在西端。",
	["Take {quest:5061} from {npc:11802}, upstairs in his building. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}."] = "到{npc:11802}建筑的楼上接{quest:5061}。然后{area:2361}的{npc:11800}会把德鲁伊直接飞送到{area:702}。",
	["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it.\nGoaz Warders (elite, 32) stand among the relics and the {object:331}: pull them away one at a time, or work around them."] = "圣物就在挖掘场里。{npc:1353}是一只大型刺喉龙，在挖掘场西边不远的迅猛龙山谷中徘徊。\n戈阿兹守卫者（32级精英）守在圣物和{object:331}之间：一次拉一只出来，或绕开它们。",
	["The three druids are inside {area:432}, apart from each other: go in at its mouth, south of the Forsaken camp, not over the hill above them. {npc:3940} is in the eastern halls, {npc:3941} deepest down at the north-east end and {npc:3942} at the western end.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight."] = "三名德鲁伊都在{area:432}里，彼此分开：从洞口进入，就在被遗忘者营地南边，别翻他们上方的山丘。{npc:3940}在东边的厅堂，{npc:3941}在最深处、东北端，{npc:3942}在西端。\n小心：巢穴里有很多刷新很快的怪，包括潜行的亡灵和巡逻队，所以战斗时经常会有额外的怪加入。",
	["{area:432}'s entrance"] = "{area:432}的入口",
	["{item:15885}: join the halves at the {area:2362}"] = "{item:15885}：在{area:2362}把两半合起来",
	["{npc:1217}, in the {area:2104}"] = "{npc:1217}，在{area:2104}里",
	["{npc:3649} stands at the north end of {area:442}."] = "{npc:3649}站在{area:442}北端。",
	["{npc:3691} and {npc:3961} are in the inn; {npc:3894} is inside the building just south of it."] = "{npc:3691}和{npc:3961}在旅店；{npc:3894}就在旅店南边那栋建筑里。",
	["{npc:3693} stands by the flight master."] = "{npc:3693}站在飞行管理员旁。",
	["{npc:3894}, inside the building south of the inn"] = "{npc:3894}，在旅店南边的建筑里",
	["{npc:3961}, in the inn"] = "{npc:3961}，在旅店",
	["{quest:98246}: the Razormaw eggs, on the same loop"] = "{quest:98246}：刺喉龙蛋，在同一圈环路中",
}

G["forever/alliance/30-40/01-hillsbrad-foothills"] = {
	["Beat {npc:4961} and his thugs: they give up"] = "打倒{npc:4961}和他的打手：他们会投降",
	["Maddened Rotclaws roam the {area:1025} around {npc:1244}; one of them drops the flesh. {npc:1244} takes the quest only with {quest:98283}'s head too."] = "狂暴的腐爪怪在{area:1025}、{npc:1244}周围游荡；其中一只会掉落肉。{npc:1244}只有连{quest:98283}的头一起带来才收任务。",
	["North along the road from {area:205} towards the {area:880}: Ebenezer Rustlocke's corpse lies under the span. Rustlocke's parchment goes back to {npc:1075}.\nTwo elite Dark Iron Saboteurs stand by the corpse inside the span: pull them one at a time, or loot the corpse and run out."] = "从{area:205}沿路向北朝{area:880}走：伊贝尼瑟·拉斯洛克的尸体就在桥下。拉斯洛克的羊皮纸要交还给{npc:1075}。\n两名精英黑铁破坏者守在桥下尸体旁：一次拉一只，或者拾取尸体后直接跑出去。",
	["North along the road to {area:205}. {npc:1071} and {npc:1075} stand together in the dwarves' camp on the east side of the road; the {object:147516} ruins west of it are full of elites."] = "沿道路向北到{area:205}。{npc:1071}和{npc:1075}一起站在路东侧的矮人营地；它西边的{object:147516}废墟里尽是精英怪。",
	["Off the boat, walk up the pier into town: {npc:2711} and Lieutenant Farren stand by the inn, {npc:2430} upstairs, {npc:2382} east of it; the flight master is at the north end, {npc:2381} and {npc:2438} between her and the inn, Maleb in the town hall at the west side.\n{npc:2366} may not offer {quest:98463} on Forever: if she doesn't, skip it."] = "下船后沿码头走进镇子：{npc:2711}和法尔林·奥里涅尔中尉站在旅店旁，{npc:2430}在楼上，{npc:2382}在旅店东边；飞行管理员在北端，{npc:2381}和{npc:2438}在她和旅店之间，赫尼·马雷布镇长在西侧的市政厅。\n在无限中{npc:2366}可能不提供{quest:98463}：如果没有，就跳过。",
	["Over the {area:880}: the Dark Irons' cache of explosives sits by its Arathi end."] = "过了{area:880}：黑铁矮人的炸药储藏点就在它靠阿拉希的一端。",
	["Razormaw nests"] = "刺喉龙巢穴",
	["South-west from the Syndicate camp to the {area:286} farms."] = "从辛迪加营地往西南到{area:286}的农田。",
	["The Perfect Razormaw Eggs for {quest:98246} lie in the raptors' nests in the hills around {quest:98283}."] = "供{quest:98246}用的完美刺喉龙蛋就在{quest:98283}周围山丘里迅猛龙的巢穴中。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. The {npc:271481} is held at the far west end of the {object:147516} ruins, past level 27-30 elite dwarves, and {npc:1364} (34, elite) can be among them. Lead it east out of the ruins, then hand it in to {npc:1072} in the camp. Skip it if you are alone."] = "这些都是精英怪：建议组队，找人一起做。{npc:271481}被关在{object:147516}废墟的最西端，路上有27-30级的精英矮人，{npc:1364}（34级精英）也可能混在其中。把它向东带出废墟，再到营地里交给{npc:1072}。如果只有一个人就跳过。",
	["Use the {item:279386} at the {area:287} council."] = "在{area:287}议会处使用{item:279386}。",
	["With {quest:98283}'s head and the flesh"] = "带上{quest:98283}的头和肉",
	["{area:287} council"] = "{area:287}议会",
	["{npc:2438} makes a yeti fur cloak for anyone who brings a {item:3719} ({skill:165}) and a {item:2997} ({skill:197}); no vendor sells either, so this step shows only when you carry both."] = "只要带来{item:3719}（{skill:165}）和{item:2997}（{skill:197}），{npc:2438}就会做一件雪人毛皮披风；商人都不卖这两样，所以只有两样都带在身上时本步骤才会显示。",
	["{npc:2438}, between the flight master and the inn: he wants a {item:3719} and a {item:2997} too"] = "{npc:2438}，在飞行管理员和旅店之间：他还要{item:3719}和{item:2997}",
	["{npc:251493} stands north-west of the flight master, on the way north to the yeti cave.\n{quest:98059}: {npc:251493} hands you a {item:279386} for the {area:287} council, in the farms west of {area:271}; you deliver it after the Syndicate camp."] = "{npc:251493}站在飞行管理员西北边，在北上去雪人洞穴的路上。\n{quest:98059}：{npc:251493}会给你一份{item:279386}，送给{area:271}西边农田里的{area:287}议会；去过辛迪加营地后再去交。",
	["{npc:4455}, by the keep's door: for {quest:1132} in Theramore, in the next guide"] = "{npc:4455}，在要塞门口：为下一份指南里塞拉摩的{quest:1132}",
	["{quest:98246}: the eggs"] = "{quest:98246}：刺喉龙蛋",
}

G["forever/alliance/30-40/02-desolace"] = {
	["Burning Blade Adept"] = "火刃专家",
	["Burning Blade Augur"] = "火刃预言师",
	["Burning Blade Felsworn"] = "火刃魔仆",
	["Burning Blade Reaver"] = "火刃劫掠者",
	["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building. {npc:5642} wants four of each kind of cultist on the way."] = "她的哥哥{npc:5643}（36级）和火刃氏族的祭司（30-33级）在要塞里巡逻：单独把他拉出来。{npc:13019}把权杖放在要塞的主建筑里。{npc:5642}要路上每种祭司各四只。",
	["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702}: it becomes a tamed kodo that follows you. Walk it back to {npc:11596}'s camp; there, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom."] = "对老迈的科多兽、濒死的科多兽或{npc:4702}使用{npc:11596}的{item:13892}：它会变成跟着你的驯服科多兽。把它牵回{npc:11596}的营地；到了那里跟科多兽对话：这样才算数，也才能驯下一只。共五只科多兽，一次一只；老迈的科多兽也会掉皮，在墓地周围捕猎的斯科尔帕什鞭笞者身上带着毒液。",
	["on an Aged, Dying or {npc:4702} in the graveyard; don't kill it"] = "在墓地里，对老迈的科多兽、濒死的科多兽或{npc:4702}使用；别杀死它",
	["the tamed kodo, at {npc:11596}'s camp: talk to it, five times"] = "在{npc:11596}的营地跟驯服的科多兽对话，共五次",
	["{npc:5642}: the Burning Blade in {area:599}, where her search leads"] = "{npc:5642}：{area:599}的燃烧之刃，正是她搜寻的目标",
}

G["forever/alliance/30-40/03-ashenvale"] = {
	["Crystalized Scale, from the Saltstone Basilisks: eight for {npc:4078} in {zone:1453}"] = "水晶鳞片，由盐石蜥蜴掉落：八个，交给{zone:1453}的{npc:4078}",
	["From the raceway follow the road south out of the {area:439} into {zone:1446}."] = "从赛道沿路向南出{area:439}进入{zone:1446}。",
	["Tapoke Jahn (34) slips out of the tavern once you take {quest:1248}: stay close behind him. He turns on you outside, a friend joins him, and he gives up once badly hurt. If you lose him the quest fails: abandon it and take it again from {npc:4963}."] = "接了{quest:1248}后，塔伯克·贾恩（34级）会溜出酒馆：紧跟在他后面。到了外面他会翻脸，还有个同伙加入，等他伤重就会投降。跟丢了任务就失败：放弃它，再找{npc:4963}重接。",
	["The canyons east of {area:482}"] = "{area:482}东边的峡谷",
	["{area:976} is a short walk down the road; keep to it. {npc:7823}, the Alliance flight master, stands inside the walls."] = "沿路走一小段就是{area:976}；别离开道路。{npc:7823}是联盟飞行管理员，站在城墙里面。",
	["{npc:4456}'s next errand goes to {area:415}, off this route: leave it."] = "{npc:4456}的下一个差事要你去{area:415}，不在这条路线上：别接。",
}

G["forever/alliance/30-40/04-stranglethorn-vale"] = {
	["Back east to Nesingwary's camp on the way north to the {area:99}."] = "向东返回奈辛瓦里营地，顺路北上前往{area:99}。",
	["Level 33.2"] = "33.2级",
	["Level 33.6"] = "33.6级",
	["Short of 33.6? Keep on the Kurzen Jungle Fighters and Medicine Men around the compound's outer edge until level 33.6. Or, with a group, run the {area:796} dungeon (Library) instead."] = "没到33.6级？继续在营地外围打库尔森丛林战士和库尔森药草师，直到33.6级。或者组队去刷{area:796}副本（图书馆）代替。",
	["Take the road north; the camp sits in the hills to the west.\n{npc:738} spends most of his time at the top of the {area:99}'s path, by the huts, and now and then walks down it to the road and back (about eight minutes). If he isn't at the arrow, look along that path."] = "沿路向北；营地在西边的山丘里。\n{npc:738}大部分时间待在{area:99}小径顶端、小屋旁，偶尔沿小径下到路上再折返（约八分钟）。如果他不在箭头处，就沿那条小径找找。",
	["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents. {quest:200}'s records lie in a hut on the compound's west side."] = "库尔森叛军占据{area:99}东边的营地；在外围活动，那里有库尔森丛林战士和库尔森药草师，并拾取帐篷旁的补给箱。{quest:200}的档案在营地西侧的一间小屋里。",
	["The jungle's quests climb to 37 from here: short of 33.2? Keep on the Stranglethorn Tigers in the hills just south and west of the camp until level 33.2. Or, with a group, run the {area:796} dungeon (Library) instead."] = "从这里开始丛林的任务升到37级：还没到33.2级？继续在营地南边和西边不远的山丘里打荆棘谷猛虎，直到33.2级。或者组队去刷{area:796}副本（图书馆）代替。",
	["The road to {area:608}"] = "前往{area:608}的路",
	["The strongbox is deeper in, by the cave: on the northern loop (04b)"] = "保险箱在更深处、洞穴旁：在北部环线（04b）",
	["{npc:4078} is in the {object:2164}, in the {object:2101}."] = "{npc:4078}在{object:2101}的{object:2164}里。",
	["{npc:469}: {quest:200}'s records lie at the edge of {area:101}, next"] = "{npc:469}：{quest:200}的档案在{area:101}边缘，接下来",
	["{npc:738} spends most of his time at the top of the {area:99}'s path, by the huts, and now and then walks down it to the road and back (about eight minutes). If he isn't at the arrow, look along that path."] = "{npc:738}大部分时间待在{area:99}小径顶端、小屋旁，偶尔沿小径下到路上再折返（约八分钟）。如果他不在箭头处，就沿那条小径找找。",
	["{npc:770}: for {npc:773} in {area:35}, later in this guide"] = "{npc:770}：留给{area:35}的{npc:773}，本指南后面会用到",
	["{object:287}, in the hut"] = "{object:287}，在小屋里",
}

G["forever/alliance/30-40/04b-stranglethorn-vale"] = {
	["In the {object:2164}, if you still carry it"] = "在{object:2164}里，如果你身上还带着它",
}

G["forever/alliance/30-40/05-arathi-highlands"] = {
	["East from {area:327} through the southern hills: {npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "从{area:327}向东穿过南部丘陵：食人魔法师{npc:2793}占据着枯木巨魔山谷南端的洞穴。",
	["Hay Weevils crawl about the north end of {quest:681}'s farm: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "干草象鼻虫在{quest:681}农场北端爬动：用{npc:217412}的昆虫学入门工具包里的工具抓住一只。",
	["Off the flight, straight to the {area:271} inn."] = "下飞机后，直奔{area:271}的旅店。",
	["South down the road to {npc:5476}, on the way west out of the swamp."] = "沿路向南到{npc:5476}处，就在向西离开沼泽的路上。",
	["South-west from {npc:2793}'s cave to the {area:880}: {npc:2696} stands on a broken section of the bridge; jump down to him from its north end. {quest:647} must reach {npc:2705} in {area:271} within 15 minutes: go straight back to {area:320} and fly to {area:271}."] = "从{npc:2793}的洞穴向西南到{area:880}：{npc:2696}站在桥断裂的一段上；从桥的北端跳下去找他。{quest:647}必须在15分钟内送到{area:271}的{npc:2705}：直接返回{area:320}，再飞往{area:271}。",
	["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up."] = "破碎岭食人魔占据着{area:280}以北的山丘。再往北，一个破旧的木箱里装着{item:3706}；{quest:537}的{npc:2320}就站在旁边。\n破碎岭重击者、破碎岭法师、破碎岭执行者和破碎岭好战者（36-39级）是精英；破碎岭食人魔和破碎岭蛮兵（34-35级）不是精英，也会掉落指骨：一次拉一只，或者组队。",
	["The Syndicate hold the farm north-west of {area:320}.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "辛迪加占据着{area:320}西北的农场。\n注意：辛迪加路霸是30-31级，能在脱战时施放潜行，因此常常处于潜行状态，很难发现。",
	["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and carry the tomes too: pull one at a time, or group up."] = "典籍在{area:280}以西的废弃堡垒里；阿古斯暗影法师占据着废墟。\n注意：破碎岭好战者血量降到一半以下后，会呼叫15码内的附近盟友。\n破碎岭重击者、破碎岭法师、破碎岭执行者和破碎岭好战者（36-39级）是精英；破碎岭食人魔和破碎岭蛮兵（34-35级）不是精英，也会携带典籍：一次拉一只，或者组队。",
	["To {area:144}"] = "前往{area:144}",
	["West along the road from {npc:5391}'s strongbox to the {area:657}."] = "沿路向西，从{npc:5391}的保险箱前往{area:657}。",
	["West along the road to {area:320}, on the way to the {object:2689}."] = "沿路向西到{area:320}，顺路前往{object:2689}。",
	["{npc:1776}: Noboru's cudgel"] = "{npc:1776}：诺博鲁的木棒",
	["{npc:2277}: the parchment"] = "{npc:2277}：羊皮纸",
	["{npc:2438} stands between the flight master and the inn; {npc:2381} beside him sells {item:2321} if you have none."] = "{npc:2438}站在飞行管理员和旅店之间；他身旁的{npc:2381}出售{item:2321}，没带的话可以买。",
	["{npc:2789}: {npc:2793}'s cave comes after {area:327}"] = "{npc:2789}：{npc:2793}的洞穴在{area:327}之后",
	["{npc:5476} guards the road junction in the west of the swamp. {npc:217412} stands a short way north of him.\n{npc:217412} may not be here on Forever: if {npc:217412} doesn't offer {quest:93176}, skip it."] = "{npc:5476}守卫着沼泽西部的路口。{npc:217412}在他北边不远处。\n在无限中{npc:217412}可能不在这里：如果{npc:217412}没有提供{quest:93176}，就跳过。",
	["{npc:5677}, at the summoning circle"] = "{npc:5677}，在召唤法阵处",
}

G["forever/alliance/30-40/06-badlands"] = {
	["South-west into the gulches: only the Greater Rock Elementals there drop the bracers."] = "向西南进入沟壑：只有那里的巨型石元素掉落护腕。",
	["{npc:2920}, beside {npc:2921}, trades for {item:2868}, a blacksmith's craft: this step shows only when you carry a pair."] = "{npc:2920}就在{npc:2921}旁边，用{item:2868}（锻造做的）交易：只有你身上带着一对时，这一步才会显示。",
}

G["forever/alliance/40-50/01-stranglethorn-vale"] = {
	["Alone, you skip Nesingwary's three elite hunts: take their experience from the Skullsplitter trolls of Zul'Mamwe instead, just east of the mine, so every kill also counts for {npc:737}'s tusks. Or, with a group, run the {area:1517} dungeon instead."] = "独自一人时，跳过奈辛瓦里的三场精英狩猎：改从矿洞正东边祖玛维废墟的劈颅巨魔身上补回经验，这样每次击杀也顺带完成{npc:737}要的獠牙。或者组队去刷{area:1517}副本代替。",
	["An {npc:217588} crawls in the jungle south-east of Nesingwary's camp, on the way to the {area:99}: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "一只{npc:217588}在奈辛瓦里营地东南边的丛林里爬行，就在去{area:99}的路上：用{npc:217412}的昆虫学入门工具包里的工具抓住一只。",
	["Level 42.16 at Zul'Mamwe"] = "在祖玛维废墟升到42.16级",
	["Ride east out of {zone:1426} through the tunnel into {zone:1432} and on along the road to {area:144}."] = "向东骑出{zone:1426}，穿过隧道进入{zone:1432}，再沿路前往{area:144}。",
	["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale."] = "向东北骑行经过奈辛瓦里营地，再沿路向北到山谷顶端的营地。",
	["Seahorn now offers {quest:604}: leave it. Its three captains are level 45-48 with crews around them, and the route brings you back to Seahorn at 48 for it."] = "海角现在提供{quest:604}：先跳过。它的三名船长是45-48级，身边还有船员，路线会在48级时带你回到海角这里做这个任务。",
	["Still short of level 42.16 after the hunts you did? Make up the rest on the Cold Eye Basilisks by the {area:310}, on your way south to {area:35}. Or, with a group, run the {area:1517} dungeon instead."] = "做完狩猎后还没到42.16级？在{area:310}旁的冷眼蜥蜴身上把剩下的经验补上，顺路南下前往{area:35}。或者组队去刷{area:1517}副本代替。",
	["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house. Jarl wants three {quest:1218}: if you passed {npc:4897}, buy them from her in Theramore first."] = "沿道路向北前往废弃的庄园；加尔住在旁边的棚屋里，松土就在房子的拐角处。加尔要三份{quest:1218}：如果你路过{npc:4897}，先在塞拉摩向她买好。",
	["The Jungle Stalkers roam the slopes west of the mine."] = "丛林捕猎者在矿洞西边的山坡上游荡。",
	["The boat leaves from Theramore: report to {npc:4944} on the top floor of {area:514} on the way to the docks."] = "船从塞拉摩出发：去码头的路上，先到{area:514}顶层向{npc:4944}报到。",
	["{npc:1470} is below ground in {area:144}, by the inn. His mushrooms grow in the {area:1517} dig in the {zone:1418}; the next guide takes you there and back through {area:144}."] = "{npc:1470}在{area:144}的地下、旅店旁。他的蘑菇长在{zone:1418}的{area:1517}挖掘场里；下一份指南会带你经{area:144}往返那里。",
}

G["forever/alliance/40-50/02-badlands"] = {
	["Back through the pass: the Stonevault troggs dig outside {area:1517} at the {zone:1418}' northern edge. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "折返穿过山口：石穹穴居人在{zone:1418}北缘的{area:1517}外挖掘。雕花瓮和紫红色蘑菇簇就在他们的洞穴和隧道里，位于副本之外。",
	["Ride north through the pass into {zone:1432} and east along the south shore to Ironband's camp."] = "向北穿过山口进入{zone:1432}，再沿湖南岸向东骑到铁环挖掘场的营地。",
	["Ride west along the loch to {area:144}."] = "沿湖向西骑到{area:144}。",
}

G["forever/alliance/40-50/03-feralas"] = {
	["Coming from the south: {npc:7877} and {npc:7878} first, then {npc:7900} beside {npc:7880}'s building, then the stairs. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:7852} is by the flight master, on the way out."] = "从南边过来：先找{npc:7877}和{npc:7878}，再找{npc:7880}那栋楼旁的{npc:7900}，然后上楼梯。{npc:7880}站在他那栋楼的楼上：从里面上楼，箭头分不清楼层。{npc:7852}在飞行管理员旁边，出去时顺路。",
	["No {quest:7735} yet? Keep killing the Rage Scar yetis until one drops, then right-click it."] = "还没拿到{quest:7735}？继续击杀怒痕雪人，直到掉落一个，然后右键点击它。",
	["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide, and about one in thirty a {quest:7735}, which {npc:7852} pays for too.\n{npc:14637}'s quests on the coast need level 45: grind the yetis here until level 44.5, so the kills also bring {npc:7852}'s hides. Or, with a group, run the {area:978} dungeon instead."] = "沿路向西骑回，再向北进入怒痕山丘。这里的每只雪人都会掉落毛皮，大约三十只里有一只会掉{quest:7735}，{npc:7852}也会收购。\n{npc:14637}在海边的任务需要45级：在这里刷雪人直到44.5级，这样击杀也能顺带拿到{npc:7852}要的毛皮。或者组队去刷{area:978}副本代替。",
}

G["forever/alliance/40-50/04-tanaris"] = {
	["\"Sea Wolf\" MacKinley in {area:35}: the route takes you there at the end of the {zone:1425} guide, keep it"] = "“海狼”马克基雷在{area:35}：路线会在{zone:1425}指南结尾带你去那里，先留着",
	["Ride back west to {area:976}: {npc:11758} stands on the east side of town, where you come in."] = "向西骑回{area:976}：{npc:11758}站在镇子东边，也就是你进来的地方。",
}

G["forever/alliance/40-50/05-the-hinterlands"] = {
	["Captain Keelhaul"] = "尼哈鲁船长",
	["Captain Stillwater"] = "斯蒂沃特船长",
	["Fleet Master Firallon"] = "舰队指挥官菲尔拉伦",
	["Set your hearth here: the {zone:1427} guide starts from {area:144}."] = "把炉石绑定在这里：{zone:1427}指南从{area:144}开始。",
	["The three Bloodsail ships lie at anchor off the coast just south of {area:35}: {npc:2550} (45) and {npc:2548} (46) on the nearer decks, {npc:2546} (48) on the flagship, each with a crew of 42-45 pirates. Swim out, clear each deck from the edge and pull one at a time."] = "三艘血帆船停泊在{area:35}南边不远的近海：{npc:2550}（45级）和{npc:2548}（46级）在较近的甲板上，{npc:2546}（48级）在旗舰上，每人身边都有42-45级的海盗船员。游过去，从边缘开始逐层清理甲板，一次拉一只。",
}

G["forever/alliance/40-50/06-searing-gorge"] = {
	["Dorius stands by the road beside the {area:247}. Escort him north-east to {area:1959} and keep him alive; when it is over, read the {object:175704} he leaves on the road."] = "多里乌斯站在{area:247}旁的路边。护送他向东北到{area:1959}并保住他的命；结束后阅读他留在路上的{object:175704}。",
	["Heavy War Golems patrol the floor of the Cauldron below {npc:8479}; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "重型战争傀儡在{npc:8479}下方的火山口地面上巡逻；岩浆元素在它们之间游荡。傀儡和元素掉落油，元素掉落心脏。",
	["Ride west along the north of the Gorge to {area:1446}, the scaffolded camp on the north-west rim."] = "沿峡谷北部向西骑到{area:1446}，那是西北边缘搭着脚手架的营地。",
	["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "监工和奴隶贩子驱赶着奴隶遍布火山口，他们中的任何一个都可能携带{item:10551}。蒸汽铁匠在中央的熔炉干活（{item:18959}），瞭望员站在南边的山脊上（望远镜）。任何{object:147516}都可能掉落{item:11818}：留着。\n注意：黑铁奴隶贩子（45-46级）被拉时向15码内的盟友求援，还会从最多15码外撒网，并在近战中使用撕裂。",
	["The spiders roam the plateaus and lava pools south of {npc:8436}, on the way to {npc:8479}."] = "蜘蛛在{npc:8436}以南的高地和熔岩池出没，就在去{npc:8479}的路上。",
	["{npc:8479} stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "{npc:8479}站在{area:1446}南边的大熔炉边缘。听他讲述他的故事。",
	["{object:147516} dwarves: kill these as you meet them"] = "{object:147516}矮人：遇到这些就杀",
}

G["forever/alliance/40-50/07-un-goro-crater"] = {
	["{npc:7312}, the mage trainer: for {npc:8395} in {zone:1447}, keep it"] = "法师训练师{npc:7312}：交给{zone:1447}的{npc:8395}，先留着",
}

G["forever/alliance/50-60/01-burning-steppes"] = {
	["Back up through {npc:8395}'s teleport."] = "通过{npc:8395}的传送门返回上面。",
	["Get off your mount before you talk to {npc:8395}: he teleports you up to {npc:8379}'s tower on the cliff above his camp."] = "和{npc:8395}交谈前先下坐骑：他会把你传送到营地上方悬崖上{npc:8379}的塔楼。",
	["Ride back west to {npc:8395}'s camp and get off your mount: he teleports you up to Xylem again."] = "向西骑回{npc:8395}的营地并下坐骑：他会再次把你传送到大法师克希雷姆那里。",
	["The Spitelash Sirens wander the ruins and the beach around the {area:1223}, just south of {npc:8395}. Only the Sirens carry the coral, not the Screamers."] = "恶鞭海妖在{npc:8395}南边、{area:1223}周围的废墟和海滩游荡。只有海妖携带珊瑚，尖啸者不掉。",
	["The apprentice at the top of the tower sends you back down."] = "塔顶的学徒会把你送回下面。",
	["The blood elves are at the {area:1220}, on the way to {npc:8420}"] = "血精灵在{area:1220}，就在去{npc:8420}的路上",
	["Xylem's last task, Destroy Morphaz, is in the {area:1417}: skip it."] = "克希雷姆的最后一个任务“消灭摩弗拉斯”在{area:1417}里：跳过。",
	["{item:20028}, from the blood elf surveyors and reclaimers"] = "{item:20028}，由血精灵勘测员和搜寻者掉落",
}

G["forever/alliance/50-60/02-felwood"] = {
	["Step into the cave: {npc:11558} stands just inside."] = "走进洞穴：{npc:11558}就站在入口内。",
	["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. Keep killing them until one drops a {quest:8470}, about one kill in thirty, then right-click it: {npc:11558} in {area:1769} takes it once the Timbermaw are Neutral to you, now if they already are, or when the last guide passes the cave again at 58.\nCareful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%."] = "{area:1762}的死木熊怪遍布洞穴以西的丘陵。继续击杀它们，直到掉落一个{quest:8470}，大约三十只掉一个，然后右键点击它：等木喉熊怪对你达到中立后，{area:1769}的{npc:11558}才会收；如果已经中立，现在就交，否则等最后一份指南在58级再次经过洞穴时再交。\n小心：巢穴守卫是53-54级；血量低于50%后，它们会呼叫25码内的盟友，低于15%时会跑去求援。",
	["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}."] = "在{area:1763}中央被腐蚀的月亮井旁使用{item:12922}。",
	["{area:1763} is the ruined temple north of the glen."] = "{area:1763}是山谷北边的废弃神庙。",
}

G["forever/alliance/50-60/03-winterspring"] = {
	["Any Winterfall furbolg can drop the totem, about one kill in thirty: if the top-up did not bring one, keep killing them here until it drops, then right-click it."] = "任何冬泉熊怪都可能掉落图腾，大约三十只掉一个：如果补充经验时没掉，就在这里继续击杀，直到掉出来，然后右键点击它。",
	["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it.\nCareful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "{area:2264}周围、礼拜堂西边的天灾军团会掉落两种天灾石；达隆郡居民的灵魂会从它们身上升起：和每一个交谈以解放它。\n小心：{npc:10411}脱离战斗时会隐形，战斗开始后会召唤岩翼石像鬼。它们只有3只，每15分钟刷新一次。",
	["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten: it comes within the kills these quests need) and a {quest:8471} (about one in thirty: it comes within the top-ups): right-click whichever drops. Keep the {item:14047} the furbolgs drop for Meilosh.\nThe rest of {zone:1452}'s work is level 55-58: stay on this camp until level 54, so your first kills also count for {npc:9298} and {npc:11556}. Or, with a group, run the {area:1584} dungeon instead."] = "西边的冬泉熊怪营地在{npc:11556}和{npc:9298}之间的山丘里。这里的任何熊怪都可能掉落{item:12771}（约十只掉一个：这些任务需要的击杀数里就够）和{quest:8471}（约三十只掉一个：补充经验时就能凑到）：掉哪个就右键点击哪个。把熊怪掉落、留给梅罗什的{item:14047}留好。\n{zone:1452}其余的任务是55-58级：在这个营地刷到54级，这样最初的击杀也同时算进{npc:9298}和{npc:11556}的任务。或者组队去刷{area:1584}副本代替。",
	["Top up here to level 55.05 before the hand-ins at {area:2255}: they take you to level 56. Grind the Winterfall furbolgs camped by {area:2246} (Pathfinders, Totemics, Den Watchers): killing them raises your Timbermaw reputation, which the quests here and the walk through {area:1769} need, one of them drops the {quest:8471}, and they fill your bags with the thirty Runecloth Meilosh asks for. Or, with a group, run the {area:1584} dungeon or the {area:1583} dungeon (Lower) instead."] = "在{area:2255}交任务前，先在这里刷到55.05级：交完能到56级。刷扎营在{area:2246}旁的冬泉熊怪（探路者、图腾师、巢穴守卫）：杀它们能提升木喉声望，这里的任务和穿过{area:1769}的路程都用得上；其中一只会掉落{quest:8471}，还能让你背包里装满梅罗什要的三十块符文布。或者组队去打{area:1584}或{area:1583}（下层）副本代替。",
}

G["forever/alliance/50-60/04-western-plaguelands"] = {
	["Coming in from {zone:1451}, {area:543} is just inside the crater: {npc:10302} the goblin sits by the water."] = "从{zone:1451}进入，{area:543}就在环形山入口内：地精{npc:10302}坐在水边。",
	["Lead {npc:7774} back to {npc:7765} at walking pace: she wanders off, so ring the bell to call her back (not in combat), and clear the harpies on the way before she reaches them."] = "以步行速度把{npc:7774}带回{npc:7765}处：她会走开，脱战时摇铃把她叫回来，并在她走到鹰身人那里之前先清理沿途的鹰身人。",
	["No {quest:5401} yet ({spell:437801} gives it on the {zone:1452} guide's way through)? Pureheart gives you one here: the scourgestone quests need it."] = "还没拿到{quest:5401}（{spell:437801}会在{zone:1452}指南途经时给予）？纯心会在这里给你一个：天灾石任务需要它。",
	["Ride back to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "骑回{area:3425}。{npc:15189}站在他那座建筑的楼上：从里面上楼，箭头分不清楼层。",
	["Ride on west to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "继续向西骑到{area:3425}。{npc:15189}站在他那座建筑的楼上：从里面上楼，箭头分不清楼层。",
	["Ride out of the crater's north-western pass into {zone:1451}: {npc:13220} stands at {area:3077}, where the pass comes out."] = "从环形山西北的山口骑出，进入{zone:1451}：{npc:13220}站在山口出口处的{area:3077}。",
	["The giant {npc:7765} sits just north-west of {npc:7775}'s camp."] = "巨人{npc:7765}就在{npc:7775}营地西北边不远处。",
	["The pelts come from the gorillas on {area:1943}"] = "毛皮来自{area:1943}的猩猩。",
	["{npc:9619} camps at the foot of the ramp into the crater."] = "{npc:9619}在通往环形山的坡道脚下扎营。",
}

G["forever/alliance/50-60/06-silithus"] = {
	["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber. The succubus {npc:9518} waits on the way, with Trey Lightforge's remains beside her.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "回到{area:1770}：{npc:9861}和{npc:9860}在最深处的房间里守着{npc:9517}。魅魔{npc:9518}在路上等着，特雷·莱弗治的残骸就在她旁边。\n小心：三个首领一起作战。先清掉附近的怪，以免多拉敌人。",
	["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there. Top up here to level 59.93 before the hand-ins at {area:3197}: they take you to level 60. Or, with a group, run the {area:2057} dungeon or the {area:2279} dungeon instead."] = "过{npc:1855}东边的河进入{area:2627}。恐惧谷的幽灵在那里的树林中游荡。在{area:3197}交任务前，先在这里刷到59.93级：交完能到60级。或者组队去打{area:2057}或{area:2279}副本代替。",
	["Flint's next task goes to {zone:1453}: you are level 60 now, skip it."] = "弗林特的下一个任务要去{zone:1453}：你现在已经60级了，跳过。",
	["Lead her out of {area:1770} and keep her alive until she is outside the cave: clear the way back first."] = "把她带出{area:1770}并保护她活到洞外：先清理回程的路。",
	["Level 59.93"] = "59.93级",
	["Ride south to the {area:2260}, the farm north-west of {area:2262}. The three agents' remains are bone outlines on the ground: one by the road south of the farm, one on the hill east of the house, one on the mound in front of it. Coming close enough to see the Blightcaller in front of the house completes the scouting.\nCareful: {npc:11878} (level 62 elite) and his elite hounds stand in front of the house: take the remains on the mound from the side and do not pull him. You don't have to fight him."] = "向南骑到{area:2260}，即{area:2262}西北的农场。三名特工的遗骸是地上的白骨轮廓：一处农场南边的路旁，一处房子东边的山丘上，一处房前的小土堆上。走近到能看见房前的凋零者，侦察就算完成。\n小心：{npc:11878}（62级精英）和他的精英猎犬站在房前：从侧面拿土堆上的遗骸，别引到他。你不必和他交战。",
	["Scare {npc:10977} with {npc:10980}"] = "用{npc:10980}吓唬{npc:10977}",
	["The Deadwood totem from {area:1762}, if {npc:11558} didn't take it then."] = "{area:1762}的死木图腾，如果当时{npc:11558}没收下，就留着。",
	["The lake for {quest:5845}"] = "{quest:5845}的湖",
	["The {quest:5086}"] = "{quest:5086}",
	["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended.\nThe Jaedenar Darkweavers, Warlocks and Enforcers in here drop a {item:13140}, about one kill in thirty: keep killing them until it drops. It opens the cell of {npc:11018}, the night elf held in the cave."] = "{area:1770}是{area:1763}后方、路西的洞穴。对里面的四个火盆使用{item:12906}。顺路杀掉怒气爪熊和邪爪狼，拿{item:11172}。\n小心：洞里到处是53-55级的暗影议会怪物，常常成群联动，很多会眩晕。建议2-3人组队。\n洞里的加德纳尔暗影织者、术士和执行者会掉落{item:13140}，大约三十只掉一个：一直击杀，直到掉落。它能打开关押洞中暗夜精灵{npc:11018}的牢笼。",
	["{npc:11016}, in her cell; below ground"] = "{npc:11016}，在她的牢笼里；地下",
	["{npc:11557}, just inside the cave beside {npc:11558}, takes thirty {quest:6031} from Friendly with the Timbermaw: the {zone:1452} top-up on the Winterfall furbolgs gets you both."] = "{npc:11557}就在洞内{npc:11558}旁边，木喉熊怪声望达到友善后，会收三十个{quest:6031}：{zone:1452}刷冬泉熊怪补经验时，声望和布两样都能凑齐。",
	["{npc:11558} stands just inside the {area:1769} cave: she speaks to you from Neutral with the Timbermaw, which the Winterfall furbolgs you ground in {zone:1452} brought you to."] = "{npc:11558}就站在{area:1769}洞口内：木喉熊怪声望达到中立后她才会和你交谈，你在{zone:1452}刷的冬泉熊怪已经帮你达到了。",
	["{npc:11558}, just inside the cave: walks around here: look inside the circle on the map"] = "{npc:11558}，就在洞口内：在这一带走动，看地图圆圈内",
	["{npc:11558}: walks around here: look inside the circle on the map"] = "{npc:11558}：在这一带走动，看地图圆圈内",
	["{quest:6184}: the agents' remains lie at the {area:2260} in the {zone:1423}"] = "{quest:6184}：特工的遗骸在{zone:1423}的{area:2260}",
}

