G["forever/alliance/skyborne/01-zephras-isle"] = {
	["Back to {npc:252800} at the farmhouse."] = "回到农舍找{npc:252800}。",
	["Prideclaws and Galestriders roam the grasslands around the village. Galestriders drop both the eggs and the meat: most players get the eggs from the ones just west of the village."] = "傲爪和疾风陆行鸟在村子周围的草原上游荡。疾风陆行鸟会掉落蛋和肉：多数玩家从村子正西边那几只身上拿到蛋。",
	["{item:258771}: the Stormchasers and Footsoldiers around {npc:254151}'s camp"] = "{item:258771}：{npc:254151}营地周围的逐暴者和步兵",
	["{npc:252800}, at the farmhouse"] = "{npc:252800}，在农舍里",
}

G["forever/class/mage/staff-or-orb-alliance"] = {
	["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {quest:1860}, the {area:87} trainer's errand; {npc:5144}'s Gizmonitor and {npc:5497}'s {quest:1861} shut out each other, so you get one staff or orb. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "10级时，{area:2102}中{area:131}的法师训练师{npc:1228}派你去找{zone:1455}的{npc:5144}。接了它就无法再接{quest:1860}，即{area:87}训练师托付的差事；{npc:5144}的基兹莫尼特与{npc:5497}的{quest:1861}互相排斥，所以你只能拿到一根法杖或一颗宝珠。（若侏儒在{area:87}接了{npc:328}的任务，则改走{quest:1861}的步骤；人类若接了这一条，则走基兹莫尼特的步骤。）",
	["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {quest:1879}, the {area:131} trainer's errand; {quest:1861} and {npc:5144}'s Gizmonitor shut out each other, so you get one staff or orb."] = "10级时，狮王之傲旅店楼上的{area:87}法师训练师{npc:328}会让你去找{zone:1453}的{npc:5497}。接了它就无法再接{quest:1879}，即{area:131}训练师托付的差事；{quest:1861}与{npc:5144}的基兹莫尼特互相排斥，所以你只能拿到一根法杖或一颗宝珠。",
}

G["forever/class/paladin/cloak-of-the-divine-storm"] = {
	["Starts now at 22 at the {area:444}; its mobs are 28-30, so go nearer 30 or with a friend. Alliance only for now."] = "现在22级时在{area:444}开启；那里的怪物是28-30级，所以最好接近30级再来，或者找个同伴。目前仅限联盟。",
}

G["forever/class/paladin/holy-mightstone"] = {
	["the {quest:5401} trinket: equip it"] = "{quest:5401}饰品：装备上",
}

G["forever/class/rogue/poisons-alliance"] = {
	["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: the Auction House in the {object:2096}; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "这四样都在{zone:1453}。{item:3421}：伯纳德或{npc:1303}的花店，在{object:2096}运河旁。{item:3372}：许多杂货和炼金商人（{npc:1257}、{npc:1325}等）有售。{item:4371}：{object:2096}里的拍卖行；工程学供应商只备一件货，几乎总是售罄，工程师也可以自己做一个。{item:8431}在运河边裁缝店{object:2177}柜台左端旁的地上；只有接了这个任务才能拾取。如果不做解毒，{item:6452}（{skill:129}）或德鲁伊的{spell:526}也能解除{spell:9810}。",
}

G["forever/class/shaman/call-of-earth-alliance"] = {
	["Teo's {quest:94373} needs the {quest:98581} handed in first: {npc:658}, where you entered {area:132}, gives it to Dwarf shamans after his {quest:179}. Bring it up the road to {npc:257446} inside {area:77}."] = "特奥的{quest:94373}要先交完{quest:98581}才行：在你进入{area:132}之处等候的{npc:658}，会在你做完他的{quest:179}后把它交给矮人萨满祭司。再沿路把它带上去，交给{area:77}里的{npc:257446}。",
}

G["forever/class/shaman/call-of-water-alliance"] = {
	["{npc:5895}, beside the shrine"] = "{npc:5895}，在神龛旁",
}

G["forever/class/warrior/fire-hardened-armor"] = {
	["Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths."] = "现在20级开启，先得一面盾牌；28级得到锁甲，之后三位铁匠分别给出罩帽、护腿和护手。",
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and a {item:5996} removes the risk."] = "{quest:1708}生长在{area:150}正南的海底，鱼人小屋和一条破船旁：那里有八株，港口东南有两株，各3分钟刷新，所以要等刷新凑够20个。鱼人在水下会用网困住你：留意呼吸条，用一瓶{item:5996}即可免去这层风险。",
}

G["forever/reputation/darnassus"] = {
	["About 3,700 {faction:69} reputation from low-level quests in {zone:1438} and {zone:1439}"] = "{zone:1438}和{zone:1439}的低等级任务约给3,700点{faction:69}声望",
	["Capture a {npc:2164}"] = "捕获一只{npc:2164}",
	["Optional: the Night Elf start glade in north-east {zone:1438}, about 1,050 reputation in 30 minutes at 60. The givers stand around {area:256}, the great tree. Forever pays these old quests in full at any level. Skip this step to skip the hub."] = "可选：{zone:1438}东北的暗夜精灵起始林间空地，60级时30分钟约1,050点声望。发布任务的NPC站在大树{area:256}周围。无限中这些旧任务在任何等级都按全额发放。跳过这一步就等于跳过该枢纽。",
	["Optional: the village on the road to {faction:69}, about 1,250 reputation in 45 minutes at 60. Forever pays these old quests in full at any level. Skip this step to skip the hub."] = "可选：通往{faction:69}的路上的村庄，60级时45分钟约1,250点声望。无限中这些旧任务在任何等级都按全额发放。跳过这一步就等于跳过该枢纽。",
	["Optional: {area:442} in {zone:1439}, a boat trip from {area:702}, about 1,400 reputation in an hour at 60. The givers stand along the town's street and pier. Forever pays these old quests in full at any level. Skip this step to skip the hub."] = "可选：{zone:1439}的{area:442}，从{area:702}坐船可达，60级时一小时约1,400点声望。发布任务的NPC站在镇上的街道和码头沿线。无限中这些旧任务在任何等级都按全额发放。跳过这一步就等于跳过该枢纽。",
	["{area:186}: the {area:262}'s entrance"] = "{area:186}：{area:262}入口",
	["{npc:2164}: use {quest:2139} on it and lead it back to {npc:3701}"] = "{npc:2164}：对它使用{quest:2139}，再把它带回{npc:3701}处",
	["{quest:3803} takes 10 {item:11040} for 50, as often as you like, and pays in full at 60. The chain before it is level 50: 220. {npc:6735} sends you to {npc:3516} in the {area:1658}; he wants 20 {quest:3764}. (The innkeepers of {zone:1453} and {zone:1455} give the same start.)"] = "{quest:3803}每10个{item:11040}换50点，想做多少次都行，60级时仍给全额。它之前的任务链是50级：220点。{npc:6735}派你去{area:1658}的{npc:3516}；他要20个{quest:3764}。（{zone:1453}和{zone:1455}的旅店老板也提供同样的起点。）",
	["{quest:7801}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Night Elves start 900 higher: 88 turn-ins; Skyborne start at Neutral 500, so 7,900 away: 158, two fewer after Exploring the Alliance). {quest:4183} and the {item:11040} chain above take 8 turn-ins off, and every 10 {item:11040} you hand in counts as one more; each hub you did takes 20 to 28 more off. More quests pay {faction:69}, in full while they are no more than 5 levels below you: the rest of {zone:1439} (about 3,400 more), {area:415} in {zone:1440} (about 3,900) and Feathermoon in {zone:1444} (about 1,700). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7801}：每20个{item:14047}换50点声望，想做多少次都行。完成最初四次捐献后，人类、矮人或侏儒处于友善6,000中的700，离尊敬还差5,300点：106次交任务，2,120个{item:14047}（暗夜精灵起始高900点：88次；天裔从中立500起步，所以差7,900点：158次，完成“探索联盟”后少两次）。上面的{quest:4183}和{item:11040}任务链能抵掉8次交任务，每交10个{item:11040}又算多一次；你每做满一个枢纽能再抵20到28次。还有更多任务给{faction:69}声望，任务最多比你低5级时给全额：{zone:1439}其余部分（约3,400点）、{zone:1440}的{area:415}（约3,900点）以及{zone:1444}的羽月（约1,700点）。每获一点主城声望，也会给其他三个联盟主城四分之一（此处不计）。把所有{item:14047}一次性交完。",
}

G["forever/reputation/gnomeregan-exiles"] = {
	["About 3,000 {area:133} reputation from low-level quests in {zone:1426}, paid to {zone:1455} too"] = "约3,000点{area:133}声望来自{zone:1426}的低级任务，同时也会给{zone:1455}",
	["Optional: eastern {zone:1426}, from {npc:264936}'s camp to the {area:134} and {area:803}, about 500 reputation in 30 minutes at 60. Forever pays these old quests in full at any level. Skip this step to skip the hub."] = "可选：{zone:1426}东部，从{npc:264936}的营地到{area:134}和{area:803}，60级时30分钟约500点声望。无限中这些旧任务在任何等级都按全额发放。跳过这一步就跳过该任务点。",
	["Optional: the Dwarf and Gnome start valley south-west of {area:131}, about 1,150 reputation in 30 minutes at 60. {npc:658} and {npc:713} stand at {area:77}. Forever pays these old quests in full at any level. Skip this step to skip the hub."] = "可选：{area:131}西南的矮人与侏儒新手山谷，60级时30分钟约1,150点声望。{npc:658}和{npc:713}站在{area:77}。无限中这些旧任务在任何等级都按全额发放。跳过这一步就跳过该任务点。",
	["Optional: {area:131} and the Brewnall and {area:133} roads around it, about 1,300 reputation in 50 minutes at 60. Most givers stand in and around the {area:2102} and at {area:189} east of it. Forever pays these old quests in full at any level. Skip this step to skip the hub."] = "可选：{area:131}以及周围布瑞恩诺尔和{area:133}的道路，60级时50分钟约1,300点声望。大多数任务发布者站在{area:2102}及其周边，以及它东边的{area:189}。无限中这些旧任务在任何等级都按全额发放。跳过这一步就跳过该任务点。",
	["{quest:7812}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Night Elf stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Gnomes start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). {npc:9616}'s and {npc:9561}'s quests above take 8 turn-ins off; each {zone:1426} hub you did takes 10 to 26 more off. Outside Dun Morogh Gnomeregan pays little: {npc:4077}'s quests in Stonetalon (about 500) and {object:171524}'s {area:133} dungeon quests. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7812}：每20个{item:14047}换50点声望，想交多少次都行。四次首次捐赠之后，人类、矮人或暗夜精灵处在友善700/6,000，离尊敬还差5,300点：106次上交、2,120个{item:14047}（侏儒初始高900点：88次；天裔从中立2,000开始，差6,400点：128次，做了“探索联盟”后少两次）。上面{npc:9616}和{npc:9561}的任务能减掉8次上交；你做过的每个{zone:1426}任务点还能再减10到26次。丹莫罗以外，诺莫瑞根的声望给得很少：{npc:4077}在石爪山的任务（约500点）和{object:171524}的{area:133}副本任务。每份主城声望收益还会以四分之一的比例给其他三个联盟主城（这里未计入）。把所有{item:14047}一次交清。",
}

